window.STARTUP_CAMI_TRANSLATIONS = {"en": {"locale": "en", "categories": {"Company Purpose": "Company Purpose", "Problem": "Problem", "Situation \u0026 Trigger": "Situation \u0026 Trigger", "Pain \u0026 Impact": "Pain \u0026 Impact", "Customer \u0026 Target Persona": "Customer \u0026 Target Persona", "Users, Payers \u0026 Decision-Makers": "Users, Payers \u0026 Decision-Makers", "Current Alternative \u0026 Competitors": "Current Alternative \u0026 Competitors", "Market \u0026 Why Now": "Market \u0026 Why Now", "Unfair Advantage": "Unfair Advantage", "Evidence": "Evidence", "Customer Discovery": "Customer Discovery", "Key Assumption": "Key Assumption", "Validation \u0026 Next Experiment": "Validation \u0026 Next Experiment", "Validation Signal": "Validation Signal", "Success Criteria": "Success Criteria", "Solution \u0026 Thin Product": "Solution \u0026 Thin Product", "Technology \u0026 Design": "Technology \u0026 Design", "Customer Acquisition": "Customer Acquisition", "Activation": "Activation", "Retention": "Retention", "Instrumentation": "Instrumentation", "Business Model \u0026 Monetization": "Business Model \u0026 Monetization", "Unit Economics \u0026 Financial Projections": "Unit Economics \u0026 Financial Projections", "Growth": "Growth", "Founder Fit": "Founder Fit", "Team \u0026 Role Coverage": "Team \u0026 Role Coverage", "Human Fit \u0026 Commitment": "Human Fit \u0026 Commitment", "Decisions \u0026 Learning": "Decisions \u0026 Learning", "Questions to Avoid or Defer": "Questions to Avoid or Defer"}, "questions": {"33785cebf03ba018": {"question": "What is our company’s purpose?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A purpose statement tells investors, recruits, and the team what lasting change the company exists to create, beyond the first product it happens to sell.", "example": "Draft: help small online sellers without a designer publish complete, accurate listings so they can spend their time on customers. Then check whether each current project, from interviews to the pilot, still serves that sentence. Treat it as a working draft to revisit after evidence.", "avoid": "Avoid a slogan so broad it fits any company, such as empowering commerce for everyone.", "synthetic": true}}, "7d52bc0a0b3cb5ee": {"question": "How would we explain the venture in one sentence?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If the venture cannot fit into one sentence, listeners will remember nothing, and the team may not share the same picture of what it is building.", "example": "Try the pattern: we help [customer] do [job] without [pain]. For the demo venture: we help small e-commerce sellers without a designer prepare complete product listings without copying data by hand. Read it aloud to someone outside the team and ask them to repeat it back.", "avoid": "Avoid stacking technology words like AI-powered platform before saying who it helps and with what.", "synthetic": true}}, "834db9e9de30b592": {"question": "Does this problem actually exist?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Many ideas start from a problem the founders imagine. Checking existence early prevents months of building for a difficulty no customer actually has.", "example": "Look for traces the problem leaves behind. Ask a few small sellers to show their last listing session: spreadsheets, half-filled store forms, notes about missing specs. If nobody can show such traces, treat the problem as unconfirmed rather than assuming it is hidden.", "avoid": "Avoid counting friends who say it sounds plausible as proof that the problem exists.", "synthetic": true}}, "cb6ee9e32aaa5cd4": {"question": "Why is this problem worth solving?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A real problem can still be too small, too rare, or too cheap to tolerate. Worth depends on what solving it would change for customers.", "example": "Write down what would improve for a seller if listing preparation stopped being a chore: faster launches, fewer returns from wrong specs, more evenings free. Then plan interviews to check which of these changes sellers actually care about, rather than which ones sound impressive.", "avoid": "Avoid assuming a problem is worth solving simply because it is technically interesting to solve.", "synthetic": true}}, "5d1ba15422ef8a4f": {"question": "Which workflows are slow, expensive, or error-prone?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Slow, costly, or error-prone workflows are where problems leave measurable marks. They give you concrete places to look instead of vague dissatisfaction.", "example": "Map one seller's listing process step by step: gather supplier specs, rename photos, write titles, fill store fields, recheck before publishing. Mark which step takes longest, which needs paid help, and which causes corrections later. Confirm each mark by watching or asking about a recent batch.", "avoid": "Avoid listing every step as painful; that hides the one workflow that genuinely hurts.", "synthetic": true}}, "19323bdcc6b1bd3c": {"question": "Which problems have persisted without being properly solved?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A problem that has lasted despite existing tools often signals a real gap. It also warns that easy fixes may have already been tried and failed.", "example": "Ask what sellers have tried for listing preparation over time: templates, marketplace import tools, freelancers, a relative helping on weekends. Note why each attempt was dropped. A pattern of abandoned workarounds suggests the problem persists; note too if one tool quietly works well enough.", "avoid": "Avoid assuming nobody has solved it because you have not searched for existing tools and workarounds.", "synthetic": true}}, "6c859a37ada46474": {"question": "Should this product exist?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This forces a judgment before building: if the problem and customer evidence are weak, the honest answer may be that the product should not exist yet.", "example": "Set a simple test before deciding. Suppose you agree in advance that the product should exist only if sellers describe recent, costly listing problems and some agree to a paid pilot. Record what you find, and be willing to stop or change direction if the bar is not met.", "avoid": "Avoid answering yes because the team is excited, has a demo, or already spent time building.", "synthetic": true}}, "9d52c3ebba5bf5c4": {"question": "What problem are we trying to solve?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In the early idea stage, naming the problem pulls the team's attention away from the product they imagine and toward the need they must understand.", "example": "Each founder writes the problem on a card without discussing first. In the demo venture, one might write missing listing data, another slow photo editing, another too many store formats. Compare the cards and agree which problem the next round of work will focus on.", "avoid": "Avoid answering with the product idea itself, such as we are building an AI listing tool.", "synthetic": true}}, "1f655b44f7474cc1": {"question": "Are we promoting a product we want to build, or understanding a problem customers need solved?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Founders easily slip from learning into selling their idea. Naming which mode you are in keeps interviews and plans honest about what you still do not know.", "example": "Review your last few seller conversations. Count how many minutes you spent showing the listing tool concept versus asking how the seller prepared their latest batch. If most of the time went to the pitch, redesign the next conversation around their past behavior.", "avoid": "Avoid calling a product demo a customer interview; it collects reactions, not problems.", "synthetic": true}}, "2c559978dadea0e2": {"question": "What is the problem?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This is the first block of a structured problem statement. A clear definition here shapes how you describe the customer, market, and solution afterwards.", "example": "State the difficulty as a fact you can check: small sellers spend hours before each launch gathering specs and fixing missing store fields. Leave the customer, market size, and solution for the next blocks, so this block stays focused on the difficulty alone.", "avoid": "Avoid mixing the customer, market, and solution into one long sentence in this block.", "synthetic": true}}, "7046f8b4d350ef5a": {"question": "Which problem is the most important to solve?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Teams usually find several problems at once. Choosing the most important one keeps limited time on the difficulty most likely to matter.", "example": "List the candidate problems from the demo venture: missing specs, inconsistent titles, poor photos, different formats per store. For each, note how often sellers mention it and what it costs them. Pick one to investigate first and write down why the others wait.", "avoid": "Avoid choosing the problem your preferred feature solves instead of the one with the strongest evidence.", "synthetic": true}}, "9b4d70faedf58c4b": {"question": "What might be the root causes of this problem?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Symptoms and causes need different solutions. Finding possible root causes stops you from building a fix for the visible symptom only.", "example": "Ask why repeatedly. Listings are incomplete. Why? Specs are missing. Why? Suppliers send them in scattered emails and PDFs. Why? There is no standard request format. Each answer is a hypothesis; check it by looking at the actual supplier files a seller received.", "avoid": "Avoid stopping at the first cause that matches the solution you already want to build.", "synthetic": true}}, "560e4df87ebc8e49": {"question": "What do we currently believe the problem is?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Writing the current belief down makes it testable. Later evidence can then confirm, weaken, or replace it instead of being quietly absorbed.", "example": "Record a dated statement such as: we currently believe small sellers lose most listing time collecting missing specs from suppliers. Note what evidence supports it so far and what would change your mind. Revisit the same statement after the next interviews.", "avoid": "Avoid presenting a current belief as settled fact; label it as a belief to be checked.", "synthetic": true}}, "ed46f7a5b1779e3e": {"question": "Is the problem unclear, or have we not found a good way to explain it?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When others look confused, the cause may be a fuzzy problem or just a weak explanation. The fix is different for each.", "example": "Explain the problem to two people outside the team. If they cannot repeat it, try rewriting with one concrete seller story. If they still disagree on what it is, the team itself may hold different problems, and you should return to the evidence instead of polishing words.", "avoid": "Avoid endlessly rewording the pitch when the underlying problem has not been agreed or investigated.", "synthetic": true}}, "8d4de5965b099052": {"question": "Can the team explain the problem clearly?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A team check: if each member describes the problem differently, the team will interview, build, and decide in different directions.", "example": "Ask every member to explain the problem aloud in under a minute without notes. In the demo venture, listen for whether everyone mentions the same seller and the same listing difficulty. Note any version that drifts toward features, and discuss the gap before the next interviews.", "avoid": "Avoid letting only the most confident founder answer and assuming the others agree.", "synthetic": true}}, "16dbf99ca6f3f1ad": {"question": "Can we describe the problem in one or two sentences?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A one or two sentence limit forces you to cut side issues. Short statements are also easier to test in interviews.", "example": "Sentence one names who and what: small sellers without a designer struggle to prepare complete listings. Sentence two names the effect: missing specs delay launches and cause corrections. If you need a third sentence, check whether you are describing two separate problems.", "avoid": "Avoid cramming several problems into one long sentence joined by commas and the word and.", "synthetic": true}}, "fb34ff456044e838": {"question": "Are we describing customers’ difficulties rather than product features?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Features describe your solution; difficulties describe the customer's world. Only difficulties tell you whether anyone needs what you plan to build.", "example": "Read your problem statement and underline every noun about your product, such as auto-fill or template engine. Rewrite those parts as what the seller experiences: re-typing the same specs into three stores. Keep the rewritten version for interviews.", "avoid": "Avoid statements like sellers need an AI listing assistant; that names a product, not a difficulty.", "synthetic": true}}, "f52c38dcf3c509f4": {"question": "Is the problem specific enough to investigate through interviews?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Interviews need a specific target. A broad problem leads to vague questions and answers you cannot compare across customers.", "example": "Too broad: running an online store is hard. Specific enough: preparing product specs for a new batch takes too long. Check by drafting three interview questions about a recent listing batch. If the questions come easily and refer to real events, the problem is specific enough.", "avoid": "Avoid interviewing about e-commerce in general and hoping a clear problem appears on its own.", "synthetic": true}}, "585020cf36a01faf": {"question": "What’s broken today?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A concrete situation is easier to investigate than a broad complaint.", "example": "A small seller copies product details between spreadsheets and a store editor, then fixes missing fields before each launch. This is a hypothesis to investigate.", "avoid": "Avoid abstract complaints without a person or situation.", "synthetic": true}}, "1a1fcb667ac94469": {"question": "Does the problem really exist?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In product strategy, existence must be checked before scope and results are set. Otherwise the roadmap rests on a guess no one has examined.", "example": "Before committing to a feature roadmap, gather direct evidence: watch a few sellers prepare a real batch, or collect copies of their listing spreadsheets with permission. Record what you observe next to what the strategy assumes, and flag any assumption with no observation behind it.", "avoid": "Avoid treating survey answers about hypothetical future use as evidence that the problem exists today.", "synthetic": true}}, "a0362e61097d453d": {"question": "Whose problem are we solving?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The same problem affects people differently. Naming whose problem it is guides who to interview, who to design for, and what result to measure.", "example": "Separate roles in a small store: the owner, an assistant who uploads products, a freelancer who edits photos. Decide whose listing difficulty you focus on first, for example the assistant doing uploads. Then check that this person actually experiences the problem you described.", "avoid": "Avoid answering small businesses or everyone selling online; that group is too wide to act on.", "synthetic": true}}, "638bae9d8892ea6b": {"question": "What problem do our customers face?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The pitch problem slide must speak from the customer's side. Investors look for a difficulty they can picture, supported by what you learned.", "example": "Write the slide around a single seller scenario: before each launch, the store assistant chases supplier specs, retypes them into the store, and fixes missing fields. Add only evidence you actually collected, such as the number of sellers who described this, clearly labeled.", "avoid": "Avoid filling the slide with industry statistics while leaving out what your own customers told you.", "synthetic": true}}, "2c7e259a94952f0d": {"question": "Does this problem recur?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A one-time problem rarely supports a business. Recurrence means customers meet the pain again and again, which makes a solution worth adopting.", "example": "Ask sellers when they prepared listings over the past few months and mark each date. In the demo venture, a seller who adds new products every week faces the problem repeatedly, while one who lists a catalog once a year does not. Compare the patterns.", "avoid": "Avoid assuming recurrence because the task sounds routine; check actual dates from past behavior.", "synthetic": true}}, "771781f0afc12eb8": {"question": "In what situations does the problem occur?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Problems appear in particular moments, not everywhere. Knowing those moments shows when a customer would need help and where a solution must fit.", "example": "Collect moments when sellers struggle with listings: a new supplier batch arrives, a seasonal sale is coming, a marketplace changes its required fields. For each, note who was involved and what they were doing. Look for the situation that comes up most across sellers.", "avoid": "Avoid describing the problem as always present; pain without a clear situation is hard to investigate.", "synthetic": true}}, "459e70d7c4acd8b1": {"question": "In what situation does it happen?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Here the situation is part of a structured problem statement. It links the problem to the customer and tells you where to observe it.", "example": "Add a situation line next to the problem block: when a seller receives a new product batch from a supplier and needs it online before a set launch date. Then check whether the customer and market blocks describe people who actually face this situation.", "avoid": "Avoid writing a situation so general, such as during daily work, that it gives no place to look.", "synthetic": true}}, "0af7eff008b767a2": {"question": "How often does it happen?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Frequency multiplies everything else. A modest pain felt every week can matter more than a severe one felt once a year.", "example": "For each seller you talk to, record how many listing batches they prepared in a recent period you choose, using their store history if they can show it. Place the counts next to your problem statement so the team sees real frequencies instead of estimates.", "avoid": "Avoid writing often or regularly; record counts within a defined time window instead.", "synthetic": true}}, "2bec2238782323b7": {"question": "Does the problem persist or recur?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A problem can last a long time or come back repeatedly. Telling these apart shapes whether a solution is a single fix or ongoing help.", "example": "In the demo venture, a messy legacy catalog persists until someone cleans it once, while new-batch preparation recurs each time products arrive. Ask sellers which describes their situation, and note both if both apply. The answer affects whether you would offer a project or a subscription.", "avoid": "Avoid treating persistent and recurring as the same thing; they lead to different offers.", "synthetic": true}}, "90ab39d19a230b5f": {"question": "In what other situations might this problem occur?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Exploring other situations can reveal a larger or more urgent version of the problem, or show that your first situation was too narrow.", "example": "Starting from new-batch listings, brainstorm related moments: moving the store to another platform, opening a second marketplace, updating prices for a sale. Treat each as a hypothesis and plan one interview question that checks whether sellers actually faced it recently.", "avoid": "Avoid adding every imagined situation to your scope before any of them has been checked.", "synthetic": true}}, "8e3e420bff537861": {"question": "In what situation does it occur?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In customer validation, the situation becomes part of a hypothesis you can test. A precise situation tells you which customers and moments to look for.", "example": "Write the hypothesis with a situation in it: sellers struggle most when a supplier sends a large batch with incomplete specs shortly before a sale. Then plan how to check it, for example by asking interviewees to walk through their most recent supplier batch.", "avoid": "Avoid testing a hypothesis that has no situation; results will be too scattered to interpret.", "synthetic": true}}, "e7d110612895b6ad": {"question": "How often does the problem occur?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Frequency changes the value of solving the problem.", "example": "Ask a seller to show the last three listing sessions. Record the dates instead of guessing a weekly average.", "avoid": "Avoid guessing frequency without looking at actual events.", "synthetic": true}}, "4e8d6eafd44e46bc": {"question": "When did it last happen?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The most recent occurrence is the easiest to remember accurately. It anchors your hypothesis in a real event rather than a general impression.", "example": "For each seller in your notes, add a date for the last listing batch that caused trouble. If you do not know it, mark the hypothesis as unchecked for that person. Sellers whose last event was long ago may not feel the problem strongly today.", "avoid": "Avoid filling in a typical date from memory; leave it blank until a customer gives it.", "synthetic": true}}, "735f675603a40328": {"question": "What event triggers the customer to look for a solution?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "People rarely search for help until something happens. The trigger tells you when customers become open to change and where to reach them.", "example": "Possible triggers in the demo venture: a marketplace rejects listings for missing fields, a big supplier batch arrives, or the assistant who handled uploads leaves. Ask sellers what happened just before they last looked for a tool or freelancer, and note the event.", "avoid": "Avoid assuming the trigger is seeing your ad; ask what happened before they started looking.", "synthetic": true}}, "62a2d4fe430a0d69": {"question": "Which situation explains their motivation to buy?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Motivation to buy is tied to a specific situation. Knowing which one turns a general need into a reason to pay now.", "example": "Compare two sellers: one wants tidier listings someday, another must have a seasonal collection live before a holiday sale. The second situation explains urgency to buy. In interviews, ask what was happening when they last paid for listing help, such as hiring a freelancer.", "avoid": "Avoid treating general interest as buying motivation when no situation forces a decision.", "synthetic": true}}, "4cb11ab56df49992": {"question": "When was the last time you experienced this problem?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Asking about the last time pulls the customer toward a real, recent event, which is more reliable than opinions about how often things usually happen.", "example": "Ask a seller: when was the last time preparing product listings gave you trouble? Then follow up: what were you listing, who helped, how did it end? Listen for a date and specific details. If they answer with usually or always, gently ask for one occasion.", "avoid": "Avoid accepting a general answer like all the time without asking for a specific occasion.", "synthetic": true}}, "463c24649929713b": {"question": "Is there a deadline or triggering event that makes action urgent?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "For growth, urgency explains why a customer acts now rather than later. Deadlines and triggering events help you time outreach and offers.", "example": "Look for deadlines in the demo venture: a holiday sale start date, a marketplace policy change with a fixed date, a supplier shipment arriving next week. Record which customers mention such deadlines, and test whether contacting sellers before those dates changes how they respond.", "avoid": "Avoid creating fake urgency with countdown offers instead of finding the customer's real deadlines.", "synthetic": true}}, "fe0ae8758711d119": {"question": "How often does the problem occur?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Frequency changes the value of solving the problem.", "example": "Ask a seller to show the last three listing sessions. Record the dates instead of guessing a weekly average.", "avoid": "Avoid guessing frequency without looking at actual events.", "synthetic": true}}, "d078ee4ea9e0ee8c": {"question": "Who encounters what difficulty, in what situation?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This combines who, what, and when into one testable statement. It keeps product strategy grounded in a specific person facing a specific moment.", "example": "Fill the pattern: [who] struggles with [difficulty] when [situation]. For the demo venture: a store assistant at a small seller struggles to complete product specs when a supplier batch arrives with missing data. Check each part separately in interviews.", "avoid": "Avoid leaving one part blank or generic, such as users struggle with listings sometimes.", "synthetic": true}}, "e1c6a66845ba9698": {"question": "When was the last time you encountered this problem?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Asked during product strategy work, this checks whether the problem behind your planned scope still happens to real customers today.", "example": "Ask the seller: when did you last run into trouble preparing a product listing? Then ask them to open the listing or spreadsheet from that time if possible. Note the date and what went wrong, and compare it with the problem your current scope targets.", "avoid": "Avoid asking whether they would use a feature; ask about the last real event instead.", "synthetic": true}}, "436b96cc878974d4": {"question": "Do customers genuinely feel pain from this problem?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A problem can exist without hurting much. Genuine pain is what makes customers change habits, spend money, or make time for a new solution.", "example": "Watch for signs of pain in how sellers act, not how they rate it. Did they stay up late fixing listings, pay a freelancer, or complain to a supplier? Record these actions for each seller. Few actions despite agreement suggests the pain may be mild.", "avoid": "Avoid relying on pain ratings from one to ten; look for actions taken because of the problem.", "synthetic": true}}, "0a399e609f080f69": {"question": "What do customers lose if the problem remains unsolved?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Loss explains the stakes. If customers lose little by leaving the problem alone, they have little reason to adopt anything new.", "example": "List possible losses for a seller with incomplete listings: products launched late, returns from wrong specs, hours taken from customer service. Treat each as a hypothesis. In interviews, ask what actually happened the last time a listing went out incomplete.", "avoid": "Avoid assuming lost revenue by default; many losses are time, stress, or missed chances instead.", "synthetic": true}}, "f744e8e88d4ed1e5": {"question": "Is our solution a painkiller or a vitamin?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Painkillers relieve something customers already feel; vitamins offer a benefit they can easily postpone. The difference strongly affects how hard it will be to sell.", "example": "Ask what sellers do today without your solution. If they already pay a freelancer or work late to finish listings, your offer may be a painkiller. If they say nicer titles would be good someday, it is more like a vitamin. Record which pattern you hear.", "avoid": "Avoid labeling your product a painkiller because the team believes in it; let customer behavior decide.", "synthetic": true}}, "85c60ac8574c4de8": {"question": "What losses does it cause?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In the structured problem block, losses connect the problem to a reason to act. They also help size the market later.", "example": "Under the problem statement, add a losses line: delayed launches, extra freelance fees, marketplace warnings for missing fields. Mark each loss as heard from customers or still assumed. Use only the heard ones when you move on to customer and market blocks.", "avoid": "Avoid listing losses you cannot trace to any customer conversation or observation.", "synthetic": true}}, "bb4784ca5fdbd032": {"question": "Does the problem have a real impact?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A team check before moving on: the problem should change something real for customers, not just be a minor annoyance discussed in theory.", "example": "As a team, pick one seller you spoke with and describe what changed for them because of the problem, such as a delayed launch or an extra cost. If nobody can name a concrete effect, pause and gather more evidence before dividing work on solutions.", "avoid": "Avoid passing this check on agreement alone when nobody can point to a concrete effect.", "synthetic": true}}, "89ec57f8f95bc2bb": {"question": "How much does it affect the customer?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Size of impact decides priority. Customers act on problems that noticeably affect their work, money, or peace of mind.", "example": "Write a hypothesis about impact, such as listing preparation takes a large share of the assistant's week. Then plan how to check it: ask the seller to estimate hours for the last batch, or compare with their own time records if they keep any.", "avoid": "Avoid describing impact with words like huge or significant without saying what was affected.", "synthetic": true}}, "6ba45e0a9c688a55": {"question": "How much time or money has the customer already spent dealing with it?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Time or money already spent is strong evidence. It shows the customer valued solving the problem enough to act before you arrived.", "example": "In your customer hypotheses, add a column for past spending. In the demo venture, this could be freelancer fees, a spreadsheet template purchase, or hours the owner spent fixing listings. Fill it only from what sellers report about real past actions.", "avoid": "Avoid guessing what customers might spend; this question is about what they already did spend.", "synthetic": true}}, "318d67ab9a5a2cc4": {"question": "What happens if the customer does nothing?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Inconvenience becomes clearer when its consequences are visible.", "example": "A possible consequence is a delayed product launch. Ask for a recent event and its actual impact; do not assume lost revenue.", "avoid": "Avoid claiming lost revenue without evidence.", "synthetic": true}}, "3ee3df5b7619c269": {"question": "Is the problem serious enough to require action?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Some problems are real but tolerable. If it does not cross the line where people must act, customers will keep living with it.", "example": "Look for moments when sellers had to act: a marketplace blocked listings, a launch date slipped, a customer complained about wrong specs. Note whether these happened and what the seller did next. If sellers shrug and continue, the problem may not yet be serious enough.", "avoid": "Avoid deciding seriousness from how strongly the team feels about the problem.", "synthetic": true}}, "1ff78355287dc618": {"question": "Does solving the problem cost more than tolerating it?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Customers compare the effort of changing with the cost of living with the problem. If solving costs more, they will rationally wait.", "example": "For a seller, compare what tolerating costs, such as a few extra hours per batch, with what switching costs: learning a new tool, moving data, paying a fee. Ask sellers to describe both sides. Note where switching feels heavier than the pain itself.", "avoid": "Avoid comparing only your price with their pain; include setup effort, learning time, and risk.", "synthetic": true}}, "d645561ca03f0fef": {"question": "What time, financial, risk, or emotional costs does the problem create?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten from an assumption statement)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Costs come in different forms. Naming the type helps you understand which cost customers care about and how to talk about it.", "example": "Sort possible costs for a seller: time spent retyping specs, money paid to a freelancer, risk of marketplace penalties, and stress before launches. Mark which types each interviewee mentions unprompted. The type that comes up most often should shape your next hypothesis.", "avoid": "Avoid squeezing every cost into money; time, risk, and emotional costs may matter more.", "synthetic": true}}, "4fda8d4e230766e2": {"question": "Are we addressing an important pain point or a minor inconvenience?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Minor inconveniences gather polite agreement but rarely lead to action. Telling them apart early saves time on problems nobody will pay to fix.", "example": "Compare reactions across sellers. Signs of an important pain: they bring it up before you ask, describe workarounds, or mention costs. Signs of an inconvenience: they agree when prompted but cannot recall a recent case. Record which signs appear for each seller.", "avoid": "Avoid treating sellers nodding along to your description as evidence of an important pain.", "synthetic": true}}, "060bff1f05edc44f": {"question": "Could you describe a specific recent example and the loss it caused?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a follow-up instruction)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "A recent, specific example with its loss is hard to invent. It turns a general complaint into evidence you can record and compare.", "example": "Ask: could you walk me through a recent listing batch that went wrong, and what it cost you? Listen for details such as which products, how late they went live, or what customers said. If the seller answers in general terms, ask for one particular batch.", "avoid": "Avoid suggesting the loss yourself, such as did you lose sales? Let the customer name it.", "synthetic": true}}, "362ff09eda2b48e1": {"question": "How much time, money, or labor did you spend dealing with it?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Effort already spent shows how much the problem matters in practice. It also gives a baseline for what a solution must beat.", "example": "Ask the seller about the last batch: how many hours did you or your assistant spend on it? Did you pay anyone for help? Record the answers separately as time, money, and labor. If they are unsure, ask what else they had to postpone that week.", "avoid": "Avoid asking how much they would pay for a fix; ask what they already spent.", "synthetic": true}}, "a82ca02ccc0afdd8": {"question": "What happened when you did not address it?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "What happened when the problem was ignored reveals real consequences. If nothing much happened, the pain may be smaller than it seems.", "example": "Ask: was there a time you left listings incomplete or published them anyway? What happened afterwards? Listen for events such as returns, marketplace warnings, or customer questions. Note if the answer is that nothing happened; that matters as much as a dramatic story.", "avoid": "Avoid asking what would happen if they ignored it; hypothetical answers tend to exaggerate.", "synthetic": true}}, "944d5ae93a005d10": {"question": "Does the problem cause lost revenue, extra costs, legal risk, complaints, or reputational damage?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "For growth, these concrete harms make the problem visible to decision makers and budgets. They often decide whether a business will pay.", "example": "Check each type against what sellers report: products listed late during a sale, extra freelancer fees, wrong specs that could breach consumer rules, complaints about mismatched items, or poor reviews. Mark which ones you heard about and which remain assumptions.", "avoid": "Avoid claiming legal or reputational risk without any customer describing a related event.", "synthetic": true}}, "7d8b0c278ba6aa4b": {"question": "How severe is it?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Severity tells product strategy where to focus. A severe problem justifies a narrow, strong solution; a mild one may not justify building anything.", "example": "Define a few severity levels before reviewing evidence, for example: an annoyance, costs a few hours per batch, or blocks a launch. Then place each seller you spoke with on that scale using what actually happened to them, not their general feelings.", "avoid": "Avoid averaging severity across very different sellers; a few severe cases may matter most.", "synthetic": true}}, "3d4f050b6cb58e52": {"question": "How much time or money have they already spent solving it?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In product strategy, past spending on solutions shows what customers already accept as worth paying for, and what your product competes against.", "example": "List the current alternatives sellers have paid for: freelance listing writers, marketplace bulk-upload tools, extra part-time help during busy seasons. Note which one each seller used and roughly what it cost them by their own account. Your scope should beat the option they actually use.", "avoid": "Avoid ignoring spreadsheets and manual effort as alternatives; doing it by hand is also a solution.", "synthetic": true}}, "b598d6f19d69964c": {"question": "How much time does it take?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Time is often the first cost customers can describe. Their own account of time spent gives a baseline any solution must clearly improve.", "example": "Ask the seller: for your last batch of new products, how long did getting them ready to publish take, from receiving specs to going live? If they are unsure, ask them to walk through that day. Write down their words and the batch size.", "avoid": "Avoid asking how long it usually takes; anchor the question in one recent batch.", "synthetic": true}}, "d6879b8df56b235c": {"question": "How much does it cost?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Money spent shows whether there is a budget connected to the problem, and roughly how large a price customers might consider.", "example": "Ask the seller: did you pay anyone or anything to help with your last listing batch, such as a freelancer, a tool, or extra hours for staff? How much was it? If nothing was paid, ask what the time would have been worth to them.", "avoid": "Avoid asking what price they would accept; ask what they actually paid before.", "synthetic": true}}, "6794c573171c7a30": {"question": "Which step is the most painful?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Not every step hurts equally. The most painful step tells you where a first, small solution could matter most.", "example": "Ask the seller to walk through the last listing batch step by step: collecting specs, editing photos, writing titles, filling store fields, checking. Then ask which step they would most like to never do again, and why. Note where their voice or pace changes.", "avoid": "Avoid offering your favorite step as an option; let the customer choose from their own description.", "synthetic": true}}, "ea777e6d7c9699f9": {"question": "Who is experiencing this problem?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "An idea only becomes a problem worth studying once you can point to real people who meet it in their daily work.", "example": "Write down the people you picture hitting the problem: a seller who lists products alone at night, a two-person shop with a part-time helper. Treat each as a guess, then plan who you could actually talk to this week.", "avoid": "Avoid answering with everyone who sells online. A group that large gives you no one to call.", "synthetic": true}}, "ac3a5fd90c26aaba": {"question": "Who is putting up with an inconvenience today?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "People tolerating a nuisance often hide the clearest early demand, because they have stopped complaining but still spend time working around it.", "example": "Look for sellers who quietly retype specs from supplier PDFs into each listing, or who skip missing fields and fix them after a customer asks. Ask them to show the workaround rather than describe how annoying it is.", "avoid": "Avoid counting only loud complainers. Quiet tolerance, visible in repeated workarounds, can matter more than strong words.", "synthetic": true}}, "c505db3d91e280dd": {"question": "Which customers face this problem?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This question sits beside your advantages and team, so naming customers early helps you see whether your strengths actually reach the people with the problem.", "example": "Suppose your team includes someone who has run a small online shop. List which kinds of sellers that experience lets you reach and understand, such as handmade goods shops, and which it does not.", "avoid": "Avoid choosing a customer group only because it sounds large, when your team has no way to reach it.", "synthetic": true}}, "b943a89a38b14268": {"question": "Can I clearly describe our target customers?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If you cannot describe the target customer in a sentence or two, interviews, outreach, and pricing decisions all stay vague.", "example": "Test yourself: write one sentence a teammate could use to find a matching seller without asking you. For example, a shop owner listing new products every week without a designer. If teammates pick very different people, the description is not clear yet.", "avoid": "Avoid a description so loose that almost any business owner could match it.", "synthetic": true}}, "5ebe606c88ce497a": {"question": "Who are our customers?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In a business model, customers are the starting point for revenue, channels, and costs, so a fuzzy answer weakens every other block.", "example": "In the business model sketch, name the customer as the one who would hold the account: for example, owners of small online stores who handle listings themselves. Then check that the channel and price blocks fit that same customer.", "avoid": "Avoid listing users, partners, and investors together as customers. Each plays a different part in the model.", "synthetic": true}}, "2478e387b014c26c": {"question": "Who experiences it?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This question ties the problem to a specific person, which is what turns a problem statement into something you can test in conversation.", "example": "Next to your problem statement, add the person who lives it: the seller who prepares listings before a launch. Then write one situation where they meet it, such as uploading a supplier batch with missing sizes.", "avoid": "Avoid writing a problem statement with no person attached. It cannot be checked against anyone's experience.", "synthetic": true}}, "11f7bf08164125b4": {"question": "Which customer group feels the most pain?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Pain differs across groups, and the group that hurts most is usually the one that will spend time or money to fix it.", "example": "Compare two groups, for instance sellers adding a few products a month and sellers adding a large batch every week. Record for each what goes wrong when listings are late or incomplete, and which group mentions real consequences.", "avoid": "Avoid judging pain by how emotional people sound. Look for consequences they describe from recent events.", "synthetic": true}}, "69bb43571965f850": {"question": "Which customer group is most willing to try a new solution?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Willingness to try something new is separate from pain; early adopters are the people who will tolerate an unfinished first version.", "example": "Notice which sellers already experiment: those who tried a new listing tool or template in recent months. Ask what they tried last and why. Their recent switching behavior is a better sign than a promise to try yours.", "avoid": "Avoid assuming the most frustrated group is also the most open to change. Check their recent behavior.", "synthetic": true}}, "9ddaa1be54db53be": {"question": "Who might our target customers be?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "At this stage several candidate groups can still be possible, and listing them keeps you from locking onto the first one too early.", "example": "Draft three possible target groups: solo sellers on a marketplace, small brands with their own store, and agencies listing products for clients. Mark each as a hypothesis and note one way to meet a few people from it.", "avoid": "Avoid treating your first guess as settled. Keep alternatives on the page until evidence narrows them down.", "synthetic": true}}, "de0a664929632505": {"question": "Which groups are most likely to be affected?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Some groups feel the effects of a problem indirectly; mapping who is affected shows where the impact actually lands.", "example": "Trace one incomplete listing: the seller loses time, a buyer asks a question, and a helper fixes the page later. List each affected group and mark which one feels the impact most directly and most often.", "avoid": "Avoid stopping at the person doing the task. Others downstream may feel the consequences more strongly.", "synthetic": true}}, "84f88d2c91b876d8": {"question": "Which customer group does each interviewee belong to?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Mixing interviews from different groups blurs the evidence; tagging each interviewee lets you compare like with like before drawing conclusions.", "example": "After each interview, tag the person with one of your candidate groups, such as solo marketplace seller or small brand owner. When reviewing notes, read each group's interviews together and see whether the pattern holds within it.", "avoid": "Avoid pooling all interviews into one summary. A strong pattern in one group can hide weak results elsewhere.", "synthetic": true}}, "a4f2340aa90fa604": {"question": "Are the target customers clearly defined?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Before teams split up to run interviews, everyone needs the same definition, or each person will collect evidence from a different market.", "example": "At the team check, ask each member to name two people they plan to contact. If one picks a large retailer and another picks a weekend hobby seller, the definition is not clear enough to share.", "avoid": "Avoid answering yes because the definition sounds fine aloud. Test whether teammates choose the same kind of people.", "synthetic": true}}, "03215e8986aa144b": {"question": "Who genuinely has this problem?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Some people agree a problem exists without actually living it; this question separates real sufferers from polite sympathizers.", "example": "Ask a seller to show the last listing they prepared and what they did when information was missing. Someone who genuinely has the problem can point to a specific recent session and the steps they took.", "avoid": "Avoid counting someone because they said the problem sounds real. Look for recent, specific events in their own work.", "synthetic": true}}, "1e5dc47411c6f002": {"question": "Is our current customer definition too broad?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A broad definition feels safe but makes interviews disagree with each other, because very different people are being treated as one customer.", "example": "If your definition is anyone selling online, try narrowing it by one condition at a time: sells physical goods, lists new products weekly, has no designer. Check whether interview answers become more consistent as you narrow.", "avoid": "Avoid keeping a broad definition just to make the market look bigger than your evidence supports.", "synthetic": true}}, "bd4911ba4c6bc638": {"question": "Which group experiences the problem most often?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Frequency shapes value: a problem met every week builds habits and budget, while a yearly problem is easy to ignore.", "example": "Ask sellers from each group to show their last three listing sessions and record the dates. Compare the intervals across groups instead of asking people to estimate how often it happens.", "avoid": "Avoid relying on estimated averages like every week. Ask for dated past sessions instead.", "synthetic": true}}, "f9a2885002bc29e2": {"question": "Which group is most urgent about solving it?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Urgency decides whether a group acts now or postpones; a frequent problem can still be low priority if nothing forces a fix.", "example": "Listen for deadlines: a seller preparing for a seasonal sale, or one whose marketplace now rejects listings with missing fields. Record which groups have a real date attached and what happened the last time they missed it.", "avoid": "Avoid confusing frequency with urgency. Ask what forces action now, not only how often it happens.", "synthetic": true}}, "9d00ba17ecd7f0e9": {"question": "What roles, industries, organization sizes, and stages describe our early customers?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Concrete attributes turn a customer idea into a profile you can search for, filter, and use to recruit interviewees.", "example": "Fill in each attribute as a working guess: role is owner who lists products, industry is apparel or home goods, organization size is one to five people, stage is past first sales. Use the profile to choose your next interviewees.", "avoid": "Avoid leaving attributes blank because you are unsure. A stated guess can be corrected; a blank cannot.", "synthetic": true}}, "745853d418f8e058": {"question": "Does this interviewee actually fit our ideal customer profile?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviewing people outside the profile can make weak demand look strong, so each record should state whether the person really qualifies.", "example": "In each interview record, check the person against the profile fields: do they list products themselves, how many people work in the shop, how often they add products. Mark fits, partial fits, and non-fits before reading their answers.", "avoid": "Avoid deciding fit after hearing the answers. Judge fit from profile facts so enthusiasm does not bias the label.", "synthetic": true}}, "e5a344b33ae1ee71": {"question": "What changed in our ideal customer profile after the interviews, and why?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from an assignment instruction)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviews should move your definition; writing down what changed and why keeps the profile tied to evidence rather than preference.", "example": "Write a short before and after: before, any small online seller; after, sellers adding products weekly from supplier sheets. Next to the change, note which interviews prompted it and what was said or shown.", "avoid": "Avoid reporting that nothing changed without checking. Avoid changes with no interview behind them.", "synthetic": true}}, "b11f38c351374db8": {"question": "Do the friends we interviewed actually fit our ideal customer profile?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Friends are easy to reach and kind in their answers, so check whether they belong to the group you are studying.", "example": "If you interviewed a friend who sells occasionally on a marketplace, compare them with your profile fields. Note where they match, such as no designer, and where they differ, such as listing only a few items a year.", "avoid": "Avoid counting friends as target customers by default. Convenience and kindness can both distort the results.", "synthetic": true}}, "773331fa72fd6ba5": {"question": "If they do not, can they represent our market?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "A friend outside the profile can still teach something, but their answers should not stand in for the market you plan to serve.", "example": "Keep a friend's interview but label it as outside the profile. Use it for open questions, such as which steps confuse a newcomer, and leave it out when counting how many sellers have the problem.", "avoid": "Avoid mixing out-of-profile answers into your counts. Avoid discarding them entirely when they reveal a useful question.", "synthetic": true}}, "5051a04dd8250939": {"question": "Who feels this pain?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Different customers may face very different levels of urgency.", "example": "Small e-commerce sellers listing over 100 products a month without a dedicated designer. Check whether this group actually experiences the problem.", "avoid": "Avoid defining the customer as everyone who sells online.", "synthetic": true}}, "27e979941b618c8d": {"question": "Who are our first customers?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Your first customers shape the product scope and the evidence you gather, so they need to be a small, reachable group.", "example": "Suppose you choose small apparel shops that add new items every week. Write the names of a few such shops you can contact and the first result you would deliver to them, such as one complete batch of listings.", "avoid": "Avoid naming the whole long-term market as first customers. Pick a group small enough to serve closely.", "synthetic": true}}, "97203e326d7a726f": {"question": "Which customer group is being ignored?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Competitors often chase the same visible segment, leaving a group underserved; that gap can become your entry point.", "example": "Look at who existing listing tools target. If most aim at larger stores with design staff, sellers without a designer may be left out. Check reviews and forums for that group describing tools that feel too complex.", "avoid": "Avoid assuming a group is ignored without checking. It may be ignored because it cannot or will not pay.", "synthetic": true}}, "038f7d6ca8ed98bf": {"question": "Who has the authority to decide whether to buy or use a solution?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Even a painful problem stays unsolved if the person who feels it cannot say yes to a solution.", "example": "In a small shop, the helper who fixes listings might suffer most, while the owner approves new tools. Ask who said yes the last time the shop started using a new app or service.", "avoid": "Avoid assuming the person describing the pain can approve the purchase.", "synthetic": true}}, "e60ee8ef921f0da4": {"question": "Who uses the product?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In the business model, the user determines what the product must do every day, even when someone else signs off.", "example": "For the listing service, the user may be whoever uploads product data and checks the result, perhaps a part-time assistant. Describe the moments they touch the product and what they need at each one.", "avoid": "Avoid naming the buyer as the user by default. The daily operator may be someone else.", "synthetic": true}}, "fcdb7b983b5e37a3": {"question": "Who pays for it?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The person doing the work may not control the budget.", "example": "A store assistant prepares listings, but the owner may approve software spending. Confirm this with the business.", "avoid": "Avoid assuming that the user also controls the budget.", "synthetic": true}}, "fb6c639e6ccc4b7d": {"question": "Who makes the purchasing decision?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The business model depends on who signs off, because sales effort, messaging, and pricing all target that person.", "example": "For a small brand, the founder may approve monthly software costs while a manager researches options. Map who proposes, who approves, and who could stop the purchase, then check this against how they bought their last tool.", "avoid": "Avoid assuming the person who sounded most excited in a meeting is the one who decides.", "synthetic": true}}, "91780aff792e3fee": {"question": "Who uses, who pays, and who controls purchasing?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Separating the three roles early shows whether your pitch, onboarding, and pricing are aimed at the right people.", "example": "Draw three columns for the listing service: uses it, pays for it, controls purchasing. A shop might put an assistant in the first, the owner in the second and third. Write one open question under each column.", "avoid": "Avoid filling all three columns with one name before you have checked with an actual business.", "synthetic": true}}, "cf25a2c2de15c97e": {"question": "Are the user, payer, and decision-maker the same person?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When the roles belong to one person, selling is simpler; when they differ, you need a path through each person.", "example": "During the team check, mark each interviewed shop: same person for all three roles, or split. A solo seller often holds all three, while a shop with staff may split them. Count both kinds before choosing a sales approach.", "avoid": "Avoid assuming every customer looks like your first interview. Role splits can change between shop sizes.", "synthetic": true}}, "5a733eda50f0b47f": {"question": "Does the user need the solution while the payer refuses to pay?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A user who loves the product cannot rescue a sale if the payer sees no reason to spend money.", "example": "An assistant may want faster listings, while the owner thinks the assistant's time is already paid for. Ask the owner what the listing delay costs them, and listen for consequences they care about, such as late launches.", "avoid": "Avoid treating user enthusiasm as payment intent. The payer needs their own reason to pay.", "synthetic": true}}, "5a8dba480f5670e9": {"question": "Who is the user?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The user is the person whose daily work changes, so their workflow defines what the product must actually handle.", "example": "Ask a seller who sits down to prepare listings and watch that person do it once. Note the files they open, the fields they fill, and where they stop to search for missing information.", "avoid": "Avoid describing the user by job title alone. Describe what they do during the task.", "synthetic": true}}, "744776a1444f3006": {"question": "Who is the payer?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The payer's view of value sets the price ceiling, and it may rest on outcomes the user never sees.", "example": "Ask whose card or account paid for the shop's last software subscription. If it is the owner, ask what made that purchase worth it, and record the reason they gave in their own words.", "avoid": "Avoid assuming the payer values time savings the same way the user does.", "synthetic": true}}, "52f05456c77f9480": {"question": "Who is the decision-maker?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The decision-maker can approve or stop a purchase, so you need to know what evidence they need before saying yes.", "example": "Ask how the shop chose its current store platform or listing template. Note who compared options, who made the final call, and what convinced them. That past story shows how a decision is likely made again.", "avoid": "Avoid asking who would decide in theory. Ask how the last real decision was made.", "synthetic": true}}, "21e2090e527fe548": {"question": "Who influences or blocks the decision?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten from a worksheet field)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "People with no formal authority can still delay or block a purchase, and missing them causes deals to stall unexpectedly.", "example": "In a small brand, a freelance photographer or the person managing the marketplace account might object to a new workflow. Ask whose opinion was needed the last time the shop changed tools, and who complained afterward.", "avoid": "Avoid mapping only the formal approver. Informal influencers can quietly stop adoption.", "synthetic": true}}, "1d7eceaa221b4ce5": {"question": "Does the customer have a budget?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A real need without money set aside often turns into polite interest that never becomes a purchase.", "example": "Ask what the shop currently spends on listing work: a freelancer, a paid template, or staff hours. Existing spending shows where a budget could come from. Record actual amounts they share, not what they say they might pay.", "avoid": "Avoid asking whether they would pay. Ask what they already spend on this work.", "synthetic": true}}, "b8602039d0d2a834": {"question": "Does the customer have decision-making authority?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Talking to someone without authority can produce encouraging conversations that lead nowhere, so confirm who can commit.", "example": "Ask the person you are interviewing whether they could start a paid pilot on their own. If they say they need to check with someone, ask who, and whether you could include that person next time.", "avoid": "Avoid assuming a senior-sounding title means authority to buy. Ask directly how approval works.", "synthetic": true}}, "3633aa0bb2342acd": {"question": "What purchasing process must they follow?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Purchasing steps add time and requirements; knowing them early prevents surprises when a willing customer cannot actually buy.", "example": "A solo seller may pay by card the same day, while a slightly larger brand may need an invoice or an accountant's approval. Ask them to walk through how their last tool purchase was approved and paid.", "avoid": "Avoid assuming small businesses have no process. Even short steps can delay or block payment.", "synthetic": true}}, "398e7d13f0c50f5d": {"question": "Who decides, and who pays?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from the interview flow)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Asking during the interview gets the roles from the customer's own account rather than the team's assumptions.", "example": "Near the end, ask: the last time your shop paid for a tool or service, who suggested it, who approved it, and who paid? Listen for names and steps from a real past event, not a hypothetical answer.", "avoid": "Avoid asking who would decide on our product. People guess about the future; ask about past purchases.", "synthetic": true}}, "ac35e3d4dc175499": {"question": "Can we distinguish the user from the payer?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "If interview notes cannot tell the user and payer apart, later pricing and sales decisions rest on mixed signals.", "example": "Review each interview record and check whether it names who uses the work and who pays for it. If a note only says the seller, go back and clarify which person in the shop played each role.", "avoid": "Avoid writing notes that merge roles into one word like customer. Record each role separately.", "synthetic": true}}, "4177c510cdbe6a08": {"question": "How do customers deal with this problem today?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Customers already handle the problem somehow, and that existing method is the real competitor your idea must beat.", "example": "List the methods you suspect: copying specs from supplier spreadsheets, paying a freelancer per batch, or leaving fields blank. Mark each as a guess and plan to confirm it by watching sellers prepare a listing.", "avoid": "Avoid answering that customers do nothing. Most people have a workaround, even if it is messy.", "synthetic": true}}, "120e89d9e882ad1e": {"question": "Why are existing solutions not good enough?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If you cannot explain the shortfall of existing solutions, you cannot explain why anyone would switch to yours.", "example": "Compare the current options against what sellers say they need: templates may be fast but still miss fields; freelancers may be accurate but slow to schedule. Write each shortfall as something to confirm in interviews.", "avoid": "Avoid listing shortfalls that only the team cares about, such as an outdated interface, without customer evidence.", "synthetic": true}}, "6f549db26704b2f1": {"question": "Why would they change their current habits?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Habits are sticky even when they are inefficient, so a new solution needs a reason strong enough to break routine.", "example": "Ask sellers what changed the last time they switched how they prepare listings, such as a new marketplace rule or a busy season. A past trigger shows what kind of event moves them to change.", "avoid": "Avoid assuming a better product is enough reason to switch. Find the trigger that disrupts the habit.", "synthetic": true}}, "4872f2ae71d20200": {"question": "What is missing from existing solutions?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A specific gap in today's options shows where your team's strengths could matter, instead of competing everywhere at once.", "example": "Look at how sellers use existing listing tools and note what they still do by hand afterward, such as checking sizes against supplier files. That leftover manual step may be the gap worth investigating.", "avoid": "Avoid naming a missing feature without checking that customers actually notice and work around its absence.", "synthetic": true}}, "1fe25efa71ff1bac": {"question": "Why are existing solutions insufficient?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This question sits inside the problem and solution section, so the answer should connect a specific shortfall to your proposed solution.", "example": "For each current option, write one sentence linking its shortfall to your idea: freelancers are slow to book, so a prepared batch within a set time might matter. Mark each link as a hypothesis to check.", "avoid": "Avoid describing shortfalls that your own solution does not address. The link should be explicit.", "synthetic": true}}, "777fd88db3c447a6": {"question": "What alternatives do customers currently use?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Alternatives include more than direct competitors; spreadsheets, freelancers, and staff time all compete for the same job.", "example": "Make a list that includes non-software options: the owner doing it late at night, a family member helping, a freelancer from a gig site, a marketplace's built-in template. Ask interviewees which one they used most recently.", "avoid": "Avoid listing only software products. Manual work and hired help are alternatives too.", "synthetic": true}}, "2c19bbcb5ff021f6": {"question": "Who are the existing competitors?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing existing competitors helps you see what customers already compare you to and where you must differ.", "example": "Search the places sellers look for help: marketplace app stores, seller forums, and freelancer sites. List the products and services that claim to prepare listing data, and note who each one targets.", "avoid": "Avoid saying there are no competitors. If the problem is real, someone or something already addresses it.", "synthetic": true}}, "1fbc689f80dcff0c": {"question": "Why have customers not adopted existing products?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Low adoption of existing products reveals barriers, such as cost, setup effort, or trust, that may block yours too.", "example": "Ask sellers whether they have heard of an existing listing tool and why they do not use it. Record specific reasons, such as setup took too long or results needed heavy editing.", "avoid": "Avoid assuming they did not know the products exist. Often they knew and decided against them.", "synthetic": true}}, "17daf7cf528972e5": {"question": "How does the customer solve it today?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Your hypotheses should describe the current solution in the customer's context, because that sets the bar your product must clear.", "example": "Write the current solution as a hypothesis card: we believe small apparel sellers fill listings from supplier spreadsheets and fix errors after buyers ask. Then note what evidence would confirm or contradict that card.", "avoid": "Avoid writing your assumption about the current solution as settled fact before any interviews.", "synthetic": true}}, "957b302a6d7fb9fd": {"question": "Is the current alternative already good enough?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If today's alternative already works well enough, customers have little reason to switch, regardless of how good your product is.", "example": "Ask a seller how satisfied they are with the result of their current method and what it costs them in time. If they shrug and say it works fine, record that honestly as a reason to reconsider.", "avoid": "Avoid dismissing good-enough answers. They are important evidence that the problem may not be worth solving.", "synthetic": true}}, "79ba5c708b00a0a0": {"question": "What do customers dislike most about their current alternative?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten from a worksheet)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The strongest dislike points to what customers would most value changing, and where your solution should focus first.", "example": "Ask sellers to recall the last time their current method frustrated them and what happened. One may describe re-checking every size field; another may describe waiting for a freelancer. Record the incident, not just the feeling.", "avoid": "Avoid ranking dislikes by your own priorities. Use the customer's recent incidents to decide.", "synthetic": true}}, "a97ce48b2741d97b": {"question": "Could you describe your current process?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "A described process reveals steps, tools, and delays that customers would not mention if asked about the problem directly.", "example": "Ask a seller to walk through their last listing session from start to finish: where the product information came from, which tools they opened, and where they got stuck. Ask to see the files if possible.", "avoid": "Avoid letting them describe an ideal process. Ask about the most recent real session.", "synthetic": true}}, "b42a40ac4d672cf7": {"question": "What alternatives have you tried?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from the interview flow)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Past attempts show how much effort customers have already invested in solving the problem, which signals how much it matters.", "example": "Ask: what else have you tried for preparing listings? Listen for specific names, paid or free, and how long they used each. A seller who tried two tools and a freelancer is more engaged than one who tried nothing.", "avoid": "Avoid suggesting options for them to react to. Let them name what they actually tried.", "synthetic": true}}, "4df17a308cddcf5d": {"question": "Why did you stop using an alternative?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from the interview flow)", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Reasons for abandoning an alternative are warnings; the same reasons could make customers abandon your product too.", "example": "When a seller mentions dropping a tool, ask what happened in the final weeks before they stopped. Listen for concrete events, such as a price increase or listings that still needed manual fixes.", "avoid": "Avoid accepting a vague reason like it did not work. Ask what specifically happened.", "synthetic": true}}, "8f53ab2aefc0da2f": {"question": "How do users solve it today?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In product strategy, the user's current method defines the starting point your product scope must improve on.", "example": "Map the user's current steps for one listing: gather supplier data, write a title, fix photos, fill specs. Mark which steps your first version would replace and which steps the user still does by hand.", "avoid": "Avoid scoping the product around steps the user does not actually perform today.", "synthetic": true}}, "98849ff06e220da6": {"question": "How do they solve the problem now?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing the current solution lets you define a measurable result, such as fewer corrections, rather than vague improvement.", "example": "Pick one measurable part of the current method, such as how many fields a seller corrects after publishing. Record it for a few current listings so you can later compare against your solution's results.", "avoid": "Avoid promising improvement without first recording what the current method actually produces.", "synthetic": true}}, "0b4ca2718a6bf41c": {"question": "How do you solve it now?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Asking the customer directly gets their actual method, which often differs from what the team pictured.", "example": "Ask: the last time you added new products to your store, how did you get the details onto the page? Listen for specific tools, people, and steps, and ask to see an example if they have one nearby.", "avoid": "Avoid asking how they would like to solve it. Ask about the last time they actually did.", "synthetic": true}}, "eff9448d799af913": {"question": "What do competitors’ users complain about most often?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Recurring complaints about competitors show unmet needs, and a gap repeated by many users is worth investigating.", "example": "Read public reviews and seller forum threads about listing tools. Record which complaints appear repeatedly, such as missing fields after import or slow support, and note the type of seller writing each one.", "avoid": "Avoid treating one angry review as a pattern. Look for complaints repeated across users.", "synthetic": true}}, "f85f607835c5cb3a": {"question": "Which workflow is cumbersome?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A cumbersome workflow inside existing tools can be a practical entry point, because users already feel the friction.", "example": "Watch a seller use their current listing tool and count steps they repeat or redo, such as resizing each photo separately. Note where they sigh or switch windows; those moments mark the cumbersome workflow.", "avoid": "Avoid judging workflows from screenshots alone. Watch someone use the tool for a real task.", "synthetic": true}}, "7a95d14d0aee396b": {"question": "Which feature do customers keep asking for that competitors have not addressed?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A feature customers keep asking for, yet competitors ignore, may signal an opening, or a request that is hard to serve.", "example": "Collect feature requests from seller forums and interviews, such as checking listings against marketplace rules before upload. Note how often each request appears, from which kind of seller, and whether any existing tool offers it.", "avoid": "Avoid building every requested feature. Check why competitors skipped it before assuming they simply missed it.", "synthetic": true}}, "ed2b1c1bc430cca9": {"question": "Who are our competitors?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A pitch needs a clear competitor view so listeners understand what customers compare you to and how you differ.", "example": "For the pitch, group competitors into direct tools, hired help such as freelancers, and doing it by hand. For each group, state one difference you aim to offer, marked as your claim to test.", "avoid": "Avoid a pitch slide claiming no competition. Avoid comparing only features while ignoring manual alternatives.", "synthetic": true}}, "6c8718cdf838d14b": {"question": "How many people face this problem?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The number of people facing the problem sets the ceiling on how far the venture can grow from it.", "example": "Estimate from a defined group: suppose you count small sellers on one marketplace who list new products monthly. Write the counting method and its sources, and mark the result as an estimate to refine.", "avoid": "Avoid quoting a large total for all online sellers without explaining how you counted.", "synthetic": true}}, "393b367e23fd10a1": {"question": "Why now?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Investors and teams need to know what has changed recently that makes this the right moment, not five years ago.", "example": "Look for recent shifts that affect the demo venture: marketplaces tightening listing requirements, or tools that make image and text preparation cheaper. Explain how each change makes the problem more pressing or the solution more feasible.", "avoid": "Avoid generic answers like the market is growing. Name a specific recent change.", "synthetic": true}}, "fe5d25a03724da1d": {"question": "How large is the market?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Market size helps you and listeners judge whether the opportunity can support the venture you want to build.", "example": "Build the estimate from the bottom up: number of target sellers you can count, times a price you plan to test, times a realistic purchase frequency. Show each input and mark which ones are assumptions.", "avoid": "Avoid citing a large top-down industry figure without connecting it to your specific customers.", "synthetic": true}}, "d6272fa86d4cbd9b": {"question": "What growth potential and future opportunities does the market have?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Growth potential shows whether the market will expand, and where the venture could go after the first customer group.", "example": "Describe possible next steps for the demo venture: from small apparel sellers to other product categories, or from listings to other store content. Mark each as a future option, not a plan already underway.", "avoid": "Avoid presenting future expansion as certain. Show which first results would need to happen first.", "synthetic": true}}, "6cc224fa11d82d12": {"question": "If a better-funded, technically stronger team builds the same product in six months, what advantage will we still have?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Money and engineering can be copied; this question forces you to find what a stronger team cannot easily replicate.", "example": "Suppose a larger team builds the same listing tool. You might still have close relationships with a group of sellers, or knowledge of their supplier formats gathered from serving them. Write what you would have, and how you would know.", "avoid": "Avoid answering that you will move faster or work harder. Those are not lasting advantages.", "synthetic": true}}, "28d9fefc459f2aad": {"question": "What network effects could make the business more valuable as it grows?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Network effects make the product more valuable as more people use it, which can protect a business over time.", "example": "For the demo venture, consider whether each new seller's supplier files could improve how future listings are prepared, or whether suppliers would join to serve many sellers. Mark each as a possibility to check, not a feature.", "avoid": "Avoid claiming network effects when more users simply means more revenue. Show how value grows per user.", "synthetic": true}}, "69bda11b26d0debc": {"question": "What would make it difficult for customers to switch away?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Switching costs keep customers even when a competitor appears, but they should come from value delivered, not lock-in tricks.", "example": "Suppose sellers save their product templates, supplier mappings, and listing history in your service. Over time, moving to another tool means rebuilding that setup. Note which of these a seller would actually miss.", "avoid": "Avoid relying on contracts or blocked data exports. Customers resent switching costs that are not based on value.", "synthetic": true}}, "73d93b2d48af922f": {"question": "Can we build a defensible advantage?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A business without defensibility can be copied quickly once it shows promise, which limits how long early work pays off.", "example": "List possible sources of defense for the listing service, such as accumulated data or seller relationships. For each, describe what would need to be true a year from now for it to protect you, and how you would check.", "avoid": "Avoid answering yes without naming a specific mechanism. Defensibility needs a concrete source.", "synthetic": true}}, "a4b4e7355ab76ecf": {"question": "Which advantages can we build through technology, data, brand, distribution, regulation, or supply chains?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Checking each source separately helps you find realistic advantages instead of claiming a vague edge across everything.", "example": "Go through each source for the demo venture: data from many supplier formats, a brand trusted by small sellers, distribution through a marketplace partner. Mark which ones you could build in a year and which are unlikely.", "avoid": "Avoid claiming all six sources at once. Choose the one or two you can actually build.", "synthetic": true}}, "bae585a71c64afc2": {"question": "What capabilities and advantages enable this team to execute the venture?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In a pitch, listeners want to know why this team, specifically, can carry out the plan it describes.", "example": "For the demo venture's founding team, list concrete capabilities: one founder managed listings for a small shop, another builds data tools. Connect each capability to a specific part of the plan it makes possible.", "avoid": "Avoid listing impressive titles or schools without linking them to work this venture requires.", "synthetic": true}}, "6a168fa8943c7d08": {"question": "What have we observed so far?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Observation is the raw material for every later claim. Listing what you actually saw keeps early discussion anchored in events rather than opinions.", "example": "Write down only things someone on the team witnessed: a seller retyping a product spec from a supplier PDF, or a listing paused because a photo was missing. Note who saw it, when, and where. Leave interpretations for a separate column.", "avoid": "Avoid listing what you expect sellers to experience as if someone on the team had already watched it happen.", "synthetic": true}}, "a69cf1ed4ecd6452": {"question": "What initial evidence do we have?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Early evidence does not need to be strong, but it needs to exist. Naming it shows how much of the plan rests on something outside the team.", "example": "Initial evidence might be three notes from conversations with sellers, a screenshot of a seller forum thread about missing fields, or your own record of preparing listings for a friend's shop. Mark each item with its source and date so its weight is easy to judge.", "avoid": "Avoid counting enthusiasm from friends, or the fact that the idea feels obvious, as initial evidence.", "synthetic": true}}, "fd146da1df1a8021": {"question": "Which parts have been confirmed?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Separating confirmed parts from the rest tells you where you can build with some confidence and where you are still guessing.", "example": "Go through the canvas and mark a part as confirmed only when a specific source backs it. For example, if two sellers showed you their listing spreadsheets with empty spec columns, the problem description may be confirmed for that group. Willingness to pay may still be open.", "avoid": "Avoid marking a part confirmed because the team agrees on it or because nobody has challenged it yet.", "synthetic": true}}, "ac6dd356b74a242b": {"question": "What did customers say?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "What customers say reveals their language, priorities, and frustrations. It is useful input, but it needs to be kept distinct from what they actually do.", "example": "After each conversation, copy the seller's own phrases into the notes, such as how they describe the night before a product launch. Group statements by topic, and mark which ones describe a past event and which are opinions about the future.", "avoid": "Avoid paraphrasing customers into your own product vocabulary, or treating polite praise for the idea as a signal of demand.", "synthetic": true}}, "957565ea0ab44281": {"question": "What did customers actually do in the past?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Past actions cost customers time or money, so they reveal real priorities more reliably than stated preferences or predictions about future behavior.", "example": "Record actions such as a seller hiring a freelancer last month to fix listing photos, or building their own spec template. Ask to see the artifact: the invoice, the spreadsheet, the message thread. Note when it happened and how much effort it took.", "avoid": "Avoid substituting what customers say they would do for what they have already done.", "synthetic": true}}, "a9f19a758281c277": {"question": "What evidence supports our assumptions?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Each assumption should point to the evidence behind it. Assumptions without support are where the plan is most exposed.", "example": "Make two columns. On the left, write an assumption such as \"sellers launch products in batches.\" On the right, list the specific sources that support it, for instance a seller's launch calendar you were shown. Leave the right side empty when nothing supports it yet.", "avoid": "Avoid listing the same piece of evidence under every assumption to make the canvas look complete.", "synthetic": true}}, "135d08f951fa894d": {"question": "What evidence contradicts our assumptions?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Contradictions can prevent expensive work on the wrong problem.", "example": "An interview might reveal that the seller only spends a few minutes on this task. If observed, keep that statement alongside supporting evidence.", "avoid": "Avoid keeping only evidence that supports your idea.", "synthetic": true}}, "abb0268362589e16": {"question": "Does the information come from government data, academic research, an industry report, or an anonymous article?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Sources differ widely in reliability. Knowing where a figure came from tells you how much weight it can carry in a decision.", "example": "Suppose you find a statistic about how many small online shops sell on more than one marketplace. Trace it back: is it from a statistics office, a peer-reviewed paper, a vendor's industry report, or an unsigned blog post? Record the original source next to the number.", "avoid": "Avoid repeating a number from a secondary article without finding and naming the original source behind it.", "synthetic": true}}, "0d74bf7f958f254d": {"question": "Does the information still reflect current market conditions?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Markets change quickly. Older information may describe platforms, tools, or seller habits that no longer apply to the customers you are studying.", "example": "Check the publication date of every source. If a report on online seller tools predates major changes in marketplace listing rules or the spread of AI writing tools, treat it as background only and look for newer seller conversations.", "avoid": "Avoid relying on a source simply because it is well known, without checking when its data was collected.", "synthetic": true}}, "96f5b09c9ce718ce": {"question": "Is the information relevant to our actual target customers?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Data about a broad market may not describe the specific customers you plan to serve. Relevance matters as much as reliability.", "example": "A report on large online retailers with in-house design teams says little about a two-person shop listing products from a spreadsheet. Check whether each source covers sellers of your size, region, and platform before using it.", "avoid": "Avoid stretching findings about large companies or a different region to cover small sellers without dedicated designers.", "synthetic": true}}, "9a9f495d2849527d": {"question": "Can real customer interviews support the claim?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Desk research can suggest a pattern, but interviews show whether the pattern appears in your customers' actual work. The two should point the same way.", "example": "If a report suggests small sellers struggle with product photos, plan interviews to check it. Ask several sellers to walk you through their last listing and see whether photos come up without prompting. Note where interviews agree with the claim and where they do not.", "avoid": "Avoid treating a claim as settled because it appears in an article, without hearing it from customers.", "synthetic": true}}, "75402a460af0f714": {"question": "Which statements are facts, and which are speculation?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Facts and speculation look the same in a slide. Labelling them shows the team where decisions rest on observation and where they rest on guesses.", "example": "Read each sentence in your problem statement and tag it. \"A seller we interviewed delayed a launch because supplier specs arrived late\" is a fact from one event. \"Most small sellers face this every week\" is speculation until you collect more cases.", "avoid": "Avoid upgrading a single interview into a general fact by dropping who said it and when.", "synthetic": true}}, "d8f7160ba3eb3c00": {"question": "Where is this analysis most likely to be wrong?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "(rewritten from a material instruction)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Every analysis has weak points. Naming the likeliest failure early tells you where to look before you invest more time or money.", "example": "Review your analysis and ask which link has the least support. For the listing venture, perhaps the problem is real but sellers solve it cheaply with a template. Write that down as the most likely error and plan a check for it.", "avoid": "Avoid answering with general risks like competition or funding instead of the specific step most likely to be wrong.", "synthetic": true}}, "ed7e15be98460a02": {"question": "What evidence would disprove this assumption?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "An assumption you cannot disprove cannot guide decisions. Defining contrary evidence in advance keeps the team honest when results arrive.", "example": "For the assumption \"sellers spend significant time fixing missing fields,\" decide beforehand what would count against it. Example only: if most sellers you interview describe the task as quick and cannot recall a recent problem, treat the assumption as weakened.", "avoid": "Avoid defining disproof so narrowly that no realistic result could ever count against the assumption.", "synthetic": true}}, "03e965ce974d6447": {"question": "How would a customer who does not want to buy challenge our argument?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "(rewritten from a material instruction)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Customers who will not buy reveal objections the team tends to overlook. Arguing from their side exposes weak points before the market does.", "example": "Role-play a seller who declines. They might say their marketplace already suggests missing fields, or that their nephew handles listings for free. Write down each objection and check whether real sellers raise it in interviews.", "avoid": "Avoid inventing weak objections that are easy to answer instead of the strongest reasons a seller might say no.", "synthetic": true}}, "dd3faa18a5846f2e": {"question": "What real-world data is still needed to support this conclusion?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A conclusion is only as strong as its missing pieces. Listing the data still needed turns a vague worry into specific research tasks.", "example": "If you conclude that sellers would pay for listing preparation, list what is still missing: how often they list, what they spend now, and who approves spending. Next to each gap, note how you could obtain it, such as asking to see a recent invoice.", "avoid": "Avoid treating a conclusion as ready while the data it depends on is still on the to-collect list.", "synthetic": true}}, "4b813516f2b929b1": {"question": "Does the team already have initial evidence?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This is a quick check on whether the team is starting from observation or from belief. It sets expectations for how much validation lies ahead.", "example": "Ask each team member to name one piece of evidence they gathered themselves, such as a seller conversation or a listing they helped prepare. If nobody can, record that honestly and plan the first evidence-gathering step before dividing other work.", "avoid": "Avoid answering yes because team members have personal opinions or industry experience that has not been checked with sellers.", "synthetic": true}}, "f89dcd86c7db723c": {"question": "Which parts already have evidence?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Evidence is usually uneven across the canvas. Seeing which sections have support helps the team decide where to direct effort next.", "example": "Walk through problem, customer, market, and solution in turn. For the listing venture, the problem section might have notes from seller conversations while pricing has nothing. Mark sections as having evidence, partial evidence, or none, and attach the source to each mark.", "avoid": "Avoid spreading one strong piece of evidence across every section so the whole canvas appears supported.", "synthetic": true}}, "51fbd5f0ec70d1d5": {"question": "Which assumptions did this interview support?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Linking each interview to specific assumptions shows what the conversation actually taught you, instead of leaving it as a general impression.", "example": "After an interview, list the assumptions it touched. If the seller showed a spreadsheet where supplier specs were pasted in by hand every week, note that it supports the assumption about recurring manual work. Quote the moment that supports it.", "avoid": "Avoid marking an assumption as supported because the seller agreed with your description when you stated it for them.", "synthetic": true}}, "01be1810fb135761": {"question": "Which assumptions did this interview disprove?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviews that contradict your assumptions are among the most valuable. Recording them explicitly stops the team from quietly ignoring inconvenient results.", "example": "If a seller says supplier data always arrives complete and their real delay is photography, note that it contradicts the missing-fields assumption. Record the exact words and the event they described, and keep this note alongside the supporting interviews.", "avoid": "Avoid explaining away a contradicting interview as an unusual customer before checking whether others say the same.", "synthetic": true}}, "931f9cc3f2d9dcbf": {"question": "Has the customer already invested in people, software, consultants, or another solution?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Existing spending shows the problem already matters enough to cost money or time. It also shows what you will be compared against.", "example": "Ask sellers what they currently use for listing preparation. One might pay a freelancer per batch, another might use a spreadsheet template, another might have a part-time assistant. Record what they pay or how many hours they spend.", "avoid": "Avoid assuming that no current spending means an open market; it may mean the problem is not important enough.", "synthetic": true}}, "4ef98f7eefbe2dfd": {"question": "What evidence shows that the problem exists?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Product strategy depends on a real problem. Before deciding scope, the team should be able to point to evidence, not just describe the problem convincingly.", "example": "Collect concrete traces: screenshots of listings rejected for missing fields, a seller's message asking a supplier for specs, or notes from watching a seller prepare a batch. Each item should show the problem happening in a specific business on a specific day.", "avoid": "Avoid using a clear problem statement or a large market estimate as a stand-in for evidence that the problem occurs.", "synthetic": true}}, "d857cf05504426a2": {"question": "Have we already talked to customers?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "At the idea stage, talking to customers is the quickest way to learn whether the problem you imagine matches how people actually work.", "example": "Count the conversations you have actually had with small sellers about how they prepare listings. A casual chat with a shop owner at a market counts if you asked about their process. Note how many and when, even if the answer is none.", "avoid": "Avoid counting conversations where you pitched the idea and asked for feedback as customer discovery.", "synthetic": true}}, "204259bb3e9fd18a": {"question": "Who have we interviewed?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing exactly who you interviewed shows whether your evidence comes from your target customers or from people who are easy to reach.", "example": "Keep a simple list: business type, size, platform, who you spoke with, and date. For example, a two-person shop selling home goods on one marketplace, interviewed with the owner. Check whether the list matches the customer you defined.", "avoid": "Avoid summarizing as \"several sellers\" without recording who they were and whether they fit the target customer.", "synthetic": true}}, "b953397f4ecc9d37": {"question": "Do we need to contact them again?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A second conversation can fill gaps, check what changed, or move toward a test. Deciding deliberately keeps relationships useful rather than accidental.", "example": "Review each interview for open questions. If a seller mentioned a supplier spec sheet but you did not see it, ask to follow up and look at the next one. If they fit a planned pilot, note them for later contact.", "avoid": "Avoid contacting everyone again by default, or no one, without a specific reason for each follow-up.", "synthetic": true}}, "b4ef6de4242ce05b": {"question": "Can we obtain customer feedback quickly?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Fast feedback lets the team learn in days rather than months. Slow access to customers is a constraint worth knowing early.", "example": "List the channels you could use this week: seller groups you belong to, shops you already buy from, or a relative who sells online. Estimate how many replies each could bring and how long it would take to arrange a conversation.", "avoid": "Avoid assuming access will be easy because the customer group is large, without testing a real channel.", "synthetic": true}}, "6efb4a1b85f47b9f": {"question": "Is the team willing to contact customers soon?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A plan that depends on interviews fails if nobody wants to make the calls. Willingness is a team fact that should be stated openly.", "example": "Ask each person whether they are ready to message sellers this week and how many they will contact. If someone is uneasy, pair them with a teammate for the first call or give them note-taking first.", "avoid": "Avoid agreeing in principle while postponing outreach until the product or pitch feels more polished.", "synthetic": true}}, "569b3e4f46cca454": {"question": "Who are the first customers we will interview?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The first interviews shape early conclusions. Choosing them on purpose makes those conclusions about your target customer, not just about whoever replied.", "example": "Name specific people or businesses: the owner of a small clothing shop you know, two sellers from a local marketplace group, a shop that recently launched new products. Check each against your customer definition before booking.", "avoid": "Avoid starting only with friends and family because they are convenient, if they do not match the target customer.", "synthetic": true}}, "26f6a3fbed82c0d0": {"question": "How many customers will we interview first?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A target number makes the plan concrete and tells the team when to stop and review, instead of interviewing indefinitely.", "example": "Example only: decide in advance how many suitable sellers you will interview before the first review, and what you will look for across them. Choose a number the team can finish in the time available, then reassess.", "avoid": "Avoid picking a large number to feel thorough when the team cannot realistically complete it before the next decision.", "synthetic": true}}, "c1389e5422fff5f7": {"question": "Who will contact them?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Outreach without an owner tends not to happen. Assigning a person makes contact a commitment rather than a shared intention.", "example": "Assign each person on the interview list to one teammate who sends the first message, schedules the call, and confirms afterwards. For instance, one founder contacts the marketplace group while another reaches out to shops they buy from.", "avoid": "Avoid writing \"the team\" as the owner, which leaves everyone assuming someone else will make contact.", "synthetic": true}}, "cddeaea851820ba4": {"question": "When will the interviews be completed?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A completion date turns interviews into a scheduled step and sets when the team will meet to review what it learned.", "example": "Pick a date when all first-round interviews should be done and a review meeting is held. Suppose the team has two weeks: book the review now, and check midway how many sellers have confirmed a time.", "avoid": "Avoid leaving the date open until enough interviews happen, which usually means the review never happens.", "synthetic": true}}, "0cb5a85af1ed10b8": {"question": "How will we organize the results?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Notes that live in different heads and formats are hard to compare. Agreeing on a structure first makes patterns visible across interviews.", "example": "Use one shared sheet with a row per interview: who, date, the past event described, exact quotes, assumptions supported or contradicted, and follow-ups. Fill it in within a day of each call while details are fresh.", "avoid": "Avoid relying on memory or loose notes until the end, when details have blurred into general impressions.", "synthetic": true}}, "f606ce05f3264361": {"question": "Are our questions about past behavior?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Questions about past behavior draw out what actually happened. Questions about the future invite guesses and politeness.", "example": "Instead of asking whether a seller would use a listing tool, ask: \"Tell me about the last time you listed a batch of new products. What did you do first?\" Listen for dates, tools, and who was involved.", "avoid": "Avoid hypothetical questions like \"Would you pay for this?\" that ask customers to predict their own behavior.", "synthetic": true}}, "1abd735a181eafe7": {"question": "Are we asking for specific examples?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "General answers hide the details that matter. A specific example shows frequency, effort, and consequences in a form you can check.", "example": "When a seller says listing is \"always a hassle,\" ask for the most recent instance: \"Which product was it? What was missing? How did you get the information?\" Ask them to show the spreadsheet or message if possible.", "avoid": "Avoid accepting summaries like \"usually\" or \"all the time\" without asking for one concrete recent case.", "synthetic": true}}, "4242c71608d13d53": {"question": "Are we introducing the product too early or too much?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Describing the product early shifts the conversation to reacting to your idea and away from the customer's own experience.", "example": "Spend the conversation on how the seller prepares listings today. Mention the product only at the end, briefly, if at all. If you find yourself explaining features in the first ten minutes, steer back to their last listing session.", "avoid": "Avoid opening with a demo or pitch, which invites polite feedback instead of honest accounts of past work.", "synthetic": true}}, "38d92b707229443c": {"question": "Are any of our questions leading?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Leading questions suggest the answer you hope for. Customers often agree to be polite, which produces evidence that only reflects your wording.", "example": "Compare \"Isn't it frustrating when supplier specs are missing?\" with \"What happened the last time you prepared a product listing?\" The second leaves room for the seller to raise the problem, or not.", "avoid": "Avoid questions that name the problem or emotion you expect, then counting the customer's agreement as evidence.", "synthetic": true}}, "ff223885f5672954": {"question": "Are we talking too much?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviews are for hearing the customer. When the interviewer talks most of the time, the notes mainly capture the team's own views.", "example": "After a call, estimate who spoke more, or review a recording with permission. Example only: decide on a rough share of talking time you aim to keep, and note moments where you explained instead of asking.", "avoid": "Avoid filling silences with explanations; a short pause often gives the seller time to add something important.", "synthetic": true}}, "d742c86e4f400bd6": {"question": "Are we following up on specific events?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "The most useful detail often comes after the first answer. Following up on a mentioned event uncovers causes, costs, and workarounds.", "example": "If a seller mentions a product launched late last month, ask what caused the delay, who fixed it, how long it took, and what happened to sales plans. Stay with that one event before moving on.", "avoid": "Avoid moving to the next scripted question when the customer has just mentioned a concrete event worth exploring.", "synthetic": true}}, "c8234fd27a008f78": {"question": "Are we recording the customer’s exact words?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Exact words keep the customer's meaning intact and are easier to compare later. Paraphrases tend to drift toward what the team expects.", "example": "Write down phrases word for word, such as how a seller describes chasing a supplier for size charts. Mark them as quotes in the notes. If recording, ask permission first and still note key lines during the call.", "avoid": "Avoid rewriting what the customer said into your product language before anyone else on the team has seen it.", "synthetic": true}}, "533b66e55536a83e": {"question": "Which customers are most willing to be interviewed?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Customers who readily agree to talk may be the ones who feel the problem most. Their willingness itself is a signal worth noting.", "example": "Track who responds to outreach and how quickly. If sellers who launch new products often reply sooner than occasional sellers, note that pattern. Ask willing interviewees whether they know others with a similar listing workload.", "avoid": "Avoid assuming that the most willing interviewees represent every customer; they may be unusually engaged or curious.", "synthetic": true}}, "61aa933f232393c0": {"question": "What is our most important assumption?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A test is useful when it targets something that could change the decision.", "example": "We assume sellers will pay to reduce listing preparation time. The next test must investigate payment, not just whether our demo looks good.", "avoid": "Avoid testing a polished demo when payment is the uncertain assumption.", "synthetic": true}}, "d5d7150a9b560fb7": {"question": "Which parts are still speculation?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Once the problem, customer, market, and solution are sketched, marking speculation shows which parts of that sketch were written without information from outside the team.", "example": "Highlight statements in each section that came from reasoning alone. For the listing venture, \"sellers would switch from their current spreadsheet\" may be speculation if no seller has said or done anything to suggest it.", "avoid": "Avoid treating speculation as harmless filler; it often sits under the parts the plan depends on most.", "synthetic": true}}, "157f42b4345648ef": {"question": "Which assumptions should we validate first?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Not every assumption deserves a test now. Ordering them focuses limited time on the ones that would change your direction.", "example": "Rate each assumption on two points: how much the plan depends on it and how little evidence supports it. For the listing venture, whether sellers face missing fields often might come before which file format they prefer.", "avoid": "Avoid starting with the easiest assumption to test simply because it gives quick results.", "synthetic": true}}, "ef06fcf1d83ce7f1": {"question": "Which parts are still assumptions?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Writing assumptions out explicitly makes them testable. When they stay implicit, the team debates conclusions instead of the beliefs underneath.", "example": "Turn each unsupported belief into a sentence that can be checked: \"Sellers prepare new listings at least monthly,\" or \"The shop owner makes the purchase decision.\" Keep these in a list separate from the evidence log.", "avoid": "Avoid writing assumptions so vaguely, such as \"sellers want efficiency,\" that no evidence could confirm or contradict them.", "synthetic": true}}, "7ffb839312bc9a7e": {"question": "Which parts are still imagination?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When dividing work and forming a team, it helps to admit which parts exist only in imagination so tasks focus on checking them.", "example": "Look for pieces that rely on a picture in your head: a seller happily uploading a supplier PDF and getting finished listings. Ask which steps of that picture nobody has seen in real life, and assign someone to investigate one.", "avoid": "Avoid dividing work around an imagined product flow as if customers had already shown they would follow it.", "synthetic": true}}, "8905d452dee23b35": {"question": "Which assumption would invalidate the venture if it were wrong?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Some assumptions carry the whole venture. Finding the one that would end it tells the team what to check before committing more effort.", "example": "Ask: if this were wrong, would we stop? For the listing venture, the deciding assumption might be that sellers face listing preparation often enough to want help. If they list only twice a year, the venture may not hold.", "avoid": "Avoid naming several assumptions as equally critical so the team never has to choose which one to test first.", "synthetic": true}}, "dd31e391e2e1d7b4": {"question": "Which assumption would invalidate the entire business model if it were wrong?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A business model connects customer, value, payment, and delivery. One broken link can stop money from flowing even if the problem is real.", "example": "Trace the model step by step: seller has the problem, seller pays, team delivers at a sustainable cost. Perhaps the weakest link is cost: preparing listings manually may take longer than the price allows. Name that link explicitly.", "avoid": "Avoid focusing only on whether customers like the product, while ignoring payment, cost, and who controls the budget.", "synthetic": true}}, "3a31e3afb91ced5b": {"question": "What are the hidden assumptions behind our idea?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "(rewritten from a course exercise)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Hidden assumptions are the ones nobody wrote down because they felt obvious. They can fail silently and undermine a plan that looked sound.", "example": "Read your idea aloud and ask \"what must be true for this to work?\" after each sentence. For the listing venture, hidden assumptions might include that sellers can share supplier files or that listing rules are similar across platforms.", "avoid": "Avoid listing only the assumptions you have already discussed; the exercise is about the ones taken for granted.", "synthetic": true}}, "d6ddf8150808faf7": {"question": "Would the idea still work if this assumption were false?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Testing an assumption against its opposite shows how much the idea depends on it. This helps separate critical assumptions from minor details.", "example": "Take one assumption, such as \"sellers prefer to upload files rather than type data.\" Imagine it is false. If the venture could switch to a guided form and still deliver value, the assumption matters less than one that would end the idea.", "avoid": "Avoid answering yes without working through what would actually change in the customer, offer, or delivery.", "synthetic": true}}, "2279afc7ed02a30f": {"question": "Which assumptions remain unconfirmed?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from an assignment instruction)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "After a round of interviews, some assumptions remain open. Listing them shows what the next interviews or tests still need to cover.", "example": "Compare the assumption list with interview notes. For example, the team may have heard enough about how sellers prepare listings but nothing about who approves spending. Mark that assumption as unconfirmed and plan questions for it.", "avoid": "Avoid marking an assumption confirmed because interviews did not contradict it; absence of contrary evidence is not support.", "synthetic": true}}, "2f44d776aa353ee3": {"question": "What is our most dangerous, least-proven assumption?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In product strategy, the riskiest assumption with the least support is where building too early wastes the most effort.", "example": "Combine two judgments: how damaging it would be if wrong, and how little evidence you have. For the listing venture, it might be that sellers trust automated data enough to publish without checking each field.", "avoid": "Avoid choosing an assumption that is risky but already well supported, or one that is uncertain but has little consequence.", "synthetic": true}}, "aaf85984756d2e44": {"question": "Which business hypothesis will this feature validate?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Each feature should exist to learn something or deliver something tested. Linking it to a hypothesis keeps the product scope tied to decisions.", "example": "Before building a feature that flags missing fields, write the hypothesis it tests: \"Sellers will fix flagged fields before publishing rather than ignoring the flags.\" Then decide what usage would support or contradict that.", "avoid": "Avoid building features because competitors have them or because they are interesting to build, with no hypothesis attached.", "synthetic": true}}, "be92af2d265496e2": {"question": "How will we validate the problem next?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "At the idea stage, the next step should check whether the problem is real for real people, before any time goes into solutions.", "example": "Pick one method for the coming week, such as asking several small sellers to walk through their most recent listing session, or sitting beside one seller while they prepare a batch. State what you hope to observe.", "avoid": "Avoid jumping to a prototype or landing page before checking that the problem exists for your intended customer.", "synthetic": true}}, "372afd29520b5c8d": {"question": "Could we test it with a manual service, a form, a presentation, or a simple prototype?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Lightweight formats let you test value long before building software. They make learning cheaper and faster when little is known.", "example": "For the listing venture, the team could prepare one seller's listings by hand, share a simple form asking for supplier files, or show a short slide sequence of the intended process. Choose the format that tests the specific assumption at hand.", "avoid": "Avoid dismissing manual or low-fidelity tests as unprofessional and jumping straight to building a working system.", "synthetic": true}}, "90ba4784ca7af67f": {"question": "What most needs to be validated next?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When the canvas is first filled in, many things are uncertain. Choosing the one most in need of validation prevents scattered effort.", "example": "Look across problem, customer, market, and solution and pick the uncertain item the plan relies on most. For the listing venture, that might be whether the chosen seller group lists new products often enough to care.", "avoid": "Avoid naming everything as needing validation, which leaves the team without a clear next step.", "synthetic": true}}, "e8b3ca99993f17a1": {"question": "What will we test next?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Moving from evidence review to a decision requires naming one concrete test. Without it, discussion of evidence does not change what the team does.", "example": "State the test in one sentence with a method and target group: \"Interview sellers who launched products last month about how they gathered specs.\" Note which open question from the evidence review it addresses.", "avoid": "Avoid naming a topic like \"pricing\" instead of a specific test with a method, audience, and expected observation.", "synthetic": true}}, "686da165d10ea5b2": {"question": "Who will be responsible for the test?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A test needs one owner who prepares it, runs it, and reports back. Clear ownership prevents the test from stalling between people.", "example": "Assign one founder to run the test, even if others help. For example, one founder schedules the seller sessions and writes up results, while another joins as note-taker. Write the owner's name next to the test.", "avoid": "Avoid sharing responsibility so broadly that nobody feels accountable for finishing the test and reporting results.", "synthetic": true}}, "caba9abf250b6e77": {"question": "When will it be completed?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A deadline sets when results will be reviewed and the next decision made. Without one, tests tend to stretch on.", "example": "Set a date for the test and a review meeting right after it. Suppose the test is a round of seller sessions: choose the finish date now, and agree what the team will do if fewer sessions are completed by then.", "avoid": "Avoid open-ended timing such as \"when we have time,\" which makes the test easy to postpone indefinitely.", "synthetic": true}}, "17ae31d68e846bed": {"question": "Which assumption will this tool help us validate?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Tools such as surveys, interviews, or prototypes each suit different assumptions. Naming the assumption first helps you pick a tool that can actually answer it.", "example": "If the assumption is that sellers lose time chasing supplier specs, an interview about a recent listing fits. If the assumption is about willingness to pay, a paid pilot offer fits better than a satisfaction survey.", "avoid": "Avoid choosing a tool because it is familiar or easy, then searching afterward for an assumption it might address.", "synthetic": true}}, "1a60a8bdbbbc02f0": {"question": "What is the next action?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "(rewritten from a record field)", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Each interview record should end with a concrete action. This keeps learning connected to what the team does next.", "example": "At the bottom of each interview note, write one action with an owner: send the seller a follow-up asking for their supplier file, add a question about budget to the guide, or invite them to a pilot.", "avoid": "Avoid ending notes with a general comment like \"interesting conversation\" that does not lead to any specific next action.", "synthetic": true}}, "852b9166b3a8a0b5": {"question": "What will we learn from this experiment?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Stating the expected learning before running an experiment keeps the result interpretable. It also shows whether the experiment is worth its cost.", "example": "Before the experiment, write what result would mean what. For instance, if sellers who receive manually prepared listings publish them without edits, that suggests the output meets their needs. If they rewrite most fields, the team learns something different.", "avoid": "Avoid running an experiment first and deciding afterward what it was supposed to teach you.", "synthetic": true}}, "5914ef41f87fd7c4": {"question": "What do we want to validate with this minimum viable product?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A minimum viable product is a learning tool. Without a clear question, it becomes a small product built without purpose.", "example": "Write the question the MVP answers, such as whether sellers will send real supplier files and publish the prepared listings. Keep only what is needed to answer that, and leave out features unrelated to it.", "avoid": "Avoid treating the MVP as a first release to impress customers rather than a tool to answer one question.", "synthetic": true}}, "6c92ac10ceb507d5": {"question": "What is the smallest thing we can do to test it?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Smaller tests are faster and cheaper, so the team can learn and adjust more times before resources run out.", "example": "Ask what you can do this week without code. For the listing venture, that might be preparing a single product listing for one seller from their supplier file and watching whether they use it.", "avoid": "Avoid calling something small when it still requires weeks of building before any customer can respond to it.", "synthetic": true}}, "b9095bf29f8694ca": {"question": "Can we test demand with a landing page and waiting list?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A landing page with a waiting list shows whether people take a small action after reading a clear offer, which is more informative than stated interest.", "example": "Describe the listing preparation service on a simple page and ask visitors to join a waiting list. Record how many suitable sellers reach the page and how many sign up. Follow up with sign-ups to confirm they fit.", "avoid": "Avoid reading sign-ups as purchase intent; joining a list costs little, so confirm interest with a follow-up conversation.", "synthetic": true}}, "1e08da1daf1ae116": {"question": "Can we test interest in a feature before building it, while clearly disclosing that it is not ready?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Testing interest before building saves effort on features nobody uses. Honest disclosure keeps customer trust while still measuring real interest.", "example": "Add an option such as \"generate listing photos\" to the order form, labelled clearly as not yet available. Record how many sellers select it and ask them what they expected. Tell them plainly when or whether it will exist.", "avoid": "Avoid hiding that the feature is not ready, which damages trust and makes the signal hard to interpret.", "synthetic": true}}, "aa9ee1ccb0510988": {"question": "Can an explainer video test interest through demo requests or pre-orders?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A short video can show how a product would work before it exists. Requests for demos or pre-orders turn passive viewing into a measurable action.", "example": "Record a brief video showing a seller uploading a supplier file and receiving prepared listings, and say clearly that this is a concept. Add a button to request a demo or place a refundable pre-order, and record who takes that step.", "avoid": "Avoid counting views or likes as interest; only demo requests or pre-orders show willingness to take action.", "synthetic": true}}, "2fbd01d1566c0af4": {"question": "Can we deliver the result manually before automating it?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Delivering manually shows what customers really need from the result before you invest in automation that might target the wrong steps.", "example": "For the first few sellers, the team fills in listing data by hand from supplier files. Track how long each step takes and which fields cause problems. Automate only the steps that repeat and that sellers clearly value.", "avoid": "Avoid automating early because manual work feels unscalable, before learning which parts of the result sellers care about.", "synthetic": true}}, "efcc937fe4743457": {"question": "Could a concierge service test whether customers value the outcome?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A concierge service delivers the outcome personally and closely. It shows whether customers value the result itself, separate from any interface or software.", "example": "Offer a small group of sellers a hands-on service: the team works with each seller directly, prepares their next batch of listings, and checks in afterward. Observe whether they ask for the service again or would pay for it.", "avoid": "Avoid treating the concierge test as free help with no clear question about whether sellers value the outcome.", "synthetic": true}}, "2c9e3fc167b7dbd8": {"question": "Are customers already looking for a solution?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If customers are already searching for help, the need is active. If nobody is looking, you may have to create demand before you can sell anything.", "example": "Ask a seller what they tried the last time listing preparation fell behind. Did they search for templates, hire a freelancer, or post in a seller forum? Record each attempt they describe, with roughly when it happened.", "avoid": "Avoid counting general complaints as searching. A seller who grumbles but never looked for help is a weaker signal.", "synthetic": true}}, "3903fb3ca8abfaed": {"question": "Are customers willing to pay for this product or service?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A problem people will not pay to solve may still be real, but it cannot support a business. Payment is the test that separates interest from value.", "example": "Offer a small paid service: you prepare the next 20 listings for one seller at a stated price. Record who agrees, who asks for a discount, and who declines. Example only: set the price before you start offering it.", "avoid": "Avoid asking whether they would pay someday. Hypothetical answers are cheap; look for an actual payment or a firm booking.", "synthetic": true}}, "c7bf03e35feb0083": {"question": "Are customers willing to act to solve it?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Action shows the problem ranks high enough among everything else the customer handles. Without action, even a painful problem may stay unsolved indefinitely.", "example": "Ask the seller to send you last week's spreadsheet of product data so you can try preparing listings from it. Whether they take the time to find and send it tells you more than their verbal agreement.", "avoid": "Avoid treating enthusiasm in a meeting as action. Count only steps the customer completes after the conversation ends.", "synthetic": true}}, "948d5d5ef3ceb9dd": {"question": "Is the customer willing to spend time, money, or other resources to solve it?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Money is only one kind of commitment. Time, data access, and staff effort also show how much the customer is prepared to give up for a fix.", "example": "List what a seller already spends: hours each week fixing missing fields, a part-time assistant, a paid spreadsheet add-on. Ask them to walk you through one recent week. Record the resources they actually used, not what they estimate.", "avoid": "Avoid looking only at cash. A seller who invests hours of staff time each week is also showing willingness to spend.", "synthetic": true}}, "967beeef1817665a": {"question": "Which group has already taken action?", "sourceSection": "Customer Validation \u0026 Growth: customers, situations, and assumptions", "sourceRange": "Source: Weeks 4–5, pages 6, 9, 11–12, 20–22, 37–38, 43–44, 49.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Groups that already act on the problem are your earliest likely customers. Starting with them shortens the path to learning whether your solution helps.", "example": "Compare sellers who list a few products a year with those who launch new batches every month. Note which group has already built workarounds, such as shared templates or hired help. That group is a stronger place to begin.", "avoid": "Avoid choosing the largest group by default. A big segment that has done nothing yet may be the slowest to respond.", "synthetic": true}}, "b183c7441248c029": {"question": "What is the customer willing to commit?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "After an interview, the commitment a customer offers is the clearest record of how strong the signal was. Polite agreement without commitment should be scored low.", "example": "After each conversation, write down the concrete next step the seller agreed to: a follow-up date, sharing sample product data, or a deposit for a pilot. If nothing was agreed, record that plainly instead of upgrading it to interest.", "avoid": "Avoid listing compliments as commitments. Phrases like sounds useful or keep me posted do not commit the customer to anything.", "synthetic": true}}, "97849cabe4bd3a54": {"question": "Are target customers asking to learn more?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When customers ask for more detail without being pushed, curiosity is coming from their side. That pull is an early sign the problem matters to them.", "example": "Track whether sellers who saw your short description reply with questions about how it works, what files you need, or how long it takes. Record each question and who asked it, rather than counting page views.", "avoid": "Avoid counting your own follow-up messages as their requests. Only questions the customer starts should count here.", "synthetic": true}}, "016e8ad9c4f6e163": {"question": "Are customers asking about launch dates or pricing?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Questions about timing and price mean the customer is picturing actually buying. They are planning around your offer, not just reacting to an idea.", "example": "Keep a simple log of every time a seller asks when the service starts or what it costs. Note whether the question came before or after you mentioned pricing. Unprompted questions carry more weight.", "avoid": "Avoid answering with a vague later. Give a concrete date or price so you can see how the customer responds.", "synthetic": true}}, "2151f948ed9f84b2": {"question": "Are customers inviting managers or decision-makers to participate?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Bringing in a manager or the budget holder costs the customer some reputation. It suggests they think the solution is worth an internal conversation.", "example": "If the store assistant you spoke with asks the owner to join the next call, record it. Note who joined, what the owner asked, and whether a decision step was agreed. Example only: decide in advance whether this counts as a pass.", "avoid": "Avoid assuming the person you talk to can buy. If they never involve the decision-maker, the deal may stall.", "synthetic": true}}, "a203c80a1202eb94": {"question": "Are customers accepting a paid trial?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A paid trial asks the customer to take a small risk before seeing full results. Acceptance shows stronger belief than agreeing to a free test.", "example": "Offer a two-week pilot where you prepare one product category for a modest fee. Record how many suitable sellers you offered it to and how many paid. Example only: decide the fee and the offer list before you start.", "avoid": "Avoid defaulting to free pilots to make signups easier. Free trials hide whether the customer values the outcome enough to pay.", "synthetic": true}}, "e7d49f57079095d6": {"question": "Are users willing to tolerate an incomplete early product?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Early adopters accept rough edges when the problem is painful enough. If users reject anything unfinished, the need may be weaker than you assumed.", "example": "Deliver listings through a shared spreadsheet and email instead of a polished app. Watch whether sellers keep using it despite the manual steps, and note which gaps they complain about versus which ones stop them entirely.", "avoid": "Avoid polishing the product before testing. Tolerance of an incomplete version is part of what you are trying to learn.", "synthetic": true}}, "da191aaaca326320": {"question": "Are customers willing to sign a letter of intent or an order?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A signed letter of intent or order turns a spoken interest into a written commitment. It is much harder to give casually than a yes in conversation.", "example": "Prepare a one-page letter describing the pilot scope, start date, and price. Ask sellers who said they are interested to sign it. Record who signs, who asks to change terms, and who goes quiet.", "avoid": "Avoid presenting the letter as a formality. If signing feels meaningless to the customer, the signal is meaningless too.", "synthetic": true}}, "e1d872801b308649": {"question": "What action do we want customers to take?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A concrete action is stronger than a polite compliment.", "example": "Ask a suitable seller to schedule a pilot or introduce the person who approves payment. Record what they actually do.", "avoid": "Avoid treating a compliment as a commitment.", "synthetic": true}}, "ca0cd943146853e8": {"question": "Would you be willing to pay to solve it?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Asked directly, this question surfaces how the customer thinks about paying. Their answer, and how they hesitate, reveals whether budget for this problem exists.", "example": "After the seller describes a recent listing delay, ask what they have paid before to handle similar work. Then ask whether they would pay to avoid it next month. Listen for references to past spending, not just a quick yes.", "avoid": "Avoid accepting a quick yes as proof. Follow up with what they have paid before and who approves spending.", "synthetic": true}}, "bd8f0722c2fa170f": {"question": "How will we judge the result?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Deciding how to judge a result before seeing it stops the team from reading any outcome as good news. It keeps evidence and decision connected.", "example": "Before running interviews, write down which answers would count as strong, weak, or contradicting evidence about listing preparation pain. Share the list with the team, then score each interview against it afterward.", "avoid": "Avoid judging results by how the team feels after a test. Agree on the yardstick first.", "synthetic": true}}, "fb1f03629aa72bd8": {"question": "What does success look like?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A shared picture of success gives every test and feature a target. Without it, the team may optimize for activity rather than outcomes.", "example": "Describe success in customer terms: a seller publishes a batch of new products without fixing missing fields by hand. Then decide how you would observe it, for example by reviewing their published listings together.", "avoid": "Avoid defining success as shipping features or holding meetings. Those are inputs, not results for the customer.", "synthetic": true}}, "5b742930361023e2": {"question": "What numbers would make us continue?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Decide the interpretation before seeing the result.", "example": "Example only: before a test, choose how many suitable sellers would need to book a paid pilot, and by what date. Set a threshold appropriate to your business.", "avoid": "Avoid choosing the success threshold after seeing the result.", "synthetic": true}}, "d8ac28b0359f716b": {"question": "What numbers would make us pivot?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Setting a pivot threshold in advance makes it easier to change direction when evidence is weak. Without one, teams tend to keep going out of habit.", "example": "Example only: before offering paid pilots, choose the minimum number of suitable sellers who must pay within a set period. Write down that falling below it means revisiting the customer group or the problem, not just trying harder.", "avoid": "Avoid moving the threshold after seeing results. A number changed after the fact no longer guides the decision.", "synthetic": true}}, "93af7c379b7b412a": {"question": "Does our proposed solution create value?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A solution only matters if it leaves the customer better off than their current workaround. This question checks that improvement before you invest more.", "example": "Prepare one batch of listings for a seller and compare it with their usual process. Record how much fixing they still had to do and whether they would choose your version again next time.", "avoid": "Avoid measuring value by how impressive the solution looks. Value is the difference it makes to the customer's work.", "synthetic": true}}, "9194e42d4b4a1a11": {"question": "Why do customers need this product?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing why the customer needs the product keeps the team anchored to a real situation. It prevents features from drifting away from the original problem.", "example": "Tie the need to a specific moment: a seller has a new supplier shipment arriving and must list it before a seasonal sale. Ask sellers to describe the last time this happened and what made it hard.", "avoid": "Avoid answering with what the product does. The need comes from the customer's situation, not from your feature list.", "synthetic": true}}, "77566383c5ca9916": {"question": "What value do we provide?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The value you provide is what the customer exchanges money for. Naming it clearly shapes pricing, messaging, and what to build first.", "example": "State it as an outcome the seller recognizes, such as complete listings ready to publish on the day stock arrives. Then check whether sellers describe the benefit in similar words when you explain it to them.", "avoid": "Avoid listing technologies or features as value. Customers pay for outcomes they can see in their own business.", "synthetic": true}}, "0acea3cbed515fa1": {"question": "What is the smallest solution we can test?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A small complete outcome can teach more than many unfinished features.", "example": "Prepare one seller’s next batch manually before building an automated system. Explain clearly what the pilot includes.", "avoid": "Avoid building automation before testing the outcome.", "synthetic": true}}, "dfde358b0bec117d": {"question": "Do we need a complete product to test it?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Many assumptions can be tested long before a full product exists. Building everything first delays learning and raises the cost of being wrong.", "example": "Instead of building an upload tool, ask a seller to email product photos and a spreadsheet. Prepare the listings manually and send them back. This tests whether they want the result before you automate anything.", "avoid": "Avoid assuming customers will only respond to a finished product. Early users often care about the outcome, not the interface.", "synthetic": true}}, "5cde4a97e57e03ba": {"question": "Which feature would best reveal whether customers need the solution?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "One well-chosen feature can test the core need faster than a broad set. Picking it forces the team to name what it most needs to learn.", "example": "Compare candidate features: auto-filling missing specs, resizing photos, writing titles. Ask which one, if sellers used it repeatedly, would most clearly show they need help with listing data. Build only that one first.", "avoid": "Avoid picking the feature that is easiest or most fun to build. Choose the one that answers your riskiest question.", "synthetic": true}}, "3484291a2eef9be2": {"question": "Which validated problem does this feature solve?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Every feature should trace back to a problem customers have confirmed in interviews. Features without that link often go unused.", "example": "Before adding photo background removal, check your interview notes. Did several sellers describe photo editing as a recurring delay, or did only one mention it in passing? Record which notes support the feature.", "avoid": "Avoid justifying a feature with a single anecdote or the team's own preference. Link it to repeated customer evidence.", "synthetic": true}}, "352b88f2094daba1": {"question": "What do they need to do?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Understanding the task customers must complete keeps the product focused on their job, not on screens or functions the team imagines.", "example": "Map the seller's job step by step: gather supplier details, write a title, check required fields, upload photos, publish. Watch one seller do it once and note which steps take the longest or cause rework.", "avoid": "Avoid describing what users do inside your product. Start from the work they must finish regardless of any tool.", "synthetic": true}}, "d3e198b82d5812db": {"question": "Which small part of the problem will we solve this time?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Choosing a small slice of the problem makes the next test achievable and its result readable. Trying to solve everything at once blurs what you learn.", "example": "Of all listing problems, pick one, such as filling missing product specifications from supplier sheets. Leave photos and titles for later. Tell pilot sellers clearly what this round covers and what it does not.", "avoid": "Avoid a slice so broad that a failure cannot be traced to one cause.", "synthetic": true}}, "008e10f76f3ac88a": {"question": "What is the least we need to deliver for a customer to make the first payment?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The first payment marks the point where your offer is worth money to someone. Finding the minimum keeps scope small and learning fast.", "example": "Ask what a seller would need to receive to pay for one batch: perhaps 30 complete listings in their store's format by a set date. Deliver that manually and see whether they pay.", "avoid": "Avoid adding dashboards, accounts, or integrations before anyone has paid. These rarely decide the first purchase.", "synthetic": true}}, "806cf1c5ff1400d5": {"question": "If this were solved tomorrow, what concrete difference would it make?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Ask the customer directly", "audienceEn": "Ask the customer directly", "help": {"why": "Hearing the customer describe a concrete difference shows whether solving the problem matters in their daily work. Vague answers suggest a mild problem.", "example": "Ask the seller to imagine listings were ready the moment stock arrived. Listen for specific changes: launching before a weekend sale, freeing an assistant for customer service. Ask which recent week this would have changed.", "avoid": "Avoid accepting general answers like it would be easier. Ask for a specific task, day, or result that would change.", "synthetic": true}}, "bbefb90e6c686c57": {"question": "How does our solution address that problem?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Investors and customers need to see a clear link between the problem stated and the solution offered. A gap there weakens the whole pitch.", "example": "Connect each part: sellers lose launch days to missing product fields, so the service collects supplier data and returns complete listings ready to upload. Check that every claim in the link is backed by interview evidence.", "avoid": "Avoid describing the solution without naming which part of the problem it removes. The connection should be explicit.", "synthetic": true}}, "cf4f653cfdf4ccce": {"question": "What product are we offering?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Naming the product plainly lets others understand what they would buy or use. A fuzzy description makes feedback and decisions harder.", "example": "Write one sentence a seller could repeat: a service that turns supplier spreadsheets and photos into store-ready product listings within two days. Test it by asking a seller to explain it back in their own words.", "avoid": "Avoid describing the product as a platform or ecosystem. Say what the customer receives and in what form.", "synthetic": true}}, "46af06a775a529df": {"question": "What makes our value proposition different from existing solutions?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Customers compare you with what they use now, including spreadsheets and freelancers. Your difference must matter to them, not just sound new.", "example": "List current alternatives: doing it in-house, hiring a freelancer, generic templates. Ask sellers what bothers them about each. A possible difference is consistent output in the store's required format, but confirm it with them.", "avoid": "Avoid claiming no competition exists. Doing nothing and manual work are alternatives customers already accept.", "synthetic": true}}, "4ff6844ca0f2db22": {"question": "What is the simplest technology that lets us test the assumption?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Technology choices should serve the test, not the other way round. The simplest setup gets an answer sooner and costs less to throw away.", "example": "To test whether sellers want complete listings, use a shared spreadsheet, a form for photos, and manual review. Only consider custom software once sellers keep sending batches through this setup.", "avoid": "Avoid choosing a technology because the team wants to learn it. Pick what answers the assumption fastest.", "synthetic": true}}, "81c0addf8c25b513": {"question": "Can a rule-based system test the need before we invest in AI?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Simple rules can often show whether customers want the outcome. If they do not, an AI investment would only make an unwanted product more expensive.", "example": "Write fixed rules that flag missing fields such as size, material, and weight in a seller's spreadsheet. If sellers find those flags useful and come back, then evaluate whether AI would improve the results.", "avoid": "Avoid starting with AI because it sounds impressive. First check that the underlying need exists with simpler logic.", "synthetic": true}}, "59ef788d3d0b7595": {"question": "Can a hard-coded workflow test demand before we build full infrastructure?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A hard-coded workflow can deliver the result to a few customers quickly. It tests demand before you spend weeks on systems that may not be needed.", "example": "Build a script that converts one seller's supplier sheet into their store's import format, with their categories written directly in the code. If several sellers keep using it, generalize afterward.", "avoid": "Avoid building multi-tenant accounts, permissions, and scaling before demand appears.", "synthetic": true}}, "368c8f4ef43eeccc": {"question": "What basic design choices must remain consistent across the product?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Even an early product needs a few consistent basics so users are not confused. Agreeing on them early avoids rework as the product grows.", "example": "Agree on a few rules: the same field names everywhere, one date format, the same wording for missing information. Write them in a short shared note and check each new screen or file against it.", "avoid": "Avoid spending weeks on a full design system. Fix only the choices that would confuse users if they changed.", "synthetic": true}}, "6c876f959825be3e": {"question": "Are we postponing tests, documentation, or instrumentation?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Speed matters early, but postponing everything creates hidden debt. Without basic instrumentation, you cannot see whether customers use what you built.", "example": "List what the team is skipping: automated tests, setup notes, usage tracking. Decide which to keep minimal now, such as logging every batch a seller submits, and when to revisit the rest.", "avoid": "Avoid postponing instrumentation entirely. Without it, later questions about usage and retention cannot be answered.", "synthetic": true}}, "a8afdf0ac12c9b4f": {"question": "Where can I find these customers today?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing where customers already gather tells you whether you can reach them at all. A great idea is hard to test if you cannot find anyone.", "example": "List concrete places: seller groups on social platforms, marketplace forums, local merchant meetups, suppliers who serve small shops. Visit two this week and note how many suitable sellers you could actually contact.", "avoid": "Avoid answering with online or social media in general. Name specific communities, events, or people you can approach.", "synthetic": true}}, "7ea4e064b15a2a56": {"question": "Which customer group can we reach most easily?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Early learning depends on talking to customers quickly. The easiest group to reach lets you run more conversations and tests in less time.", "example": "Compare segments: sellers in a forum a team member already belongs to, sellers met through a supplier contact, and sellers found by cold outreach. Record how many conversations each route produces in one week.", "avoid": "Avoid picking an easy group that does not have the problem. Reachability only helps if they fit the customer profile.", "synthetic": true}}, "cbb9ff30e57367e4": {"question": "Can we reach them soon?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Timing affects momentum. If reaching customers takes months, the team may lose time and energy before learning anything.", "example": "Set a short window, such as the next ten days, and plan who you can contact within it. Example only: decide how many seller conversations you aim to book, then compare the plan with what actually happened.", "avoid": "Avoid planning outreach for later. Reaching customers soon is part of testing whether the plan is realistic.", "synthetic": true}}, "aa037480add09669": {"question": "Which customer group has the highest response rate?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Response rate shows which group finds the problem relevant enough to reply. It can guide where to focus limited time.", "example": "Send the same short message to two seller groups, for example clothing sellers and home goods sellers. Record how many in each group were contacted and how many replied, then compare.", "avoid": "Avoid comparing groups contacted with different messages. Change one thing at a time to see what drives replies.", "synthetic": true}}, "c3682203cbc51b08": {"question": "Which acquisition channel has the lowest cost?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Acquisition cost determines whether growth can pay for itself. Knowing it early prevents scaling a channel that loses money on each customer.", "example": "Track time and money spent per channel: forum posts, supplier referrals, small paid ads. Record how many suitable sellers each channel produced. Divide cost by that number to compare channels.", "avoid": "Avoid counting only money. Founder hours spent on a channel are also a cost.", "synthetic": true}}, "85ddfe10e09164cc": {"question": "Which invitation message gets the highest response rate?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The invitation is often a customer's first contact with you. Small wording changes can affect who replies, which shapes everything you learn afterward.", "example": "Write two versions: one naming the problem, such as fixing missing product details before launch, and one offering a short chat about listing work. Send each to similar sellers and record replies per version.", "avoid": "Avoid judging wording on too few messages. Wait until each version has reached enough people to compare.", "synthetic": true}}, "ee914defe2121043": {"question": "Are interviewees introducing other potential customers?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When interviewees introduce peers, they are vouching for the problem's relevance. Referrals also make recruiting cheaper and faster.", "example": "At the end of each interview, ask whether they know another seller who struggles with listing preparation. Record how many offer a name, and how many introductions actually turn into conversations.", "avoid": "Avoid counting vague offers to mention it to someone. Count only introductions that lead to contact.", "synthetic": true}}, "41c5e60512f9bba1": {"question": "What are our interview invitation response and completion rates?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Response and completion rates show where recruiting breaks down. A high reply rate with low completion points to a different fix than few replies.", "example": "Track three numbers per week: invitations sent to sellers, replies received, and interviews completed. If many reply but few attend, shorten the request or offer more flexible times so attendance is easier for busy sellers.", "avoid": "Avoid tracking only completed interviews. Without the earlier counts, you cannot tell which step needs work.", "synthetic": true}}, "8ffeafb5f13c5b7a": {"question": "What is our customer referral rate?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Referral rate shows whether customers value the product enough to recommend it. It can also become a low-cost acquisition channel.", "example": "Record each new seller who arrived because an existing pilot seller recommended you. Divide by the number of active pilot sellers in the same period, and note the date of every referral.", "avoid": "Avoid relying on how much customers say they like the product. Measure the referrals that actually happen.", "synthetic": true}}, "ab5db194c4df06ea": {"question": "What proportion of users complete the core task and return?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Finishing the core task once and coming back shows the first experience delivered enough value. Signups alone do not show this.", "example": "Define the core task, such as a seller uploading a supplier sheet and publishing the returned listings. Record how many new sellers do this, and how many return with another batch within a set period.", "avoid": "Avoid measuring activation by logins or account creation. These happen before the customer receives any value.", "synthetic": true}}, "ab04d74c83667b21": {"question": "What are the most important one or two user journeys?", "sourceSection": "Product Strategy: problem, outcomes, validation, and product scope", "sourceRange": "Source: Week 7, pages 8, 11–16, 19–20, 26, 28, 31, 46, 52–53. Direct customer questions are on page 31. The last question is explicitly placed after understanding the problem; stated willingness to pay is not actual payment.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Focusing on one or two journeys keeps a small team from spreading effort thin. These paths are where the product must work well.", "example": "Pick the journey that matters most: a seller sends supplier data and receives complete listings. A second might be correcting a returned listing. Write each as steps and test them end to end.", "avoid": "Avoid listing every feature as a journey. If everything is important, nothing gets enough attention.", "synthetic": true}}, "c91c992c4c2bc4fc": {"question": "When does the user first genuinely experience the product’s value?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Signup is not the same as receiving value.", "example": "A seller publishes a prepared listing without correcting missing information. Validate whether this is the meaningful moment for them.", "avoid": "Avoid treating account creation as proof of customer value.", "synthetic": true}}, "ae0d82b1ca4d8a64": {"question": "Which steps between signup and the first experience of value can we shorten?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Each step before value is a chance for the user to give up. Removing unnecessary steps helps more people reach the moment that matters.", "example": "Write out every step from signup to the first ready listing: account creation, store connection, uploading files, choosing templates. Ask which steps could be skipped or done later, such as connecting the store after the first batch.", "avoid": "Avoid adding onboarding screens to explain a long process. Shorten the process itself where possible.", "synthetic": true}}, "fdbca3373e454a91": {"question": "Are users returning without reminders?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Returning voluntarily may reveal recurring value.", "example": "Observe whether the seller brings a second batch without a follow-up message. Record the event; do not infer it from satisfaction alone.", "avoid": "Avoid counting a prompted return as an unprompted one.", "synthetic": true}}, "0dbd6d3dc2437f11": {"question": "Are users returning after their first trial?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A return visit after the first trial suggests the value was real enough to repeat. One-time use may mean curiosity, not need.", "example": "After each seller's first pilot batch, note whether they submit another one without being reminded. Record the date of the second batch, or that none arrived, for each seller in the pilot group.", "avoid": "Avoid counting returns you prompted with reminders. Those show your follow-up effort, not the customer's need.", "synthetic": true}}, "326bd370e163acd0": {"question": "What do our usage patterns show?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Usage patterns reveal how customers fit the product into their work. Timing and frequency can confirm or challenge your assumptions about the problem.", "example": "Review when sellers submit batches: only before seasonal sales, or steadily each week? Plot submission dates per seller. A seasonal pattern may change how you price the service and plan support capacity.", "avoid": "Avoid looking only at totals. Averages can hide that a few heavy users carry most of the activity.", "synthetic": true}}, "dc7574ea38b33f7b": {"question": "If users are leaving, what should we reconsider about the problem, requirements, or value proposition?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When users leave, the cause may lie upstream in the problem itself, not in a missing feature. Looking back helps avoid fixing the wrong thing.", "example": "If sellers stop after one batch, ask what changed. Perhaps listing is rare for them, or missing data comes from suppliers you cannot reach. Revisit your interview notes and decide which assumption to retest.", "avoid": "Avoid responding to churn by adding features right away. First check whether the original problem was frequent and painful.", "synthetic": true}}, "51a68ddfbb7d30d9": {"question": "What is our retention rate?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Retention rate summarizes whether customers keep getting value over time. It is one of the clearest signals that the product solves a recurring problem.", "example": "Group sellers by the month they started. Record what share submitted at least one batch in each following month. Example only: decide in advance which period you will treat as the retention window.", "avoid": "Avoid calculating retention without a fixed time window. Without one, the number cannot be compared across groups.", "synthetic": true}}, "a675c3d0a3b643e0": {"question": "What are our trial and paid conversion rates?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Trial and paid conversion show where interest turns into commitment. They help you see whether the offer or the trial experience needs work.", "example": "Record how many sellers start a trial, how many complete it, and how many then pay for a batch. Track these as separate counts so you can see which step loses the most people.", "avoid": "Avoid combining trial and paid conversion into one figure. Each points to a different problem to fix.", "synthetic": true}}, "e8a48bec8f9e840d": {"question": "Where do users click?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Click data shows where users focus and where they get confused. It can reveal problems that users never mention in interviews.", "example": "Log clicks on the main screens of the listing tool, such as upload, preview, and edit field. Review whether sellers repeatedly click something that is not interactive, or skip the preview entirely.", "avoid": "Avoid tracking every click without a question in mind. Decide what you want to learn before adding tracking.", "synthetic": true}}, "e2c1bc7c8c4c3224": {"question": "Which features do they use?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing which features are used shows where customers find value. It helps you decide what to improve and what to stop maintaining.", "example": "Record each time a seller uses a feature: bulk upload, missing-field flags, title suggestions. After a few weeks, list which features each seller used at least once, and which ones only appeared in demos.", "avoid": "Avoid relying on what users say they use. Actual usage often differs from their own description.", "synthetic": true}}, "d87da2c7c56d7763": {"question": "At which step do they leave?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The step where users drop out shows where your process fails them. It tells you where to look first when fixing the flow.", "example": "Log each step of the main journey: upload started, file accepted, listings previewed, listings exported. Count how many sellers reach each step and find the biggest drop between two of them.", "avoid": "Avoid guessing the drop-off point from complaints. Measure each step so the data points to the real gap.", "synthetic": true}}, "be3dfed046130fa0": {"question": "Which features are heavily adopted?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Heavily adopted features often point to the core value. They show what to protect and strengthen as the product changes.", "example": "Rank features by how many active sellers use them each week. If most use missing-field flags but few use title suggestions, consider making the flags the center of the product.", "avoid": "Avoid confusing heavy adoption with a single power user. Check how many different customers use the feature.", "synthetic": true}}, "f4338f46ae7d3102": {"question": "Which features does nobody use?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Unused features cost maintenance and clutter the product. Finding them helps you remove distractions and question the assumptions behind them.", "example": "After a set period, list features with no use by any active seller, such as a template library nobody opened. Ask a few sellers whether they knew it existed before deciding to remove it.", "avoid": "Avoid keeping unused features because effort went into building them. Past effort is not a reason to keep them.", "synthetic": true}}, "b04051277b59b241": {"question": "What is our conversion rate?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Conversion rate shows how well each stage moves people toward value or payment. It makes the funnel measurable instead of anecdotal.", "example": "Define the stages first, such as visited the page, requested a sample, received listings, paid. Record the counts at each stage for the same group of sellers over the same period.", "avoid": "Avoid quoting a conversion rate without saying which two stages it connects. The number means nothing without its definition.", "synthetic": true}}, "5875a39fd8e4aee5": {"question": "What is our error rate?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Errors break trust quickly, especially for sellers publishing to a live store. Tracking them shows whether quality issues are driving users away.", "example": "Log every failed upload, rejected export, and listing a seller had to correct by hand. Record the number of errors per batch, and review the most common causes each week.", "avoid": "Avoid counting only system crashes. Wrong or incomplete listing data is also an error from the seller's view.", "synthetic": true}}, "122e852db49700ab": {"question": "How will we earn revenue and grow?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Revenue and growth are linked. A way of earning money that cannot expand with more customers limits how far the business can go.", "example": "Suppose sellers pay per prepared listing. Write down how revenue would rise: more listings from the same seller, more sellers, or both. Then note which of those paths you have actually seen a seller take so far.", "avoid": "Avoid answering with a revenue target alone, without describing the customer behavior that would produce it.", "synthetic": true}}, "28b59453ed4b3f79": {"question": "Is our revenue repeatable?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "One-time payments force you to find new buyers every month. Repeatable revenue shows whether customers come back to pay again for the same value.", "example": "Record how many pilot sellers pay for a second batch of listings without being chased. Example only: decide in advance how many repeat purchases within two months would count as a repeatable pattern for you.", "avoid": "Avoid counting a seller's promise to keep using the service as repeat revenue before a second payment happens.", "synthetic": true}}, "61a4d50ec12c5df4": {"question": "How do we capture the value?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Creating value for customers does not guarantee you receive part of it. Capture depends on who pays, when, and for which outcome.", "example": "A seller saves preparation time on each launch. Decide whether you charge when listings are delivered, monthly for access, or per product published. Ask a pilot seller which moment feels like the right point to pay.", "avoid": "Avoid assuming customers will pay simply because the product saves them effort; check where payment naturally fits.", "synthetic": true}}, "0227c91eea69ebe8": {"question": "Does our free version provide value on its own?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A free tier only attracts and keeps users if it solves something real. An empty free version teaches nothing and converts nobody.", "example": "Imagine a free checker that flags missing fields in a seller's product spreadsheet. Watch whether sellers use it for a real launch and fix the flagged fields, even if they never upgrade.", "avoid": "Avoid offering a free version that is only a locked demo with no outcome a seller can use.", "synthetic": true}}, "072f808d128e2d8b": {"question": "What gives free users a clear reason to upgrade?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Free users stay free unless the paid version solves a problem the free one leaves open. The upgrade trigger must be concrete.", "example": "A free checker finds missing fields, but the paid plan fills them in and formats titles. Record the moment sellers ask for the fix rather than the warning; that request marks a possible upgrade point.", "avoid": "Avoid relying on usage limits alone when free users never reach them or do not feel the limit.", "synthetic": true}}, "db194ed5c25b5a39": {"question": "Do we have enough traffic to support an advertising model?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Advertising pays only at large audience scale. A small, focused tool may never reach the traffic needed for ads to cover costs.", "example": "Estimate how many seller visits per month your listing tool currently gets, then compare that to what an advertiser would need. If the gap is very large, consider direct payment from sellers instead.", "avoid": "Avoid choosing ads as a default model because charging users feels uncomfortable.", "synthetic": true}}, "5917f029dc565fe9": {"question": "Does the product provide ongoing value that justifies a subscription?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A subscription asks customers to pay every month. That only feels fair if they receive value every month, not once.", "example": "Check whether sellers launch new products often enough to need help monthly. Ask a seller to show their launch dates over the past few months and see whether the need repeats on a regular rhythm.", "avoid": "Avoid adopting a subscription because recurring revenue looks attractive, when the customer's need is occasional.", "synthetic": true}}, "bba70bf3e15fda21": {"question": "Does the value occur only once?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If customers need you only once, a subscription will churn quickly and a one-time or per-project price may fit better.", "example": "A seller might need a full catalog cleanup once, then only small updates afterward. Track whether pilot sellers return after the first cleanup, and price the first job differently from the follow-up work if needed.", "avoid": "Avoid treating a large first project as proof of ongoing demand from the same seller.", "synthetic": true}}, "7df6b058ce456c5e": {"question": "What pricing unit makes sense in the customer’s business?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Pricing is easier to understand when it matches the work customers recognize.", "example": "Compare paying per listing with paying for model tokens. Test which unit the seller can connect to a useful outcome.", "avoid": "Avoid charging in technical units customers cannot relate to value.", "synthetic": true}}, "c1148c680f66f444": {"question": "What is our business model?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Investors and teammates need a short statement of who pays, for what, and how the money arrives. Without it, plans drift.", "example": "One possible statement: small sellers pay a fee per batch of prepared listings, delivered before each launch. Write your version in one sentence, then mark which parts are tested and which are still assumptions.", "avoid": "Avoid listing several possible models at once without choosing the one you are testing now.", "synthetic": true}}, "8e7fdb7d5e438783": {"question": "What are our revenue sources and charging methods?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Naming each revenue source and how it is charged reveals whether pricing matches the customer's work and how cash actually arrives.", "example": "List each source separately, such as per-listing fees, a setup fee for catalog cleanup, or a monthly plan. For each one, note who pays, the pricing unit, and whether any seller has paid that way yet.", "avoid": "Avoid mixing planned revenue sources with ones customers have actually paid for in the same list.", "synthetic": true}}, "d19766be37a192e7": {"question": "Are our gross margins high enough?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Gross margin shows what is left after the direct cost of serving each customer. Thin margins leave little room to grow.", "example": "For one batch of listings, record the hours your team spends on manual fixes plus any tool or model costs. Compare that total with the price charged and see how much remains for the business.", "avoid": "Avoid ignoring manual work hidden behind the product when calculating the cost of delivering each batch.", "synthetic": true}}, "ac72aaaef685e68a": {"question": "Do our unit economics work?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Unit economics test whether a single customer is profitable. If one does not work, adding more customers only multiplies losses.", "example": "Pick one pilot seller. Add up what it cost to find them, the cost of serving their listings, and what they paid. Example only: decide what profit per seller you would need before scaling outreach.", "avoid": "Avoid hoping scale will fix negative unit economics without knowing which cost will actually fall.", "synthetic": true}}, "4880f53aa4747347": {"question": "What does it cost to acquire a customer?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing acquisition cost tells you how much you can afford to spend on finding customers before each new customer becomes a loss.", "example": "Track the hours and money spent on outreach to sellers, such as messages, community posts, and calls, then divide by the number who became paying customers. Record the channel used for each customer.", "avoid": "Avoid leaving founder time out of acquisition cost because no money was spent directly.", "synthetic": true}}, "bc0cd6242bc68eff": {"question": "What is the lifetime value of a customer?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Lifetime value estimates how much a customer brings in before leaving. It sets the ceiling on what acquisition can sensibly cost.", "example": "With early sellers, you cannot observe a full lifetime yet. Record how many batches each seller has bought and how long they have stayed, then state any lifetime estimate clearly as an assumption to revisit.", "avoid": "Avoid projecting a multi-year lifetime from a few months of data and presenting it as known.", "synthetic": true}}, "669e0e59441e21a9": {"question": "How long does it take to recover our customer acquisition cost?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The payback period shows how long your cash is tied up in each new customer. Long payback strains a small team's runway.", "example": "Suppose finding one seller cost a certain amount of outreach time and money. Record how many months of that seller's payments it takes to cover that cost, and compare it with how long your cash can last.", "avoid": "Avoid calculating payback with revenue instead of margin, which makes recovery look faster than it is.", "synthetic": true}}, "413baf3ecebd56da": {"question": "What are our gross margin and customer retention rate?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Margin and retention together show whether each customer earns money and stays long enough for that money to add up.", "example": "For each pilot seller, record the margin on every batch and whether they returned the next month. Put the two side by side; a high margin with sellers who leave quickly tells a different story than steady returns.", "avoid": "Avoid reporting one of the two numbers alone when the other one is weak.", "synthetic": true}}, "7812f3281d483297": {"question": "How much does it cost to acquire one user?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Within product strategy, the cost of one user shows which acquisition channel deserves more effort and which should stop.", "example": "Compare channels for reaching sellers, such as seller forums, marketplace groups, and referrals from existing pilots. For each, record the time and money spent and how many sellers signed up and completed a first listing.", "avoid": "Avoid averaging all channels into one number, which hides the channel that is actually working.", "synthetic": true}}, "780d1d9793deca51": {"question": "Is customer acquisition cost lower than customer value?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If acquiring a customer costs more than that customer brings in, every new signup makes the business weaker.", "example": "Place two figures next to each other for your seller pilots: what it cost to bring each seller in, and the margin they have produced so far. Mark which sellers have already covered their own acquisition cost.", "avoid": "Avoid comparing acquisition cost with an optimistic future value instead of the value customers have produced.", "synthetic": true}}, "f142e7b12a64c8a6": {"question": "What are our revenue, costs, and unit economics?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Seeing revenue, costs, and per-customer economics on one page reveals whether the current activity can support the team at all.", "example": "Build a simple monthly table: revenue from listing batches, direct delivery costs, outreach costs, and fixed costs such as tools. Add a row for profit per seller. Keep tested figures and assumptions in separate columns.", "avoid": "Avoid presenting a polished spreadsheet where assumptions and recorded figures cannot be told apart.", "synthetic": true}}, "6e3dd5b451718ded": {"question": "What are our average revenue per user and monthly recurring revenue growth?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Average revenue per user and recurring revenue growth show whether sellers spend more over time and whether the base keeps expanding.", "example": "Each month, record total recurring revenue from sellers and divide it by active sellers. Note whether growth comes from new sellers joining or existing sellers sending larger batches, since each points to a different next step.", "avoid": "Avoid counting one-time cleanup fees as monthly recurring revenue, which inflates the growth line.", "synthetic": true}}, "6158fab3be1b22c1": {"question": "What are our financial projections?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Projections show how you think the business will grow and what must be true for that to happen. The assumptions matter most.", "example": "Project seller count, price per batch, batches per month, and costs for the next year. Example only: choose a conservative and an optimistic case. Beside each line, write the assumption behind it and what would test it.", "avoid": "Avoid a single steep curve with no stated assumptions behind each number.", "synthetic": true}}, "95aa48534b4b2163": {"question": "Does growth depend on adding more people?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "If each new customer needs more staff, costs rise with revenue and the business struggles to scale beyond the team's capacity.", "example": "Today the team fixes listings by hand. Record how many hours one seller's batch takes. If doubling sellers would need roughly double the hours, growth still depends on people and automation is the next question.", "avoid": "Avoid assuming software will remove manual work later without measuring how much manual work exists now.", "synthetic": true}}, "372672bde8aca578": {"question": "Does growth come from replicating the product, network effects, or adding people and inventory?", "sourceSection": "From Problem to Team: business models", "sourceRange": "Source: Week 3, pages 3, 9, 13–14. Items marked as rewritten questions were expanded from original fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The source of growth determines its cost. Copying software is cheap, network effects compound, but people and inventory grow costs too.", "example": "For the listing service, mark which parts copy at almost no cost, such as a field checker, and which need a person, such as rewriting titles. Note whether sellers referring other sellers could create any network effect.", "avoid": "Avoid claiming network effects when customers do not actually benefit from each other's participation.", "synthetic": true}}, "859a8ea0916752bf": {"question": "Does this activity bring us closer to customers, validation, usage, or revenue?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Small teams easily fill weeks with busy work. This check keeps effort tied to customers, evidence, usage, or revenue.", "example": "Before redesigning the dashboard, ask which of the four it moves. Booking three more seller calls brings you closer to customers; polishing a page nobody visits may not. Write the answer next to each planned task.", "avoid": "Avoid treating tasks that feel productive, like tool setup or branding, as progress without that link.", "synthetic": true}}, "2b4ea3108c5c89ac": {"question": "Are we getting closer to a sustainable business model?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Growth means little if each month still depends on effort that cannot last. This question checks direction, not just activity.", "example": "Compare this month with last month for your seller pilots: are more sellers paying, is delivery taking fewer hours per batch, and are fewer sellers leaving? Record the change in each rather than relying on a general feeling.", "avoid": "Avoid judging progress by signups or attention while payment and delivery cost stay unchanged.", "synthetic": true}}, "f5a5f6a9a30678b6": {"question": "Can we repeat the way we acquire and serve customers?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Growth needs a process that works again, not a lucky win. Repeatability shows whether the first customers can be followed by more.", "example": "Write down how each pilot seller was found, onboarded, and served. If the next three sellers can come through the same steps with similar effort, the process may be repeatable. Note where each one differed.", "avoid": "Avoid assuming a deal won through a personal connection can be repeated with strangers.", "synthetic": true}}, "d2cc68f71976d798": {"question": "Which effective practices can the whole team reuse?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When one teammate finds something that works, the team grows faster if others can repeat it instead of rediscovering it.", "example": "One founder may have a message that gets sellers to book calls. Write the steps and the exact wording down, let another teammate use it for a week, and record whether bookings follow.", "avoid": "Avoid keeping effective practices in one person's head, where nobody else can use or check them.", "synthetic": true}}, "a0ca75f0dba03362": {"question": "Where should we invest our limited time, people, and attention?", "sourceSection": "Customer Validation \u0026 Growth: Growth", "sourceRange": "Source: Weeks 4–5, pages 14–18, 30, 32–33. Rewritten items are marked separately from original questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A small team cannot pursue every channel and feature. Choosing where effort goes is often the most important growth decision.", "example": "List current efforts, such as seller outreach, building automated title rewriting, and running social posts. For each, record time spent last week and what it produced. Keep the one or two with clearer results and pause the rest.", "avoid": "Avoid spreading effort evenly across everything to avoid the discomfort of stopping something.", "synthetic": true}}, "60c92f964306af40": {"question": "Do I have a genuine interest in this problem?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Early work on a problem is slow and often disappointing. Real interest is what keeps you reading, asking, and returning to it when nothing is working yet.", "example": "Suppose a founder of the listing-data team notices she reads seller forum threads about messy product spreadsheets in her free time. Write down two moments in the past month when you chose to spend time on this problem without anyone asking you to.", "avoid": "Avoid answering from how exciting the market sounds. Interest shows up in what you already do, not what you plan to do.", "synthetic": true}}, "ce2caae988aa6594": {"question": "Am I willing to spend a year studying this field?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Understanding a field well enough to spot a real opportunity takes time. A year of study is a test of whether you will stay long enough to learn it.", "example": "For the listing-data venture, a year might mean learning marketplace listing rules, supplier data formats, and how small sellers plan launches. List the topics you would study and estimate the hours per week you would honestly give them.", "avoid": "Avoid saying yes without picturing the dull parts, such as reading platform policy pages and comparing spreadsheet templates.", "synthetic": true}}, "9985b86116f69cdc": {"question": "Am I willing to talk to strangers to validate this problem?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Most of what you learn about a problem comes from people you do not know yet. If talking to strangers feels impossible, the problem cannot be checked.", "example": "One founder could try sending short messages to five small sellers she has never met, asking about their last product launch. Notice how it feels to send them and whether you would repeat it next week.", "avoid": "Avoid planning to rely only on friends and former colleagues, who tend to be polite rather than accurate.", "synthetic": true}}, "1d254a13db1bd36a": {"question": "Would I still care about this problem if the solution changed?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Your first solution will probably change. Caring about the problem itself, not your favorite feature, is what lets you keep going after the first idea fails.", "example": "Imagine the team learns that sellers do not want an automated listing tool, but would accept a checklist service. Ask yourself whether you would still want to help these sellers with missing product fields in that case.", "avoid": "Avoid treating attachment to a specific app, design, or technology as attachment to the problem.", "synthetic": true}}, "bc63c1c1ed444992": {"question": "What am I good at?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Your strengths shape which problems you can study well and which work you can carry yourself. Knowing them early helps you choose a fitting role.", "example": "In the listing-data team, one person may be good at cleaning spreadsheets, another at writing clear product copy, and another at calming stressed customers. Ask two people who have worked with you what they would hand you first.", "avoid": "Avoid listing only job titles or tools. Describe what you have actually done well and could do again.", "synthetic": true}}, "434e023caa94b179": {"question": "Which problem areas do I care about?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Starting from areas you already care about gives you a wider list to choose from, before you lock onto a single idea too early.", "example": "A founder might list small online retail, supplier communication, and product photography as areas she keeps noticing. Write three to five areas, then add one recent situation in each where you saw someone struggle.", "avoid": "Avoid naming only areas that sound popular or fundable when you have no personal pull toward them.", "synthetic": true}}, "6d427eb63c6c4cbf": {"question": "Am I interested in a real pain point, or just an interesting idea?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "An interesting idea can feel exciting while solving nothing anyone urgently needs. Separating the two keeps you from building something only you find clever.", "example": "An AI tool that writes poetic product titles may be an interesting idea. A seller delaying a launch because supplier specs are missing is a pain point. Note which one you could describe with a real past event.", "avoid": "Avoid judging by how much you enjoy explaining the idea. Enjoyment of the concept is not evidence of pain.", "synthetic": true}}, "363153a61f4296a3": {"question": "What am I most afraid of right now?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Fear quietly shapes decisions, such as avoiding interviews or delaying a test. Naming it lets the team plan around it instead of being steered by it.", "example": "A founder in the listing-data team might admit she fears being rejected by sellers, or losing savings, or looking foolish to former colleagues. Write the fear down and one small step that would make it easier to face this week.", "avoid": "Avoid answering that you are not afraid of anything. That usually means the fear has not been looked at yet.", "synthetic": true}}, "92f7452014ce9592": {"question": "Can I treat failure as information rather than a personal defeat?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Many early tests will not go the way you hope. Seeing failure as information keeps you learning instead of hiding results or quitting too early.", "example": "Suppose ten sellers decline a pilot. A founder who treats this as information would ask what they said, sort the reasons, and change the next test. Recall a recent setback and note what you learned from it.", "avoid": "Avoid promising to stay calm about failure without checking how you reacted to a real setback before.", "synthetic": true}}, "0439513ba4f2d75a": {"question": "In which fields can I understand problems, find customers, or access data more easily than most people?", "sourceSection": "From Problem to Team: Problem, Customer, Market, Solution", "sourceRange": "Source: Week 3, pages 17, 21, 23, 25–26, 32–34.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "An unfair head start in understanding a field, reaching its customers, or seeing its data makes early learning faster and cheaper than for outsiders.", "example": "A founder who once ran a small online shop may know seller groups, understand marketplace upload rules, and still have old listing spreadsheets. List the fields where you could contact ten relevant people within a week.", "avoid": "Avoid claiming access you have not used yet. Test whether those contacts actually reply before counting them as an advantage.", "synthetic": true}}, "8433e62be1f0c31d": {"question": "Do I genuinely care about this problem?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When forming a team, each person's care for the problem decides how much effort they will give. This check is personal before it becomes shared.", "example": "Before agreeing to join the listing-data team, each founder could write one sentence on why seller listing problems matter to them personally, then read the sentences aloud. Notice whose answer is specific and whose is vague.", "avoid": "Avoid answering yes because the other founders are enthusiastic. Their care does not count as yours.", "synthetic": true}}, "d5cb586e94adc523": {"question": "Am I willing to spend time understanding these customers?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A team can only serve customers it understands. Willingness to learn about these specific customers matters more than general interest in startups.", "example": "For small e-commerce sellers, understanding might mean watching someone prepare a batch of listings, joining seller communities, and reading their complaints about platforms. Each person can name how many hours they would spend on this in the next two weeks.", "avoid": "Avoid treating customer understanding as one teammate's job while others only build or plan.", "synthetic": true}}, "9d06bff33197fe4e": {"question": "Am I willing to interview strangers?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Interviews are a shared team job, not a task for the most outgoing person. Each member needs to decide whether they will take part.", "example": "In the listing-data team, each founder could commit to running at least two seller interviews, then compare notes. Someone uncomfortable can start by taking notes in another person's interview before leading their own.", "avoid": "Avoid letting one teammate do every interview while the rest only hear a summary of what sellers said.", "synthetic": true}}, "27245f55339cd106": {"question": "Will I stay if our original solution is rejected?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Teams often form around one solution. If that solution is rejected, members who joined only for it may leave and stall the work.", "example": "Suppose sellers reject the planned listing editor but describe a different problem with supplier data. Each founder can write whether they would stay to work on that, and what would make them leave.", "avoid": "Avoid answering for the team as a whole. Each person states their own answer, privately first if needed.", "synthetic": true}}, "6f6176b896e86f1d": {"question": "Do I believe this problem is worth investigating?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Investigating a problem costs weeks of effort. Believing it deserves that effort is what makes each member willing to do the unglamorous research.", "example": "A founder could explain to teammates why missing product data for small sellers seems worth three weeks of investigation, and what finding would make her stop. Compare whether each person's reason holds up.", "avoid": "Avoid confusing belief that the problem is worth investigating with belief that it is already solved or confirmed.", "synthetic": true}}, "4613b38c402b5d51": {"question": "Why is this founder or team suited to this problem?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten from the Founder fit field)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Investors, partners, and early customers want to know why this team, rather than another, can understand and solve this problem well.", "example": "For the listing-data venture, a fit statement might combine one founder's years running a small shop, an engineer who has built spreadsheet import tools, and access to seller groups. Attach evidence for each claim, such as past work or contacts.", "avoid": "Avoid generic traits like passion or hard work that any team could claim without evidence.", "synthetic": true}}, "f5aaa8c729a363bf": {"question": "What contribution can I make?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Team fit includes concrete work someone is willing and able to own.", "example": "I can recruit five suitable sellers and organize interview notes. This is a proposed commitment, not completed work.", "avoid": "Avoid naming a skill without owning a concrete task.", "synthetic": true}}, "0f29829a4f215f93": {"question": "Which roles are missing from the team?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Gaps in the team become gaps in the work. Seeing them early lets you recruit, learn, or plan around them before they block progress.", "example": "The listing-data team might have product and engineering skills but no one comfortable selling to store owners. Write the roles the next three weeks need, mark who covers each, and circle the empty ones.", "avoid": "Avoid assuming someone will pick up a missing role later without naming who or when.", "synthetic": true}}, "d374d58f4c0d52fa": {"question": "Which role can I take responsibility for?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Taking responsibility means owning a result, not just helping. Knowing what you can own makes it clear what the team can count on you for.", "example": "One founder might say she can own seller recruitment for the next three weeks, including outreach messages and scheduling. Write the role you will own and what done looks like for it.", "avoid": "Avoid offering to help with everything. Shared ownership of every task usually means nobody owns anything.", "synthetic": true}}, "ce59dc7f84d85d41": {"question": "Which role suits me best?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The role you take on and the role that fits you best may differ. Fit affects how well and how long you can sustain the work.", "example": "In the listing-data team, a founder may be able to code but do her best work organizing interview evidence. Compare which tasks leave you energized after a long day and which drain you, and choose accordingly.", "avoid": "Avoid picking the role with the most impressive title instead of the one matching your real strengths.", "synthetic": true}}, "315dade60eb1f6b0": {"question": "What kind of teammates am I looking for?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Knowing what you need in teammates makes recruiting deliberate. It also helps you notice when someone is pleasant but does not fill a real gap.", "example": "A founder of the listing-data venture might look for someone who can talk to store owners about budgets and is free for ten hours a week. Write the skills, availability, and attitude you need, in that order.", "avoid": "Avoid looking only for people who think and work exactly like you, which leaves the same gaps open.", "synthetic": true}}, "761da01d5eeab5f8": {"question": "Do we have different but complementary skills?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A team of similar people repeats the same blind spots. Complementary skills let the team cover research, building, and selling without overloading one person.", "example": "Put each founder's top two skills on a board. In the listing-data team, if everyone lists coding, the team lacks someone to interview sellers and someone to handle sales conversations.", "avoid": "Avoid counting difference alone as complementarity. Different skills only help if the work actually needs them.", "synthetic": true}}, "0c0826825dae8428": {"question": "How will we divide the work?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Without an agreed split, some tasks are done twice and others not at all. A clear division makes progress visible and fair.", "example": "For a three-week sprint, the listing-data team could split work into seller interviews, market notes, and a manual pilot. Assign each to one owner, with a check-in date, and write it where everyone can see it.", "avoid": "Avoid dividing work only by who volunteers first in the meeting, without checking skills and available time.", "synthetic": true}}, "49d6699783cb27af": {"question": "Who will research the problem and interview customers?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Problem research and interviews produce the evidence every later decision depends on. Without a named owner, interviews get delayed or left unrecorded.", "example": "In the listing-data team, one founder could own finding sellers, scheduling calls, and keeping a shared interview log. Others join some calls, but she makes sure each one happens and is written up.", "avoid": "Avoid naming a whole team as owner. Pick one person accountable, even if several people help.", "synthetic": true}}, "05bce37146f14dfa": {"question": "Who will analyze the market?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Market analysis tells you how many customers might have the problem and who else serves them. Someone needs to own this so it stays grounded.", "example": "For the listing-data venture, the market owner could list where small sellers gather, what tools they already use, and how many sellers fit the target description. Mark every figure as a source to check or an estimate.", "avoid": "Avoid assigning market analysis to whoever writes the pitch, which often turns it into impressive numbers without sources.", "synthetic": true}}, "0262a0c37050f11f": {"question": "Who will design and develop the product?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Design and development turn learning into something customers can try. A clear owner keeps the team from building before the problem is understood.", "example": "In the listing-data team, the engineer might own a small manual pilot first, such as a shared spreadsheet that fixes missing fields, before writing any software. She decides what gets built and when.", "avoid": "Avoid letting the builder start full development before interviews show what sellers actually need.", "synthetic": true}}, "e1cd1d87be16f6ab": {"question": "Who will handle visual design and marketing communication?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "How the team presents itself affects whether sellers respond. Visual design and messaging need an owner so outreach and pitch materials stay consistent.", "example": "For the listing-data venture, one founder could own the outreach message, a simple one-page explanation of the pilot, and before-and-after listing samples. Track which wording gets more sellers to reply.", "avoid": "Avoid leaving visuals and messaging until the night before a pitch, when nobody has tested them with customers.", "synthetic": true}}, "6f3749fb87b2ccf2": {"question": "Who will handle sales and business development?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Someone must ask customers to commit, whether to a pilot, a payment, or an introduction. Without a sales owner, interest rarely turns into action.", "example": "In the listing-data team, the sales owner could follow up with interviewed sellers, propose a paid pilot, and find out who approves spending. She records each seller's response, including refusals.", "avoid": "Avoid assuming a good product will sell itself, or that sales can start only after the product is finished.", "synthetic": true}}, "fcc580180d3d7a37": {"question": "Who will manage the project and communicate the proposal?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A project manager keeps deadlines, notes, and decisions in one place, and someone must present the proposal clearly to mentors, judges, or partners.", "example": "For the listing-data team, one founder could run weekly check-ins, keep the task board, and prepare the final proposal. She gathers evidence from others rather than writing every section herself.", "avoid": "Avoid giving this role to the person with the least other work, without checking they can communicate clearly.", "synthetic": true}}, "266573447281464d": {"question": "Are roles and owners clearly defined?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Vague roles cause dropped tasks and quiet resentment. A clear owner for each role makes it easy to see who to ask and who is accountable.", "example": "Make a simple table for the listing-data team with each role, its owner, and its expected output this week. Ask every founder to read it back and confirm without changes.", "avoid": "Avoid stopping at a verbal agreement in a meeting. If it is not written, people remember it differently.", "synthetic": true}}, "eda328c92eb45b4e": {"question": "Does every member have a specific task?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A member without a specific task drifts away or waits for direction. Concrete tasks keep everyone involved and make progress measurable.", "example": "In the listing-data team, a specific task could be interviewing three sellers by Friday or drafting the pilot offer by Wednesday. Check that each member's task has a deliverable and a date.", "avoid": "Avoid tasks like 'help with research' or 'support marketing', which cannot be checked at the end of the week.", "synthetic": true}}, "1892e108c2e3a84f": {"question": "Who will invite customers, conduct interviews, and organize the evidence?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviews involve several steps: finding people, talking to them, and turning notes into usable evidence. Each step can be skipped if no one owns it.", "example": "For the listing-data team, one founder could send invitations, a second could lead calls, and the third could tag notes by problem and seller type. Check after each round that all three steps were completed.", "avoid": "Avoid holding interviews without anyone owning the notes, which leaves evidence scattered across personal chats and memories.", "synthetic": true}}, "7b43af1e16477fb4": {"question": "Who will update the customer profile and problem definition?", "sourceSection": "Customer Validation \u0026 Growth: interviews and post-interview checks", "sourceRange": "Source: Weeks 4–5, pages 25–26, 30, 39–40, 45, 47–49. Includes direct customer questions and team checks.", "editorialNote": "", "audience": "Team check", "audienceEn": "Team check", "help": {"why": "Interviews only matter if they change the team's shared understanding. Someone must update the customer profile and problem statement when evidence shifts.", "example": "After a week of seller interviews, one founder could revise the target description, perhaps narrowing it to sellers who rely on supplier spreadsheets, and note which interviews prompted the change.", "avoid": "Avoid keeping the original customer profile because updating it feels like admitting a mistake.", "synthetic": true}}, "e9472c50960bf7bd": {"question": "Who is on the team?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Anyone reading a proposal wants to know who is actually doing the work. A clear list also shows the team who is committed and who is just interested.", "example": "For the listing-data venture, list each founder with one line on their background, such as a former small shop owner, an engineer, and a retail marketer. Include only people actively working now.", "avoid": "Avoid listing advisors or friends who gave one piece of advice as team members.", "synthetic": true}}, "1cef232fe71f0857": {"question": "What expertise and responsibilities does each member bring?", "sourceSection": "Pitch fields rewritten as questions", "sourceRange": "Source: Week 2, page 5; Week 7, page 1. Business questions retained; submission and grading requirements removed. These are rewritten from fields, not verbatim questions.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Readers of a pitch judge whether the team can deliver. Linking each person's expertise to a responsibility shows the team is organized, not just talented.", "example": "In the listing-data team, one founder brings experience running a small shop and owns seller interviews. Another has built import tools and owns the pilot. Pair each expertise with what that person is doing now.", "avoid": "Avoid listing impressive past credentials that have no connection to the current responsibilities.", "synthetic": true}}, "629eccb2e32cbdfb": {"question": "How much time is each person willing to commit each day?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Daily time determines how fast the team can learn. Knowing each person's realistic daily hours prevents plans that quietly depend on one person.", "example": "In the listing-data team, one founder might give two hours each weekday evening, another only thirty minutes. Write the numbers down and plan tasks to fit the smallest realistic daily window.", "avoid": "Avoid answering with your best day. Use what you can sustain on an ordinary busy day.", "synthetic": true}}, "0b89111698d07105": {"question": "Are we willing to work in the evenings or on weekends?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Many early teams work around jobs or classes. Agreeing whether evenings and weekends are in scope avoids surprise and resentment later.", "example": "The listing-data team could agree that weekday evenings are for async work and Saturday mornings are for joint interview reviews. Each person states which evenings or weekends they cannot give.", "avoid": "Avoid assuming everyone is available on weekends because one person is. Ask each member directly.", "synthetic": true}}, "a38ba35bce2b888e": {"question": "How will the team make decisions?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Decisions will come up before anyone feels ready. Choosing a method early keeps disagreements from turning into delays or hurt feelings.", "example": "For the listing-data team, the agreement might be that each area's owner decides within that area, and decisions about which customer to target need explicit agreement from all three founders.", "avoid": "Avoid letting the loudest or most senior person decide by default without the team having chosen that.", "synthetic": true}}, "b3d4c9b42df58fb4": {"question": "How will we handle disagreements?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A clear process helps the team keep moving when people disagree.", "example": "Agree who owns the decision, what evidence to consider, and when to revisit it. Do not treat silence as agreement.", "avoid": "Avoid treating silence as agreement.", "synthetic": true}}, "29a57578640b62fc": {"question": "Do we share the same definition of success?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "One person may see success as learning, another as launching, another as funding. Different definitions lead to different priorities and frustration.", "example": "Each founder of the listing-data venture writes privately what success would look like at the end of the course, such as a paid pilot or a clear stop decision. Compare the answers side by side.", "avoid": "Avoid using a broad phrase like 'make it work' that everyone agrees with but defines differently.", "synthetic": true}}, "33c5870b981144be": {"question": "How much time can I commit over the next three weeks?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A three-week window is short enough to plan precisely. Your personal hours decide which interviews, tests, and drafts are realistic in that period.", "example": "A founder of the listing-data team might check her calendar and find twelve free hours across three weeks, with one week mostly blocked by work. Write the hours per week rather than a single total.", "avoid": "Avoid ignoring exams, trips, or work deadlines already on your calendar when estimating your available time.", "synthetic": true}}, "39b62fd12357d8d8": {"question": "Do we care about the same problem?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Members who care about different problems pull the team in different directions. A shared problem keeps research and decisions focused.", "example": "In the listing-data team, one founder may care about seller time loss while another cares about better product photos. Each writes the problem in one sentence, then the team checks whether they describe the same thing.", "avoid": "Avoid assuming agreement because everyone likes the same product idea. The same idea can hide different problems.", "synthetic": true}}, "592c56cb8c02b1ad": {"question": "Are we willing to face the possibility that the problem is not valid?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Research may show the problem is minor or already solved. A team that cannot accept this tends to ignore evidence and keep building anyway.", "example": "The listing-data team could agree in advance: if most interviewed sellers spend only minutes on listing preparation, they will pause and reconsider. Write the condition down before the first interview starts.", "avoid": "Avoid reading every unclear interview as support. Decide what a negative result would look like before you see it.", "synthetic": true}}, "a8488581a90582cf": {"question": "Do we agree on our level of commitment and standards for results?", "sourceSection": "From Problem to Team: collaboration", "sourceRange": "Source: Week 3, pages 44–48.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Commitment and result standards decide how hard people work and what counts as done. Mismatches here are a common source of team conflict.", "example": "For the listing-data team, agree on things like replying to messages within a day and finishing interview notes within 24 hours. Example only: decide how many interviews per week each person should complete.", "avoid": "Avoid leaving standards implicit and then judging teammates against expectations they never agreed to.", "synthetic": true}}, "0dd807049fabd788": {"question": "How much time can each person commit each week?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Weekly hours turn good intentions into a workable plan. When dividing work, they show which tasks each person can realistically finish.", "example": "In the listing-data team, each founder writes weekly hours next to their assigned role. If the sales owner has only three hours a week, the team may move follow-ups to someone else.", "avoid": "Avoid assigning roles before knowing hours, which puts the biggest tasks on people with the least time.", "synthetic": true}}, "609b07e6e9c5c333": {"question": "What results does each person expect?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "People join for different reasons, such as learning, a portfolio piece, or a real company. Unspoken expectations cause disappointment when results arrive.", "example": "Each founder of the listing-data venture could name what they personally hope to gain, perhaps interview skills, a working prototype, or a chance to keep going after the course. Note where expectations differ.", "avoid": "Avoid assuming everyone wants to start a full company just because the team is working on a startup idea.", "synthetic": true}}, "763226add17f4bb9": {"question": "How will we make decisions?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When forming the team and splitting roles, a decision process tells each owner how much they can decide alone and when to ask others.", "example": "The listing-data team could write that task owners decide within their tasks, disagreements get a short discussion with evidence, and if still unresolved the project manager decides by a set date.", "avoid": "Avoid requiring everyone to agree on every small decision, which slows the team down and tires everyone out.", "synthetic": true}}, "23c07dd5fa7c7bb8": {"question": "How will we handle disagreements?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A clear process helps the team keep moving when people disagree.", "example": "Agree who owns the decision, what evidence to consider, and when to revisit it. Do not treat silence as agreement.", "avoid": "Avoid treating silence as agreement.", "synthetic": true}}, "2f1bcc9108539a75": {"question": "How will we respond when a member does not complete a task?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Missed tasks will happen. Agreeing on a response beforehand makes it a practical problem to solve rather than a personal conflict.", "example": "In the listing-data team, a missed interview could trigger a quick check-in about the cause, a new deadline, and reassigning the task if it is missed again. Agree on these steps before the first deadline.", "avoid": "Avoid staying silent and quietly doing the work yourself, which builds resentment and hides the real workload.", "synthetic": true}}, "d8cfe12743f86c0b": {"question": "How often will we communicate, and through which channels?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "A clear rhythm and channel prevent lost messages and scattered decisions, especially when members work at different times.", "example": "The listing-data team might use one group chat for quick questions, a shared document for interview notes, and a thirty-minute call every Monday. Write where decisions are recorded so nobody searches old chats.", "avoid": "Avoid spreading decisions across many apps without one agreed place to find what was decided.", "synthetic": true}}, "a6c88620ffdde5e9": {"question": "Is the proposer willing to consider different opinions?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "The person who proposed the idea often has the most attachment to it. If they resist other views, the team stops raising useful doubts.", "example": "In the listing-data team, the founder who suggested the idea could invite each teammate to name one assumption they doubt, and respond by planning how to check it rather than defending it.", "avoid": "Avoid treating the proposer's idea as fixed, with others only allowed to help execute it.", "synthetic": true}}, "24a46f651ac93736": {"question": "Do team members have consistent levels of commitment?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "When commitment is uneven, the most committed person carries the load and others feel pressured. Checking consistency surfaces this early.", "example": "Compare the listing-data founders' stated weekly hours and their actual hours after the first week. If one person gave eight hours and another one, discuss it openly and adjust roles.", "avoid": "Avoid expecting identical hours from everyone. Consistency means honest, agreed levels, not equal numbers.", "synthetic": true}}, "ac637909817b3876": {"question": "Have we agreed on commitment and how decisions will be made?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "This is the final check after forming the team. It confirms that commitment and decision rules are written down before real work begins.", "example": "Before the first sprint, the listing-data team reviews one page with each person's hours, expected results, and the decision process. Each founder confirms it in writing, and the team sets a date to revisit it.", "avoid": "Avoid ticking this box because the topic was discussed once. Agreement means something written that everyone confirmed.", "synthetic": true}}, "6c6567eb10870f51": {"question": "Can our team act, learn, and adjust quickly?", "sourceSection": "From Idea to Problem: problems and demand", "sourceRange": "Source: Week 2, pages 9, 15, 17, 19–20, 25, 27, 29.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Early ventures win by learning faster than they run out of time and money. Slow cycles mean fewer chances to correct course.", "example": "Measure how long it takes the team to go from a new idea to a seller test and a decision. If testing a new listing format takes a month, look for a smaller test that could answer the question in a week.", "avoid": "Avoid confusing speed of building with speed of learning; shipping fast without reviewing results teaches little.", "synthetic": true}}, "7fe58e2639b9e5bd": {"question": "Are we willing to change direction if our idea is rejected?", "sourceSection": "From Idea to Problem: advantages, team, and individual", "sourceRange": "Source: Week 2, pages 31, 35, 37, 43–45. The original reflection period is three weeks; retained as source context, not a fixed deadline for the website.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Founders often defend an idea after customers reject it. Agreeing in advance to change keeps evidence stronger than attachment.", "example": "Before the next round of seller conversations, each founder writes what they would do if sellers say listing preparation is not a problem. Revisit those notes after the interviews and compare them with what the team actually decides.", "avoid": "Avoid explaining away rejection as customers not understanding the idea yet.", "synthetic": true}}, "83d7791fefe7632d": {"question": "Why did we choose this direction?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Recording the reasons behind a direction lets the team check later whether those reasons still hold as new evidence arrives.", "example": "Write a short note: we focused on small sellers without a designer because several described repeated listing fixes before each launch. Link the interview notes. When new interviews arrive, check whether they support that reason.", "avoid": "Avoid recording only the decision, without the evidence or assumption that led to it.", "synthetic": true}}, "c43a0d6e99f2b2b3": {"question": "Why did we abandon another direction?", "sourceSection": "From Problem to Team: evidence and decisions", "sourceRange": "Source: Week 3, pages 37, 39, 41–42.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Abandoned directions carry lessons. Without the reasons written down, the team may return to them, or dismiss them for the wrong reason.", "example": "Suppose the team dropped product photo editing. Record why: perhaps sellers already had a photo tool, or the cost to deliver was too high. Note what new evidence would make that direction worth revisiting.", "avoid": "Avoid writing simply that it did not work, without stating what was tested and what was observed.", "synthetic": true}}, "64ff041dd3cc79e5": {"question": "Under what circumstances should we change direction?", "sourceSection": "From Problem to Team: responsibilities, team validation, and first checks", "sourceRange": "Source: Week 3, pages 47–60. Items marked as rewritten questions were expanded from responsibilities or Canvas fields.", "editorialNote": "", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Setting conditions for a pivot before results arrive stops the team from rationalizing weak outcomes after the fact.", "example": "Example only: before the pilot, agree that if fewer than a number of suitable sellers you choose agree to pay by a set date, you will test a different customer group. Write it down and date it.", "avoid": "Avoid leaving pivot conditions vague, such as if it is not going well, which no one can check.", "synthetic": true}}, "6537a3b675533f75": {"question": "How will what we learned change our next decision?", "sourceSection": "Product Strategy: acquisition, activation, retention, and measurement", "sourceRange": "Source: Week 7, pages 21–24, 40–41. Except for original questions on acquisition cost and first value, these are statements rewritten as questions.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Research should change what you do next.", "example": "If the main delay is missing supplier information, test that problem before investing in image generation.", "avoid": "Avoid repeating the original plan when evidence points elsewhere.", "synthetic": true}}, "11f748ccce111483": {"question": "What does the data say, regardless of who has the highest position?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "In small teams, the most senior or confident voice can override evidence. Putting data first keeps decisions honest.", "example": "Before a decision meeting, collect what sellers did, such as bookings, payments, and repeat batches, into one shared page. Each person reads it before anyone gives an opinion, and the decision note cites that page.", "avoid": "Avoid letting the founder with the strongest opinion choose which data counts after seeing the result.", "synthetic": true}}, "0f289a72c7f84e61": {"question": "Are we deciding based on future value or past costs?", "sourceSection": "Product Strategy: competition, pricing, and building", "sourceRange": "Source: Week 7, pages 34–36, 39, 43, 45, 48–49, 51. Rewritten questions are marked; tool or technology choices are not mandatory for every founder.", "editorialNote": "(rewritten as a question)", "audience": "Team / individual reflection", "audienceEn": "Team / individual reflection", "help": {"why": "Time and money already spent cannot be recovered. Decisions should depend on what each option can bring from now on.", "example": "The team spent weeks building an automated photo editor that sellers rarely use. Compare the options from today: what each would cost next and what it could bring. Leave the past weeks out of that comparison.", "avoid": "Avoid continuing a project mainly because so much has already been invested in it.", "synthetic": true}}, "f1dc316b6f3da70f": {"question": "Do you like our idea?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "People are polite about ideas. Liking an idea costs nothing and says little about whether they have the problem or would act.", "example": "Ask a seller to walk you through their last product launch: what they prepared, which fields were missing, and how long fixes took. Their past actions tell you more than their opinion of your idea.", "avoid": "Avoid treating compliments about the idea as evidence of demand.", "synthetic": true}}, "3a190bc64bfa1b05": {"question": "Would you use it?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Predictions about future behavior are unreliable. Most people say yes to be kind, then never use the product.", "example": "Instead, ask what the seller currently does to prepare listings and what they have tried to make it easier. Later, offer a pilot for their next batch and record whether they actually send the files.", "avoid": "Avoid counting hypothetical yes answers as future users or as signs of demand.", "synthetic": true}}, "6c4e4e9e6fa2f1ad": {"question": "How much would you pay?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(asked before understanding value)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Asking about price before the customer understands the value produces guesses. The answer reflects the question, not real willingness to pay.", "example": "First learn what the listing problem costs the seller, such as hours or delayed launches. After they have seen a prepared batch, offer a specific paid pilot and record whether they accept, negotiate, or decline.", "avoid": "Avoid quoting a hypothetical price from an early conversation as their willingness to pay.", "synthetic": true}}, "3e07881fefa4cddc": {"question": "What other features could we add?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Brainstorming features shifts focus from the customer's problem to your solution. It often grows scope before the core value is confirmed.", "example": "Ask which part of the seller's current listing work causes the most delay, and ask them to show it. Return to feature ideas only after a pilot shows which outcome sellers keep coming back for.", "avoid": "Avoid collecting feature wish lists from customers who have not yet used the core offer.", "synthetic": true}}, "500a5fd4e61578e1": {"question": "Don’t you think this process is cumbersome?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(leading question)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "This is a leading question. It suggests the answer you hope for, so agreement tells you nothing about the seller's real experience.", "example": "Ask neutrally: walk me through the last time you listed new products. Listen for steps they describe as slow or repeated. If they never mention frustration, note that as evidence too.", "avoid": "Avoid wording questions so the customer only has to agree with you.", "synthetic": true}}, "dae99895abe6f43e": {"question": "What features should the app have?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(should not precede problem validation)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Choosing app features before the problem is confirmed means building around a guess. Features should follow evidence about the problem.", "example": "Before listing features, confirm that sellers repeatedly struggle with missing fields or titles. Deliver one batch manually and note which steps you actually performed; those steps suggest the first features worth building.", "avoid": "Avoid starting with a feature roadmap when you have not yet seen the problem happen.", "synthetic": true}}, "c0ef952d29cab6c5": {"question": "What should the website look like?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(should not precede problem validation)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Website design is hard to get right before you know who the customer is and what will convince them.", "example": "A plain page or a direct message may be enough to offer sellers a pilot. Once interviews show which problem and words sellers use, design the website around that language.", "avoid": "Avoid spending weeks on visual design before a single seller has agreed to try the service.", "synthetic": true}}, "c745b021d7a3ae1a": {"question": "Which AI model should we use?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(should not precede problem validation)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Model choice is an implementation detail. It cannot be judged until you know which task customers need done and what quality matters.", "example": "Prepare one seller's listings manually and note which steps take longest, such as writing titles or filling specs. Test models later against those specific steps, using the seller's real product data.", "avoid": "Avoid comparing AI models before knowing which customer task they need to perform.", "synthetic": true}}, "520ecbdea25882b9": {"question": "What should the brand be called?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(should not precede problem validation)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Naming feels like progress but rarely affects early learning. A name chosen before the customer is clear may need to change.", "example": "Use a simple working name while you test with sellers. Revisit the brand once you know which customer group you serve and which words they use to describe their listing problem.", "avoid": "Avoid long naming debates that delay conversations with the sellers you need to learn from.", "synthetic": true}}, "2531c7cb1255a920": {"question": "What color should the logo be?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(should not precede problem validation)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Logo color has almost no effect on whether the problem is real. It uses time that early customer work needs more.", "example": "Skip the logo for now and spend that time contacting sellers who list products regularly. Return to visual identity once a few sellers are paying and you are preparing a wider launch.", "avoid": "Avoid treating logo or color decisions as milestones during problem discovery.", "synthetic": true}}, "a3bfc377f53d9bca": {"question": "What is the minimum number of features needed to call this a product?", "sourceSection": "Questions the materials advise avoiding or deferring", "sourceRange": "These are not recommended answer prompts; retained as counterexamples. Source: Week 3, page 18; Weeks 4–5, pages 9, 27; Week 7, pages 28, 30.", "editorialNote": "(the material recommends asking instead what value would earn the first payment)", "audience": "Counterexample / defer", "audienceEn": "Counterexample / defer", "help": {"why": "Counting features does not define a product. The course suggests asking what value a customer needs to receive before paying for the first time.", "example": "Ask instead: what must a seller receive to pay for their first batch? Perhaps it is listings ready to publish without corrections. Build or deliver only what produces that outcome, even manually.", "avoid": "Avoid setting a feature checklist as the bar for launch instead of a paying customer's outcome.", "synthetic": true}}}, "provenance": {"translationPolicy": "Original English questions and derived examples retained. Chinese source metadata translated for display; original provenance remains in the pinned catalog.", "sourceFiles": [{"file": "Week2-9_16-從 Idea 到 Problem.md", "sha256": "fc00e81a7289f0c5c170395f41a153cc2539a91979b8b7e6df348687e425bbe8"}, {"file": "Week3-0923-Problem-to-Team.md", "sha256": "c1a5bbd60fcabcbef74ed500ea492c289fe548d6328774d26eaf878db5cdf95c"}, {"file": "Week4-5-Customer-Validation-Growth-revised.md", "sha256": "dc1a8fe4d7f8c3bd5092a13a724a813c3cebd1de53cf140a374ee3b5770cb1d6"}, {"file": "week7-10_21- Product Strategy.md", "sha256": "5ee9acf7c844239794998713d5162b2ed023ac2d9a19cf8c8df85584f2ccc3fe"}], "questionCount": 362, "derivedExamplePolicy": "Existing synthetic examples are translated, not replaced, and are not attributed as original Cami slide examples."}}, "zh-TW": {"locale": "zh-TW", "categories": {"Company Purpose": "公司業務與目標", "Problem": "問題", "Situation \u0026 Trigger": "情境與觸發事件", "Pain \u0026 Impact": "痛點與影響", "Customer \u0026 Target Persona": "顧客與目標客群", "Users, Payers \u0026 Decision-Makers": "使用者、付費者與決策者", "Current Alternative \u0026 Competitors": "現有解法與競爭對手", "Market \u0026 Why Now": "市場與時機", "Unfair Advantage": "不公平優勢", "Evidence": "證據", "Customer Discovery": "顧客探索", "Key Assumption": "關鍵假設", "Validation \u0026 Next Experiment": "驗證與下一個實驗", "Validation Signal": "驗證訊號", "Success Criteria": "成功標準", "Solution \u0026 Thin Product": "解決方案與最精簡產品", "Technology \u0026 Design": "技術與設計", "Customer Acquisition": "顧客取得", "Activation": "啟用", "Retention": "留存", "Instrumentation": "量測", "Business Model \u0026 Monetization": "商業模式與收費方式", "Unit Economics \u0026 Financial Projections": "單位經濟與財務預測", "Growth": "成長", "Founder Fit": "創辦人適合度", "Team \u0026 Role Coverage": "團隊與角色互補", "Human Fit \u0026 Commitment": "合作方式與投入程度", "Decisions \u0026 Learning": "決策與學習", "Questions to Avoid or Defer": "應避免或延後的問題"}, "questions": {"33785cebf03ba018": {"question": "我們公司的業務與目標是什麼？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "公司的業務與目標敘述，讓投資人、應徵者與團隊了解：除了最初銷售的產品，公司存在是為了創造什麼持續的改變。", "example": "草稿：協助沒有設計師的小型網路賣家發布完整、正確的商品頁，讓他們能把時間花在顧客身上。接著檢查每個進行中的專案，從訪談到試行，是否仍服務於這句話。把它當成工作草稿，取得證據後再回頭檢查。", "avoid": "避免寬泛到適用於任何公司的口號，例如讓所有人的商務更有力量。", "synthetic": true}}, "7d52bc0a0b3cb5ee": {"question": "我們要如何用一句話介紹這項創業構想？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "如果創業構想無法用一句話說清楚，聽者可能什麼都記不住，團隊對正在做的事也可能沒有共同理解。", "example": "試用這個句型：我們協助［顧客］完成［任務］，不必承受［痛苦］。示範構想可以寫成：我們協助沒有設計師的小型電商賣家準備完整商品頁，不必手動複製資料。念給團隊外的人聽，請對方用自己的話重述。", "avoid": "避免還沒說清楚幫助誰、解決什麼，就堆疊「AI 驅動平台」之類的技術詞。", "synthetic": true}}, "834db9e9de30b592": {"question": "這個問題是否真實存在？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "許多想法源自創辦人想像的問題。及早確認問題是否存在，可以避免花幾個月開發，卻沒有顧客真的面對那個困難。", "example": "尋找問題留下的痕跡。請幾位小型賣家展示最近一次上架過程：試算表、填到一半的商店表單、缺少規格的筆記。如果沒有人能展示這些痕跡，就把問題視為尚未確認，而不是假設它只是藏起來了。", "avoid": "避免把朋友說「聽起來有可能」當成問題存在的證據。", "synthetic": true}}, "cb6ee9e32aaa5cd4": {"question": "這個問題為什麼值得被解決？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題即使真實存在，仍可能太小、太少發生，或忍受它的代價太低。值不值得解決，取決於解決後會替顧客改變什麼。", "example": "寫下如果準備商品頁不再費事，賣家會有哪些改善：更快上架、減少規格錯誤造成的退貨、晚上有更多空閒。接著規劃訪談，確認賣家真的在乎哪些改變，而不是挑聽起來厲害的改變。", "avoid": "避免只因為技術上很有趣，就認定問題值得解決。", "synthetic": true}}, "5d1ba15422ef8a4f": {"question": "哪些工作流程仍然緩慢、昂貴或容易出錯？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "緩慢、昂貴或容易出錯的流程，會留下可以量測的問題痕跡。它們讓你有具體的觀察位置，而不只是模糊的不滿。", "example": "逐步畫出一位賣家的上架流程：蒐集供應商規格、重新命名照片、撰寫標題、填寫商店欄位、發布前再次檢查。標出哪一步最耗時、哪一步需要付費協助、哪一步會造成後續修正。透過觀察或詢問最近一批商品，確認每一個標記。", "avoid": "避免把每一步都列為痛點，否則會掩蓋真正讓人困擾的流程。", "synthetic": true}}, "19323bdcc6b1bd3c": {"question": "哪些問題已經長期存在，卻一直沒有被妥善解決？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "即使已有工具，問題仍長期存在，通常表示某些需求沒有被滿足；也提醒你，簡單的解法可能早就試過卻失敗了。", "example": "詢問賣家過去為準備商品頁試過什麼：範本、平台匯入工具、自由工作者、週末來幫忙的親戚。記下每種做法為何被放棄。如果各種替代做法反覆被放棄，表示問題仍存在；若某個工具其實已經夠用，也要記錄。", "avoid": "避免在沒有查過既有工具與替代做法前，就認定沒有人解決過。", "synthetic": true}}, "6c859a37ada46474": {"question": "這項產品真的需要存在嗎？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這迫使團隊在開發前做判斷：如果問題與顧客證據都薄弱，誠實的答案可能是產品目前還不該存在。", "example": "決定前先設定一個簡單測試。例如事先同意：只有當賣家描述近期發生且成本高的上架問題，並有人同意付費試行時，產品才值得存在。記錄發現；如果沒有達到標準，願意停止或改變方向。", "avoid": "避免只因團隊興奮、已有展示版本，或已花時間開發，就回答應該存在。", "synthetic": true}}, "9d52c3ebba5bf5c4": {"question": "我們想解決什麼問題？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在最初構想階段，說清楚問題，能把團隊注意力從想像的產品拉回必須理解的需求。", "example": "每位創辦人先各自在卡片上寫下問題，不先討論。示範構想中，有人可能寫商品資料缺漏，有人寫修圖太慢，有人寫商店格式太多。比較卡片，決定下一輪工作要專注哪個問題。", "avoid": "避免用產品構想本身回答，例如「我們正在做 AI 上架工具」。", "synthetic": true}}, "1f655b44f7474cc1": {"question": "我們是在推銷自己想做的產品，還是在理解顧客真正需要解決的問題？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "創辦人很容易從學習變成推銷自己的想法。辨認目前處於哪種狀態，才能讓訪談與計畫誠實呈現仍不知道的事。", "example": "回顧最近幾次與賣家的對話。計算展示上架工具構想花了幾分鐘，詢問賣家如何準備最近一批商品又花了幾分鐘。如果多數時間都用來提案，就重新設計下一次對話，圍繞顧客過去的行為。", "avoid": "避免把產品展示稱作顧客訪談；那收集的是反應，不是問題。", "synthetic": true}}, "2c559978dadea0e2": {"question": "問題是什麼？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這是結構化問題敘述的第一部分。這裡定義清楚，會影響後續如何描述顧客、市場與解決方案。", "example": "把困難寫成可以查證的敘述：小型賣家每次上架前都花好幾個小時蒐集規格、補齊商店缺少的欄位。把顧客、市場規模與解法留給後續區塊，讓這個區塊只專注於困難本身。", "avoid": "避免在這個區塊把顧客、市場與解法混成一個長句。", "synthetic": true}}, "7046f8b4d350ef5a": {"question": "最重要、最需要解決的問題是哪一個？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊通常同時發現好幾個問題。選出最重要的一個，才能把有限時間用在最可能真正重要的困難上。", "example": "列出示範構想中的候選問題：規格缺漏、標題不一致、照片品質差、各商店格式不同。逐一記下賣家提及的頻率，以及造成的成本。選一個先研究，並寫下其他問題為什麼先等。", "avoid": "避免選擇你偏好的功能能解決的問題，而不是證據最強的問題。", "synthetic": true}}, "9b4d70faedf58c4b": {"question": "這個問題背後可能有哪些根本原因？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "表面症狀與根本原因需要不同解法。找出可能的根本原因，可以避免只針對看得見的症狀做修補。", "example": "反覆問為什麼。商品頁不完整。為什麼？規格缺漏。為什麼？供應商把規格分散在電子郵件與 PDF 裡。為什麼？沒有標準的資料索取格式。每個答案都是假設；查看賣家實際收到的供應商檔案來驗證。", "avoid": "避免在遇到第一個符合你原本想做解法的原因時，就停止追問。", "synthetic": true}}, "560e4df87ebc8e49": {"question": "我們目前認為問題是什麼？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "把目前的想法寫下來，才能測試。之後的證據才能確認、削弱或取代它，而不是被悄悄吸收進原本說法。", "example": "記下一段附日期的敘述，例如：我們目前認為，小型賣家準備商品頁時，最多時間花在向供應商蒐集缺少的規格。註明目前有哪些證據支持，以及什麼會讓你改變想法。下一輪訪談後，重新檢查同一段敘述。", "avoid": "避免把目前的想法說成定論；標明這是仍需查證的想法。", "synthetic": true}}, "ed46f7a5b1779e3e": {"question": "是問題本身不夠清楚，還是尚未找到好的表達方式？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "別人聽不懂時，原因可能是問題模糊，也可能只是表達不清楚。兩種情況需要不同處理。", "example": "向兩位團隊外的人解釋問題。如果他們無法重述，試著用一個具體賣家故事改寫。如果他們仍對問題有不同理解，團隊本身可能就在想不同問題；應回到證據，而不是繼續潤飾文字。", "avoid": "避免在底層問題尚未取得共識或研究前，就無止盡地重寫提案。", "synthetic": true}}, "8d4de5965b099052": {"question": "團隊能否清楚說明問題？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這是團隊檢查：如果每個人描述的問題不同，訪談、開發與決策就會走向不同方向。", "example": "請每位成員不看筆記，在一分鐘內說明問題。以示範構想為例，聽聽大家是否都提到同一類賣家與同一個上架困難。記下哪些版本偏向功能，在下一輪訪談前討論差異。", "avoid": "避免只讓最有自信的創辦人回答，就假設其他人都同意。", "synthetic": true}}, "16dbf99ca6f3f1ad": {"question": "我們能否用一至兩句話說清楚問題？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "限制一至兩句，會迫使你刪去旁枝問題。簡短敘述也較容易在訪談中測試。", "example": "第一句說明誰遇到什麼：沒有設計師的小型賣家，難以準備完整商品頁。第二句說明影響：規格缺漏會延誤上架並導致修正。如果需要第三句，檢查你是不是其實在描述兩個問題。", "avoid": "避免用逗號與「以及」把好幾個問題硬塞進一個長句。", "synthetic": true}}, "fb34ff456044e838": {"question": "我們是否在描述顧客的困難，而非產品功能？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "功能描述的是你的解法；困難描述的是顧客的世界。只有困難才能告訴你，是否有人需要你計畫做的東西。", "example": "閱讀問題敘述，把所有關於產品的名詞畫線，例如自動填寫、範本引擎。把這些部分改寫成賣家經歷的事：把同一份規格重新輸入三個商店。保留改寫版本，拿去訪談。", "avoid": "避免寫「賣家需要 AI 上架助理」；那是在說產品，不是在說困難。", "synthetic": true}}, "f52c38dcf3c509f4": {"question": "問題是否具體到可以進行訪談？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "訪談需要具體對象。問題太廣，問句與回答就會模糊，無法在顧客間比較。", "example": "太廣：經營網路商店很難。夠具體：為新一批商品準備規格資料太耗時。試著針對最近一次上架寫三個訪談問題。如果問句容易寫出，而且都指向真實事件，問題就夠具體。", "avoid": "避免泛泛訪談電商經營，期待清楚的問題會自己出現。", "synthetic": true}}, "585020cf36a01faf": {"question": "現在到底哪裡有問題？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "具體情境比籠統抱怨更容易研究。", "example": "一位小型賣家在試算表與商店編輯器之間複製商品資料，每次上架前再補齊缺少欄位。這是待研究的假設。", "avoid": "避免沒有具體人物或情境的抽象抱怨。", "synthetic": true}}, "1a1fcb667ac94469": {"question": "這個問題真的存在嗎？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在產品策略中，必須先確認問題存在，才能設定範圍與成果；否則路線圖就建立在無人檢查過的猜測上。", "example": "承諾功能路線圖前，先收集直接證據：觀察幾位賣家準備真實商品批次，或經同意取得他們的上架試算表副本。把觀察結果與策略假設並列，標出沒有觀察支持的假設。", "avoid": "避免把問卷中對未來假想使用的回答，當作問題今日存在的證據。", "synthetic": true}}, "a0362e61097d453d": {"question": "我們要解決誰的問題？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "同一個問題對不同人的影響不同。說清楚是誰的問題，才能決定訪談誰、為誰設計，以及量測什麼成果。", "example": "區分小型商店中的角色：店主、負責上傳商品的助理、修圖的自由工作者。決定先專注誰的上架困難，例如執行上傳的助理，再確認這個人確實經歷你描述的問題。", "avoid": "避免回答「小企業」或「所有網路賣家」；範圍太廣，無法據以行動。", "synthetic": true}}, "638bae9d8892ea6b": {"question": "我們的顧客面對什麼問題？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "提案中的問題頁必須從顧客角度出發。投資人要看能想像得出的困難，並有你的實際發現支持。", "example": "圍繞單一賣家情境撰寫：每次上架前，商店助理追討供應商規格、重新輸入商店，再補齊缺少欄位。只補入真正收集到的證據，例如有多少賣家描述這件事，並清楚標示。", "avoid": "避免整頁都是產業統計，卻沒有自己顧客說過的內容。", "synthetic": true}}, "2c7e259a94952f0d": {"question": "這個問題是否會反覆發生？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "一次性的問題較少能支撐一門生意。反覆發生表示顧客一再面對痛苦，因而值得採用解法。", "example": "詢問賣家過去幾個月何時準備商品頁，逐次標上日期。示範構想中，每週新增商品的賣家會反覆面對問題，而一年只上架一次整份目錄的人則不會。比較這些模式。", "avoid": "避免因任務聽起來像例行工作就假設會反覆發生；要查過去行為的實際日期。", "synthetic": true}}, "771781f0afc12eb8": {"question": "問題在什麼情境下發生？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題會出現在特定時刻，不是到處都發生。知道那些時刻，才能了解顧客何時需要協助、解法必須放在哪裡。", "example": "收集賣家準備商品頁遇到困難的時刻：新供應商批次到貨、季節促銷將至、平台更改必填欄位。逐一記下誰參與、當時在做什麼，找出不同賣家最常提到的情境。", "avoid": "避免把問題說成一直存在；沒有明確情境的痛苦很難研究。", "synthetic": true}}, "459e70d7c4acd8b1": {"question": "這件事在什麼情境下發生？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這裡的情境是結構化問題敘述的一部分。它把問題連結到顧客，也告訴你應到哪裡觀察。", "example": "在問題區塊旁加上一行情境：當賣家收到供應商新一批商品，必須在預定上架日期前發布。接著檢查顧客與市場區塊，描述的是否真是會面對這個情境的人。", "avoid": "避免只寫「日常工作時」之類過度籠統的情境，讓人不知道去哪裡觀察。", "synthetic": true}}, "0af7eff008b767a2": {"question": "發生的頻率有多高？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "頻率會放大其他影響。每週遇到的輕微痛苦，可能比一年一次的嚴重問題更重要。", "example": "對每位訪談賣家，記下你選定的近期期間內準備了幾批商品；若對方能展示商店紀錄，就以紀錄為依據。把次數放在問題敘述旁，讓團隊看到真實頻率，而不是估計。", "avoid": "避免只寫「經常」或「定期」；改記明確時間範圍內的次數。", "synthetic": true}}, "2bec2238782323b7": {"question": "問題是否持續或反覆發生？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題可能長期持續，也可能反覆出現。區分兩者，會影響解法是一次修復，還是持續協助。", "example": "示範構想中，混亂的舊商品目錄會一直存在，直到有人整理一次；新批次的準備則每次到貨都會發生。問賣家屬於哪種情況，若兩者皆有就都記錄。這會影響你提供專案服務還是訂閱。", "avoid": "避免把持續存在與反覆發生當成同一件事；它們會導向不同服務。", "synthetic": true}}, "90ab39d19a230b5f": {"question": "這個問題還可能出現在哪些情境？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "探索其他情境，可能發現更大或更急迫的同類問題，也可能顯示最初情境設得太窄。", "example": "從新批次上架出發，想想相關時刻：把商店移到另一個平台、開設第二個通路、促銷時調整價格。把每個情境當成假設，並各設計一個訪談問題，確認賣家近期是否真的遇過。", "avoid": "避免還沒確認任何情境，就把所有想像的情境都放進範圍。", "synthetic": true}}, "8e3e420bff537861": {"question": "問題發生在什麼情境？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在顧客驗證中，情境會成為可測試假設的一部分。精確情境能告訴你要找哪些顧客與時刻。", "example": "把情境寫進假設：促銷前不久，供應商送來大量且規格不全的商品時，賣家最困難。接著規劃如何確認，例如請受訪者帶你走過最近一次供應商到貨批次的處理過程。", "avoid": "避免測試沒有情境的假設；結果會過於分散，難以解讀。", "synthetic": true}}, "e7d110612895b6ad": {"question": "問題發生的頻率有多高？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題發生的頻率，會改變解決它的價值。", "example": "請賣家展示最近三次上架過程。記錄日期，不要猜每週平均次數。", "avoid": "避免沒有查看實際事件就猜測頻率。", "synthetic": true}}, "4e8d6eafd44e46bc": {"question": "最近一次發生是什麼時候？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "最近一次發生的事件最容易準確記得，能把假設放在真實事件上，而不是一般印象。", "example": "在每位賣家的筆記中，補上最近一次出問題的上架批次日期。不知道就標記該人的假設尚未確認。若最近一次已是很久以前，賣家現在可能沒有強烈感受到問題。", "avoid": "避免憑記憶填入一個典型日期；在顧客提供前先留白。", "synthetic": true}}, "735f675603a40328": {"question": "什麼事件會讓顧客開始尋找解法？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "人們通常要遇到某件事，才會開始尋找協助。觸發事件會告訴你顧客何時願意改變，以及可以在哪裡接觸他們。", "example": "示範構想的可能觸發事件：平台因缺少欄位拒絕商品頁、大批供應商商品到貨，或原本處理上傳的助理離職。問賣家上次找工具或自由工作者前發生了什麼，並記下事件。", "avoid": "避免假設觸發事件就是看到你的廣告；要問他們開始尋找之前發生了什麼。", "synthetic": true}}, "62a2d4fe430a0d69": {"question": "什麼情境能解釋他們的購買動機？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "購買動機與特定情境相連。知道是哪種情境，才能把一般需求變成現在付費的理由。", "example": "比較兩位賣家：一位想以後把商品頁整理得更整齊，另一位必須在節日促銷前把季節新品上架。後者的情境解釋了購買急迫性。訪談時詢問：上次為上架協助付費，例如雇用自由工作者時，當時發生了什麼？", "avoid": "避免在沒有任何情境迫使決定時，把一般興趣當成購買動機。", "synthetic": true}}, "4cb11ab56df49992": {"question": "你上一次遇到這個問題是什麼時候？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "詢問上一次，能把顧客帶回真實、近期事件，比對平常頻率的印象更可靠。", "example": "問賣家：上次準備商品頁遇到困難是什麼時候？再追問：上架什麼、誰協助、最後如何？留意日期與具體細節。若對方回答「通常」或「總是」，溫和地請他舉出一次事件。", "avoid": "避免接受「一直都是」之類的一般答案，而不追問具體事件。", "synthetic": true}}, "463c24649929713b": {"question": "是否有明確期限或觸發事件，讓採取行動變得急迫？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "在成長上，急迫性解釋了顧客為何現在行動，而不是以後。期限與觸發事件有助於安排接觸與提供服務的時間。", "example": "尋找示範構想中的期限：節日促銷開始日、平台政策的生效日、下週到貨的供應商商品。記下哪些顧客提到這些期限，並測試在期限前聯繫賣家，是否會改變回應。", "avoid": "避免用倒數優惠製造假的急迫性，取代尋找顧客真實的期限。", "synthetic": true}}, "fe0ae8758711d119": {"question": "這個問題多久發生一次？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題發生的頻率，會改變解決它的價值。", "example": "請賣家展示最近三次上架過程。記錄日期，不要猜每週平均次數。", "avoid": "避免沒有查看實際事件就猜測頻率。", "synthetic": true}}, "d078ee4ea9e0ee8c": {"question": "誰，在什麼情境下，遇到了什麼困難？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這把誰、什麼事與何時組合成可測試的敘述，讓產品策略建立在特定人物面對的特定時刻。", "example": "填入句型：［誰］在［情境］中遇到［困難］。示範構想：小型賣家的商店助理，在供應商送來資料缺漏的商品批次時，難以補齊商品規格。訪談時分別確認每個部分。", "avoid": "避免有任何部分留白或過度籠統，例如「使用者有時準備商品頁會有困難」。", "synthetic": true}}, "e1c6a66845ba9698": {"question": "你上一次遇到這個問題是什麼時候？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "在產品策略工作中問這一題，是要確認你計畫範圍背後的問題，今日是否仍發生在真實顧客身上。", "example": "問賣家：你上次準備商品頁遇到困難是什麼時候？若可以，請他打開當時的商品頁或試算表。記下日期與出錯情況，再和目前範圍要處理的問題比較。", "avoid": "避免問對方會不會使用某項功能；改問最近一次真實事件。", "synthetic": true}}, "436b96cc878974d4": {"question": "顧客是否真的因這個問題感到痛苦？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問題可能存在，卻不太痛。真正的痛苦，才會讓顧客改變習慣、花錢，或挪時間嘗試新解法。", "example": "從賣家的行動找痛苦跡象，而不是看他給幾分。他是否熬夜修改商品頁、付錢給自由工作者，或向供應商抱怨？逐位記錄這些行動。如果口頭認同卻很少行動，痛苦可能不深。", "avoid": "避免依賴一到十分的痛苦評分；要找因問題而採取的行動。", "synthetic": true}}, "0a399e609f080f69": {"question": "如果問題沒有被解決，顧客會失去什麼？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "損失說明了事情的重要性。如果不處理問題也損失不大，顧客就沒有太多理由採用新東西。", "example": "列出商品頁不完整可能造成的損失：延遲上架、規格錯誤引起退貨、占用原本服務顧客的時間。把每項都視為假設。訪談時詢問，上次不完整的商品頁發布後，實際發生了什麼。", "avoid": "避免預設損失就是營收；很多損失其實是時間、壓力或錯失機會。", "synthetic": true}}, "f744e8e88d4ed1e5": {"question": "我們的解決方案是止痛藥，還是維他命？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "止痛藥減輕顧客已感受到的痛苦；維他命提供的好處則容易被延後。這個差異會大幅影響銷售難度。", "example": "問賣家在沒有你的解法時，現在怎麼做。如果已付錢請自由工作者，或熬夜完成商品頁，你的服務可能是止痛藥。若只是說以後有更漂亮的標題也不錯，就較像維他命。記錄你聽到哪種模式。", "avoid": "避免因團隊相信產品，就把它稱為止痛藥；讓顧客行為來判斷。", "synthetic": true}}, "85c60ac8574c4de8": {"question": "這個問題會造成什麼損失？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在結構化問題區塊中，損失把問題與採取行動的理由連結起來，也有助於之後估算市場。", "example": "在問題敘述下加一行損失：延遲上架、額外自由工作者費用、缺少欄位引來平台警告。標記各項是顧客說過，還是仍屬假設。後續進入顧客與市場區塊時，只使用實際聽到的項目。", "avoid": "避免列出無法追溯至任何顧客對話或觀察的損失。", "synthetic": true}}, "bb4784ca5fdbd032": {"question": "問題是否具有真實影響？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "繼續前先做團隊檢查：問題應對顧客造成真實改變，而不只是理論上討論的小麻煩。", "example": "團隊共同選一位訪談過的賣家，描述問題對他造成的變化，例如延遲上架或額外費用。如果沒有人能指出具體影響，就先暫停，在分工做解法前蒐集更多證據。", "avoid": "避免在無人能指出具體影響時，只靠大家同意就通過檢查。", "synthetic": true}}, "89ec57f8f95bc2bb": {"question": "這個問題對顧客的影響有多大？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "影響大小決定優先順序。顧客會對明顯影響工作、金錢或安心程度的問題採取行動。", "example": "寫下一個影響假設，例如準備商品頁占用助理一週很大比例的時間。再規劃確認方式：請賣家估算最近一批花了幾小時，或與他已有的工時紀錄比較。", "avoid": "避免只用「巨大」「顯著」形容影響，卻不說影響了什麼。", "synthetic": true}}, "6ba45e0a9c688a55": {"question": "顧客已經花了多少時間或金錢處理這個問題？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "已花費的時間或金錢是有力證據，顯示在你出現之前，顧客就已認為問題值得處理並採取行動。", "example": "在顧客假設中加一欄過去投入。示範構想可能包括自由工作者費用、購買試算表範本，或店主修改商品頁的工時。只根據賣家描述的真實過去行動填寫。", "avoid": "避免猜顧客可能花多少；這題問的是已經花了多少。", "synthetic": true}}, "318d67ab9a5a2cc4": {"question": "如果顧客什麼都不做，會發生什麼事？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "當後果看得見時，不方便的程度才會更清楚。", "example": "可能的後果是商品延遲上架。詢問近期事件與實際影響，不要直接假設營收損失。", "avoid": "避免沒有證據就宣稱造成營收損失。", "synthetic": true}}, "3ee3df5b7619c269": {"question": "問題是否嚴重到需要採取行動？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "有些問題真實存在，但仍可忍受。如果沒有跨過必須行動的程度，顧客就會繼續忍受。", "example": "找出賣家不得不行動的時刻：平台封鎖商品頁、錯過上架日期、顧客抱怨規格錯誤。記下是否真的發生，以及賣家接著做什麼。如果賣家聳聳肩照常做，問題可能還不夠嚴重。", "avoid": "避免用團隊對問題的強烈感受，決定問題的嚴重性。", "synthetic": true}}, "1ff78355287dc618": {"question": "解決問題的成本，是否比忍受問題更高？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "顧客會比較改變所需的努力與繼續忍受的成本。如果解決的成本更高，等待是合理的選擇。", "example": "對一位賣家，比較忍受的成本，例如每批多花幾小時，與轉換的成本：學新工具、搬資料、付費。請賣家描述兩邊，記下哪些地方的轉換負擔比痛苦本身更大。", "avoid": "避免只比較你的價格與他的痛苦；要包含設定努力、學習時間與風險。", "synthetic": true}}, "d645561ca03f0fef": {"question": "這個問題會造成哪些時間、金錢、風險或情緒成本？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（由假設句轉問句）", "audience": "團隊／個人自問", "help": {"why": "成本有不同形式。說清楚種類，才能理解顧客在乎哪一種成本，以及該如何談。", "example": "分類賣家的可能成本：重新輸入規格的時間、付給自由工作者的錢、平台處罰風險，以及上架前壓力。標記每位受訪者未經提示就提到哪些。最常出現的種類，應影響下一個假設。", "avoid": "避免把所有成本都換算成金錢；時間、風險與情緒成本可能更重要。", "synthetic": true}}, "4fda8d4e230766e2": {"question": "我們解決的是重要痛點，還是單純不方便？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "小麻煩容易得到禮貌認同，卻很少促成行動。及早區分，可以避免花時間處理沒人願付費解決的問題。", "example": "比較不同賣家的反應。重要痛點的跡象：你還沒問就主動提、描述替代做法，或提到成本。小麻煩的跡象：提示後同意，卻想不起近期案例。逐位記下出現哪些跡象。", "avoid": "避免把賣家對你的描述點頭，當成重要痛點的證據。", "synthetic": true}}, "060bff1f05edc44f": {"question": "可以描述最近一次具體發生的情況，以及造成的損失嗎？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由追問指示轉問句）", "audience": "直接問顧客", "help": {"why": "近期、具體且附損失的例子不容易憑空編出。它能把一般抱怨轉成可記錄、可比較的證據。", "example": "問：可以帶我回顧最近一次出錯的上架批次，以及它造成什麼代價嗎？留意哪些商品、晚了多久上架、顧客說了什麼等細節。若賣家泛泛回答，就請他指出某個特定批次。", "avoid": "避免自己暗示損失，例如「有損失銷售嗎？」讓顧客自己說。", "synthetic": true}}, "362ff09eda2b48e1": {"question": "你花了多少時間、金錢或人力處理這個問題？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "直接問顧客", "help": {"why": "已投入的努力，顯示問題在實際生活中有多重要，也提供解法必須超越的基準。", "example": "問賣家最近一批商品：你或助理花了幾小時？有付錢請人協助嗎？把時間、金錢、人力分別記錄。若不確定，就問那週還有什麼事因此延後。", "avoid": "避免問他願意花多少錢解決；要問已經投入多少。", "synthetic": true}}, "a82ca02ccc0afdd8": {"question": "當你沒有處理時，發生了什麼後果？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "直接問顧客", "help": {"why": "忽略問題後實際發生的事，會揭露真正後果。如果沒什麼事發生，痛苦可能比想像的小。", "example": "問：有沒有把商品頁留著不完整，或直接發布的時候？之後發生什麼？留意退貨、平台警告或顧客詢問等事件。若答案是沒發生什麼，也要記下；這與戲劇性的故事同樣重要。", "avoid": "避免問「如果不處理會怎樣」；假設性的答案容易誇大。", "synthetic": true}}, "944d5ae93a005d10": {"question": "問題是否造成收入損失、額外成本、法律風險、客訴或聲譽損失？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "在成長上，這些具體損害能讓決策者與預算負責人看見問題，往往決定企業是否願意付費。", "example": "逐類比對賣家回報：促銷期間商品晚了上架、額外自由工作者費用、可能違反消費規範的錯誤規格、商品不符的客訴，或負評。標記哪些實際聽過，哪些仍是假設。", "avoid": "避免沒有顧客描述相關事件，就宣稱有法律或聲譽風險。", "synthetic": true}}, "7d8b0c278ba6aa4b": {"question": "問題有多嚴重？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "嚴重程度告訴產品策略應專注哪裡。嚴重問題值得用範圍窄但有效的解法處理；輕微問題可能連開發都不值得。", "example": "看證據前先定義幾個程度，例如小麻煩、每批耗費幾小時，或阻擋上架。再依每位訪談賣家實際發生的事，而不是一般感受，把他放在對應位置。", "avoid": "避免把差異很大的賣家嚴重程度平均；少數嚴重案例可能最重要。", "synthetic": true}}, "3d4f050b6cb58e52": {"question": "他們為了解決這個問題，已經付出了多少時間或金錢？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在產品策略中，過去為解法付費的情況，顯示顧客已接受哪些事值得花錢，以及你的產品在和什麼競爭。", "example": "列出賣家付費用過的替代方案：商品文案自由工作者、平台批次上傳工具、旺季額外兼職人力。記下每位賣家用過哪個，以及依他自己所述大約花多少。你的範圍應超越他實際使用的選項。", "avoid": "避免忽略試算表與人工投入這些替代方案；手動處理也是解法。", "synthetic": true}}, "b598d6f19d69964c": {"question": "這需要花多少時間？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "時間通常是顧客最先能描述的成本。他自己描述的投入時間，提供任何解法都必須明顯改善的基準。", "example": "問賣家：最近一批新商品，從收到規格到正式上架，準備發布花了多久？如果不確定，就請他回顧那一天。記下他的原話與批次商品數量。", "avoid": "避免問「通常要多久」；把問題放在近期某一批商品上。", "synthetic": true}}, "d6879b8df56b235c": {"question": "這需要花多少錢？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "已花費的金錢，能顯示是否有與問題相關的預算，以及顧客可能考慮的大致價格範圍。", "example": "問賣家：上次商品批次有沒有付錢請人或買工具協助，例如自由工作者、工具，或員工加班？花了多少？如果沒有付費，再問那段時間對他而言值多少。", "avoid": "避免問能接受什麼價格；要問以前實際付過多少。", "synthetic": true}}, "6794c573171c7a30": {"question": "整個過程最痛苦的是哪一步？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "不是每一步都同樣痛苦。最痛苦的一步會告訴你，第一個小解法在哪裡最可能有價值。", "example": "請賣家逐步回顧最近一批上架：蒐集規格、修圖、寫標題、填商店欄位、檢查。再問最希望永遠不用重做哪一步，以及為什麼。記下語氣或說話速度在哪裡改變。", "avoid": "避免把你偏好的步驟當成選項提示；讓顧客從自己的描述中選。", "synthetic": true}}, "ea777e6d7c9699f9": {"question": "誰正在承受這個問題？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "當你能指出哪些真實的人在日常工作中遇到它，想法才成為值得研究的問題。", "example": "寫下你想像會遇到問題的人：晚上獨自上架的賣家，或有兼職幫手的兩人商店。把每種都當成猜測，再規劃這週實際能找誰談。", "avoid": "避免回答所有網路賣家；這麼大的範圍，不會讓你知道能打電話給誰。", "synthetic": true}}, "ac3a5fd90c26aaba": {"question": "哪些人目前正在忍受某種不方便？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "忍受麻煩的人，往往藏著最清楚的早期需求：他們可能已不再抱怨，卻仍花時間繞過問題。", "example": "尋找默默把供應商 PDF 規格重新輸入每個商品頁的賣家，或先跳過缺少欄位，等顧客詢問才補的人。請他展示替代做法，而不是描述有多煩。", "avoid": "避免只計算大聲抱怨的人。反覆替代做法所呈現的安靜忍受，可能比強烈言詞更重要。", "synthetic": true}}, "c505db3d91e280dd": {"question": "哪一類顧客正面對這個問題？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這題與你的優勢及團隊相鄰；及早說清楚顧客，能看出你的長處是否真的能接觸有問題的人。", "example": "假設團隊有人經營過小型網路商店。列出這段經驗能讓你接觸、理解哪些賣家，例如手作商品商店，以及哪些賣家不在其中。", "avoid": "避免只因某個顧客群聽起來很大就選它，團隊卻沒有接觸方法。", "synthetic": true}}, "b943a89a38b14268": {"question": "我能否清楚描述我們的目標顧客？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "如果無法用一兩句描述目標顧客，訪談、接觸與定價決策都會保持模糊。", "example": "測試自己：寫一句話，讓隊友不用問你，就能找到符合條件的賣家。例如沒有設計師、每週上架新商品的店主。如果隊友選出差異很大的人，描述就還不清楚。", "avoid": "避免描述寬鬆到幾乎任何企業主都符合。", "synthetic": true}}, "5ebe606c88ce497a": {"question": "我們的顧客是誰？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在商業模式中，顧客是收入、管道與成本的起點；答案模糊，會削弱其他每個區塊。", "example": "在商業模式草圖中，把顧客定義為實際持有帳號的人，例如自行處理商品頁的小型網路店主。再確認管道與價格區塊是否適用於同一種顧客。", "avoid": "避免把使用者、夥伴與投資人一起列作顧客；他們在模式中各有不同角色。", "synthetic": true}}, "2478e387b014c26c": {"question": "誰正在承受這個問題？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這題把問題連結到具體人物，才能讓問題敘述成為可在對話中測試的內容。", "example": "在問題敘述旁補上實際經歷的人：在上架前準備商品頁的賣家。再寫一個他遇到問題的情境，例如上傳缺少尺寸資料的供應商商品批次。", "avoid": "避免寫沒有對應人物的問題敘述；它無法與任何人的經歷比對。", "synthetic": true}}, "11f7bf08164125b4": {"question": "哪一群顧客最痛？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "不同群體的痛苦程度不同；最痛的群體，通常最願意花時間或金錢處理。", "example": "比較兩群人，例如每月只新增幾件商品的賣家，與每週大量新增商品的賣家。分別記錄上架延遲或不完整時會出什麼事，以及哪群人提到真實後果。", "avoid": "避免用說話多激動判斷痛苦；要看他們描述的近期事件後果。", "synthetic": true}}, "69bb43571965f850": {"question": "哪一群顧客最願意嘗試新的解決方案？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "願意嘗試新事物與痛苦是兩回事；早期採用者，是願意容忍第一版尚不完整的人。", "example": "留意哪些賣家已在嘗試，例如最近幾個月用過新的上架工具或範本。問上次試了什麼、為什麼。近期轉換行為比答應嘗試你的產品更有參考價值。", "avoid": "避免假設最挫折的一群也最願意改變；要查看近期行為。", "synthetic": true}}, "9ddaa1be54db53be": {"question": "我們可能的目標顧客是誰？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在這個階段，仍可能有好幾個候選群體；列出它們，可以避免太早鎖定第一個。", "example": "草擬三種目標群體：平台上的個人賣家、有自家商店的小品牌，以及替客戶上架商品的代理商。把每種標為假設，並註記一種能認識其中幾個人的方式。", "avoid": "避免把第一個猜測當成定案；在證據縮小範圍前，把其他選項留在紙上。", "synthetic": true}}, "de0a664929632505": {"question": "哪些族群最可能受到影響？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "有些群體間接受到影響；梳理受影響者，能看清楚影響實際落在哪裡。", "example": "追蹤一個不完整商品頁：賣家損失時間、買家提出問題、幫手之後修改頁面。列出每個受影響群體，標出誰最直接、最常受到影響。", "avoid": "避免只看到執行任務的人；後續的人可能更強烈承受後果。", "synthetic": true}}, "84f88d2c91b876d8": {"question": "每位訪談對象屬於哪一類顧客？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "混合不同群體的訪談，會讓證據模糊。標記每位受訪者，才能先比較同類，再下結論。", "example": "每次訪談後，替對方標上某個候選群體，例如平台個人賣家或小品牌店主。回顧筆記時，把同群體的訪談放一起讀，看模式在群內是否成立。", "avoid": "避免把所有訪談混成一份摘要。某群體的強烈模式，可能掩蓋其他群體的弱結果。", "synthetic": true}}, "a4f2340aa90fa604": {"question": "目標顧客是否明確？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊分頭訪談前，所有人需要同一定義；否則每個人都會從不同市場收集證據。", "example": "團隊檢查時，請每人說出準備聯繫的兩位對象。如果一人選大型零售商，另一人選週末興趣賣家，定義就還不夠清楚，無法共用。", "avoid": "避免只因定義念出來聽著合理就回答是；要測試隊友是否會選同類型的人。", "synthetic": true}}, "03215e8986aa144b": {"question": "誰真的有這個問題？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "有些人同意問題存在，卻未親身經歷；這題區分真正受影響者與出於禮貌同情的人。", "example": "請賣家展示最近準備的商品頁，以及資料缺漏時做了什麼。真的有問題的人，能指出近期特定的一次操作與採取的步驟。", "avoid": "避免因對方說問題聽起來真實就算入；要找他自己工作中的近期具體事件。", "synthetic": true}}, "1e5dc47411c6f002": {"question": "我們目前的顧客定義是否太廣？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "寬泛定義讓人感覺安全，卻會讓訪談互相矛盾，因為差異很大的人被當成同一種顧客。", "example": "如果定義是任何網路賣家，試著一次加一個條件縮小：販售實體商品、每週上新商品、沒有設計師。看範圍縮小後，訪談答案是否更一致。", "avoid": "避免只為讓市場看起來比證據支持的更大，就保留寬泛定義。", "synthetic": true}}, "bd4911ba4c6bc638": {"question": "哪一群人最常遇到這個問題？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "頻率塑造價值：每週遇到的問題容易形成習慣與預算，一年一次的問題則容易被忽略。", "example": "請各群體的賣家展示最近三次上架，記下日期。比較群體間的時間間隔，而不是要求估計發生頻率。", "avoid": "避免依賴「每週」之類的估計平均值；改問有日期的過去操作。", "synthetic": true}}, "f9a2885002bc29e2": {"question": "哪一群人最急著解決？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "急迫性決定群體現在行動還是延後；即使經常發生，若沒有事情迫使處理，問題仍可能順位很低。", "example": "留意期限：正準備季節促銷的賣家，或平台開始拒絕缺欄位商品頁的賣家。記下哪些群體有真實日期，以及上次錯過時發生什麼。", "avoid": "避免把頻率與急迫性混淆；除了多久發生一次，也問是什麼迫使現在行動。", "synthetic": true}}, "9d00ba17ecd7f0e9": {"question": "我們的早期顧客有哪些角色、產業、組織規模與所處階段？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "具體特徵能把顧客想法變成可搜尋、篩選與招募訪談對象的輪廓。", "example": "把每個特徵當成暫定猜測填寫：角色是自己上架的店主，產業是服飾或家用品，組織規模是一至五人，階段是已經有初次銷售。用這份輪廓選下一批受訪者。", "avoid": "避免因不確定就留白。寫明的猜測能修正，空白則無法修正。", "synthetic": true}}, "745853d418f8e058": {"question": "這位訪談對象是否真的符合我們的理想顧客輪廓？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "團隊檢查", "help": {"why": "訪談不符合輪廓的人，可能讓弱需求看起來很強，因此每份紀錄都應說明對方是否真正符合條件。", "example": "每份訪談紀錄中，逐欄核對：是否自己上架、店裡有多少人、多久新增商品。在閱讀回答前，先標示符合、部分符合或不符合。", "avoid": "避免聽完回答才決定是否符合。依輪廓事實判斷，才不會被熱情影響標籤。", "synthetic": true}}, "e5a344b33ae1ee71": {"question": "訪談後，我們的理想顧客輪廓有哪些改變？為什麼？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由作業指示轉問句）", "audience": "團隊檢查", "help": {"why": "訪談應該改變你的定義；記下改了什麼、為什麼，才能讓輪廓與證據相連，而不是跟著喜好走。", "example": "簡短寫下前後比較：原本是任何小型網路賣家；之後是每週依供應商表格新增商品的賣家。旁邊註明哪些訪談促成改變，以及對方說了或展示了什麼。", "avoid": "避免沒有檢查就說什麼都沒變，也避免沒有訪談依據就改變。", "synthetic": true}}, "b11f38c351374db8": {"question": "我們訪談的朋友是否真的符合理想顧客輪廓？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "朋友容易接觸、回答也較友善，因此要檢查他們是否屬於正在研究的群體。", "example": "如果訪談了一位偶爾在平台販售商品的朋友，把他與輪廓各欄比較。記下符合之處，例如沒有設計師，以及不同之處，例如一年只上架幾件商品。", "avoid": "避免預設朋友就是目標顧客；方便性與善意都可能扭曲結果。", "synthetic": true}}, "773331fa72fd6ba5": {"question": "如果不符合，他們能代表我們的市場嗎？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "不符合輪廓的朋友仍可能讓你學到東西，但他的答案不應代表你準備服務的市場。", "example": "保留朋友的訪談，標記為輪廓之外。用它發現開放問題，例如哪些步驟讓新手困惑；計算多少賣家有此問題時則排除。", "avoid": "避免把不符合輪廓的答案混入計數，也避免在它揭露有用問題時完全丟棄。", "synthetic": true}}, "5051a04dd8250939": {"question": "到底是誰感受到這個痛？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "不同顧客的急迫程度可能非常不同。", "example": "每月上架超過一百件商品、沒有專職設計人員的小型電商賣家。確認這群人是否真的遇到問題。", "avoid": "避免把顧客定義為所有網路賣家。", "synthetic": true}}, "27e979941b618c8d": {"question": "我們第一批顧客是誰？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第一批顧客會影響產品範圍與你收集的證據，因此應是規模小、接觸得到的群體。", "example": "假設選擇每週新增商品的小型服飾店。寫下幾家可以聯繫的店名，以及你要先交付的成果，例如一批完整商品頁。", "avoid": "避免把整個長期市場當作第一批顧客；選擇小到能密切服務的群體。", "synthetic": true}}, "97203e326d7a726f": {"question": "哪一群顧客被忽略了？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "競爭者常追逐同一個顯眼客群，留下未被充分服務的一群；這可能成為你的切入點。", "example": "看看既有上架工具服務誰。如果多數面向有設計人員的大商店，沒有設計師的賣家可能被排除。查看評論與論壇中，這群人是否描述工具過於複雜。", "avoid": "避免未查證就認定某群被忽略；也可能是因為他們不能或不願付費。", "synthetic": true}}, "038f7d6ca8ed98bf": {"question": "誰擁有採購或使用解決方案的決定權？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "即使問題很痛，如果感受到的人沒有採用解法的決定權，問題仍會無解。", "example": "小商店中，修改商品頁的幫手可能最痛苦，但新工具由店主核准。問店裡上次開始用新 App 或服務，是誰同意的。", "avoid": "避免假設描述痛苦的人能批准採購。", "synthetic": true}}, "e60ee8ef921f0da4": {"question": "誰使用這項產品？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在商業模式中，使用者決定產品每天必須完成什麼，即使核准的人是別人。", "example": "上架服務的使用者，可能是上傳商品資料並檢查結果的人，例如兼職助理。描述他接觸產品的各個時刻，以及每個時刻需要什麼。", "avoid": "避免預設買方就是使用者；日常操作者可能另有其人。", "synthetic": true}}, "fcdb7b983b5e37a3": {"question": "誰為它付費？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "實際做事的人不一定掌握預算。", "example": "商店助理準備商品頁，但軟體支出可能由店主核准。向店家確認這件事。", "avoid": "避免假設使用者也掌握預算。", "synthetic": true}}, "fb6c639e6ccc4b7d": {"question": "誰做採購決策？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "商業模式取決於誰核准，因為銷售投入、訊息與定價都要面向那個人。", "example": "小品牌可能由創辦人核准每月軟體費，經理負責研究選項。畫出誰提議、誰核准、誰可能阻止採購，再與上次購買工具的過程核對。", "avoid": "避免假設會議中最興奮的人就是決策者。", "synthetic": true}}, "91780aff792e3fee": {"question": "誰使用、誰付費、誰擁有採購決策權？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "及早區分三個角色，才能看出提案、導入與定價是否面向正確的人。", "example": "替上架服務畫三欄：誰使用、誰付款、誰控制採購。某家店可能把助理放第一欄，店主放第二、三欄。每欄下面寫一個待釐清的問題。", "avoid": "避免還沒向真實企業確認，就把三欄都填上同一個名字。", "synthetic": true}}, "cf25a2c2de15c97e": {"question": "使用者、付款者與決策者是否是同一人？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "三個角色是同一人時，銷售較簡單；不同人時，就需要經過每一個人的方法。", "example": "團隊檢查時，標記每家訪談商店：三個角色同一人，還是分開。個人賣家通常兼三職，有員工的店可能分開。選擇銷售方式前，先分別計數。", "avoid": "避免假設每位顧客都像第一位受訪者；角色分工可能隨店家規模改變。", "synthetic": true}}, "5a733eda50f0b47f": {"question": "是否使用者有需求，但付費者不願付款？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "如果付費者看不出花錢的理由，使用者再喜歡產品也無法挽救銷售。", "example": "助理可能想更快上架，但店主認為助理工時本來就已付薪。問店主上架延遲造成什麼代價，留意他在乎的後果，例如新品上市太晚。", "avoid": "避免把使用者熱情當作付款意圖；付費者需要自己的付費理由。", "synthetic": true}}, "5a8dba480f5670e9": {"question": "誰是使用者？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "使用者是日常工作會改變的人，因此他的工作流程決定產品實際必須處理什麼。", "example": "問賣家是誰坐下來準備商品上架資料，並觀察那個人實際做一次。記錄他開啟哪些檔案、填哪些欄位，以及在哪裡停下來搜尋缺漏資訊。", "avoid": "避免只用職稱描述使用者；描述他執行任務時做什麼。", "synthetic": true}}, "744776a1444f3006": {"question": "誰是付費者？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "付款者對價值的看法決定價格上限，而且可能取決於使用者看不到的成果。", "example": "問商店上次訂閱軟體，是用誰的卡或帳戶付款。若是店主，問什麼讓那次購買值得，並用他的原話記錄理由。", "avoid": "避免假設付款者與使用者一樣重視省下的時間。", "synthetic": true}}, "52f05456c77f9480": {"question": "誰是決策者？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "決策者能核准或阻止購買，因此需要知道他答應前要看到哪些證據。", "example": "問商店當初如何選擇目前的電商平台或上架範本。記錄誰比較選項、誰做最後決定，以及什麼說服了他。過往經驗能顯示下次可能如何決策。", "avoid": "避免問理論上誰會決定；問上次真實決策如何做成。", "synthetic": true}}, "21e2090e527fe548": {"question": "誰會影響或阻擋這項決策？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（由學習單欄位轉問句）", "audience": "團隊／個人自問", "help": {"why": "沒有正式權限的人仍可能延後或阻擋購買，忽略他們會讓交易出乎意料地停滯。", "example": "小品牌的接案攝影師或管理電商帳號的人，都可能反對新流程。問上次商店更換工具時，需要誰的意見，以及事後誰曾抱怨。", "avoid": "避免只列正式核准者；非正式影響者也可能默默阻止採用。", "synthetic": true}}, "1d7eceaa221b4ce5": {"question": "顧客是否有預算？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "真實需求若沒有可用預算，往往只會變成禮貌的興趣，始終不會購買。", "example": "問商店目前為上架工作花什麼資源：接案者、付費範本或員工工時。既有支出能顯示預算可能從哪裡來。記錄對方提供的實際金額，不是他說可能願付多少。", "avoid": "避免問是否願意付費；問目前為這項工作已花多少。", "synthetic": true}}, "b8602039d0d2a834": {"question": "顧客是否有決策權？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "與沒有權限的人交談，可能獲得鼓舞卻沒有結果，因此要確認誰能做出承諾。", "example": "問受訪者能否自行開始付費試行。若他說要先問別人，就問是誰，以及下次能否邀請那人一起參與。", "avoid": "避免以為聽起來資深的職稱就有購買權；直接問核准流程。", "synthetic": true}}, "3633aa0bb2342acd": {"question": "他們必須遵循什麼採購流程？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "採購步驟會增加時間與要求，提早了解，才不會在顧客願意卻無法實際購買時措手不及。", "example": "個人賣家可能當天刷卡，稍大的品牌卻可能需要發票或會計核准。請對方回顧上次工具採購如何核准、如何付款。", "avoid": "避免假設小企業沒有流程；即使簡短步驟也可能延後或阻擋付款。", "synthetic": true}}, "398e7d13f0c50f5d": {"question": "誰決定、誰付錢？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由訪談流程轉問句）", "audience": "直接問顧客", "help": {"why": "在訪談中詢問，能從顧客自己的敘述取得角色分工，而不是依賴團隊假設。", "example": "接近結束時問：上次商店為工具或服務付款，是誰提議、誰核准、誰付錢？留意真實過往事件中的人名與步驟，而不是假設性回答。", "avoid": "避免問誰會決定購買我們的產品。人們會猜未來；應問過去的採購。", "synthetic": true}}, "ac35e3d4dc175499": {"question": "我們能否辨認使用者與付費者？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "若訪談筆記分不出使用者與付款者，後續定價與銷售決策就會建立在混雜的訊號上。", "example": "逐份檢查訪談紀錄，是否寫出誰使用成果、誰付款。若筆記只寫「賣家」，回頭釐清商店裡是哪個人扮演各角色。", "avoid": "避免用「顧客」一個詞把角色混在一起；分別記錄各角色。", "synthetic": true}}, "4177c510cdbe6a08": {"question": "顧客目前如何處理這個問題？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客已經用某種方式處理問題，既有做法才是你的構想必須勝過的真正競爭對手。", "example": "列出你猜測的做法：複製供應商試算表中的規格、按批請接案者處理，或讓欄位空白。每項標成猜測，規劃透過觀察賣家準備上架資料來確認。", "avoid": "避免回答顧客什麼都沒做。多數人已有替代做法，即使很雜亂。", "synthetic": true}}, "120e89d9e882ad1e": {"question": "現有解法為什麼不夠好？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "若說不清既有解法的不足，就無法說明為何有人會換成你的解法。", "example": "用賣家說需要的條件比較現有選項：範本可能快但仍會漏欄位；接案者可能準確卻難排時間。把每項不足寫成要在訪談確認的事情。", "avoid": "避免沒有顧客證據，就列出只有團隊在意的不足，例如介面過時。", "synthetic": true}}, "6f549db26704b2f1": {"question": "他們為什麼要改變目前的使用習慣？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "即使沒效率，習慣也很難改，因此新解法需要足夠強的理由打破慣例。", "example": "問賣家上次更換上架準備方式時，發生什麼改變，例如平台新規則或旺季。過去的觸發事件能顯示什麼事情會促使他改變。", "avoid": "避免認為產品更好就足以讓人轉換；找出打破習慣的觸發事件。", "synthetic": true}}, "4872f2ae71d20200": {"question": "現有解法有什麼不足？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "現有選項中的具體不足，能顯示團隊強項在哪裡有用，而不必同時在所有地方競爭。", "example": "觀察賣家使用既有上架工具後，仍要手動做什麼，例如對照供應商檔案確認尺寸。這個剩下的人工步驟可能值得研究。", "avoid": "避免只列缺少的功能，卻沒確認顧客是否真的注意到，並為它採取替代做法。", "synthetic": true}}, "1fe25efa71ff1bac": {"question": "為什麼現有解法仍然不足？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這題位於問題與解法部分，回答應把具體不足連到提出的解法。", "example": "對每種既有選項，用一句話把不足連到構想：接案者很難約到，因此在指定時間內交付一批整理好的資料可能有價值。每個連結都標成待確認的假設。", "avoid": "避免描述自己的解法並未處理的不足；兩者連結必須明確。", "synthetic": true}}, "777fd88db3c447a6": {"question": "顧客目前使用哪些替代方案？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "替代方案不只直接競爭者；試算表、接案者與員工時間都在競爭同一份工作。", "example": "清單也納入非軟體選項：店主深夜自己做、家人幫忙、接案平台找到的人、電商平台內建範本。問受訪者最近一次用了哪一種。", "avoid": "避免只列軟體產品；人工工作與雇人協助也是替代方案。", "synthetic": true}}, "2c19bbcb5ff021f6": {"question": "目前有哪些競爭者？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "了解既有競爭者，才能知道顧客已把你與誰比較，以及你在哪裡必須不同。", "example": "到賣家尋求協助的地方搜尋：電商平台的應用商店、賣家論壇、接案網站。列出聲稱能準備上架資料的產品與服務，註明各自針對誰。", "avoid": "避免說沒有競爭者；若問題真實存在，已有人或某種做法在處理。", "synthetic": true}}, "1fbc689f80dcff0c": {"question": "顧客為什麼沒有採用現有產品？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "既有產品採用率低，可能揭露成本、設定心力或信任等障礙，這些也可能阻礙你的產品。", "example": "問賣家是否聽過某個既有上架工具，以及為什麼不用。記錄具體原因，例如設定太久，或產出仍需大幅修改。", "avoid": "避免假設對方不知道產品存在；很多時候他知道，只是決定不用。", "synthetic": true}}, "17daf7cf528972e5": {"question": "顧客現在怎麼解決？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "假設應在顧客情境中描述目前解法，因為這決定產品必須跨越的標準。", "example": "把目前解法寫成假設卡：我們認為小型服飾賣家依供應商試算表填入商品資料，買家問了才修正錯誤。再註明哪些證據會支持或反駁這張卡。", "avoid": "避免在任何訪談之前，就把對既有解法的假設寫成確定事實。", "synthetic": true}}, "957b302a6d7fb9fd": {"question": "現在的替代方式是否已經夠用？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "若目前替代方案已夠用，無論你的產品多好，顧客都沒什麼理由轉換。", "example": "問賣家對現有做法的成果有多滿意，以及付出多少時間。若他聳肩說用得不錯，就誠實記錄，作為重新考慮的理由。", "avoid": "避免忽略「已經夠用」的回答；這是問題可能不值得解決的重要證據。", "synthetic": true}}, "79ba5c708b00a0a0": {"question": "顧客對目前替代方案最不滿意的地方是什麼？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（由學習單轉問句）", "audience": "團隊／個人自問", "help": {"why": "最不喜歡的部分，指向顧客最重視的改變，也指出解法應優先專注哪裡。", "example": "請賣家回想最近一次現有做法讓他挫折的經過。有人可能描述重新檢查每個尺寸欄位，有人可能描述等待接案者。記錄事件，而不只是感受。", "avoid": "避免依自己的優先順序排列不滿；用顧客近期事件判斷。", "synthetic": true}}, "a97ce48b2741d97b": {"question": "可以描述目前的處理流程嗎？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "描述流程會揭露步驟、工具與延誤，這些可能在直接問問題時不會被提到。", "example": "請賣家從頭到尾回顧最近一次上架：商品資訊從哪來、開了哪些工具、在哪裡卡住。可以的話，請他展示檔案。", "avoid": "避免讓對方描述理想流程；問最近一次真實經驗。", "synthetic": true}}, "b42a40ac4d672cf7": {"question": "你有嘗試過哪些其他方法？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由訪談流程轉問句）", "audience": "直接問顧客", "help": {"why": "過往嘗試顯示顧客已為解決問題投入多少心力，從而反映問題有多重要。", "example": "問：「準備上架資料時，你還試過什麼？」留意具體名稱、免費或付費，以及每種用了多久。試過兩個工具與一位接案者的賣家，比什麼都沒試的人更投入。", "avoid": "避免先列選項讓對方回應；讓他自己說出實際試過什麼。", "synthetic": true}}, "4df17a308cddcf5d": {"question": "你為什麼停止使用某個替代方案？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由訪談流程轉問句）", "audience": "直接問顧客", "help": {"why": "放棄替代方案的原因是警訊；同樣原因可能讓顧客放棄你的產品。", "example": "賣家提到停用工具時，問停止前最後幾週發生什麼。留意具體事件，例如漲價，或上架資料仍需手動修正。", "avoid": "避免接受「不好用」這類模糊原因；追問具體發生了什麼。", "synthetic": true}}, "8f53ab2aefc0da2f": {"question": "使用者現在怎麼解決？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在產品策略中，使用者現有做法就是產品範圍必須改善的起點。", "example": "畫出使用者為一筆商品執行的步驟：蒐集供應商資料、寫標題、修照片、填規格。標出首版會取代哪些步驟，以及哪些仍由使用者手動完成。", "avoid": "避免以使用者目前根本不做的步驟來規劃產品範圍。", "synthetic": true}}, "98849ff06e220da6": {"question": "他們目前怎麼解決這個問題？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "了解目前解法，才能定義可衡量的結果，例如減少修正次數，而不是籠統地說改善。", "example": "選目前做法中一項可測量的部分，例如賣家發布後修正多少欄位。先記錄幾筆現有商品，之後才能與你的解法成果比較。", "avoid": "避免還沒記錄現有做法實際產出什麼，就承諾改善。", "synthetic": true}}, "0b4ca2718a6bf41c": {"question": "你現在怎麼解決？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "直接問顧客，才能取得實際做法，往往與團隊想像不同。", "example": "問：「上次在商店新增商品時，你怎麼把詳細資料放到頁面上？」留意具體工具、人與步驟，若手邊有範例，請他展示。", "avoid": "避免問想要怎麼解決；問上次實際怎麼做。", "synthetic": true}}, "eff9448d799af913": {"question": "競爭對手的使用者最常抱怨什麼？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "對競爭者反覆出現的抱怨，顯示未被滿足的需求；多位使用者重複提到的不足值得研究。", "example": "閱讀上架工具的公開評論與賣家論壇討論。記錄哪些抱怨反覆出現，例如匯入後欄位缺漏、支援太慢，並註明每位發言者的賣家類型。", "avoid": "避免把一則憤怒評論當成模式；找跨使用者重複出現的抱怨。", "synthetic": true}}, "f85f607835c5cb3a": {"question": "哪個流程很麻煩？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "既有工具中的繁瑣流程，可能是實際可切入之處，因為使用者已經感受到不便。", "example": "觀察賣家使用現有上架工具，計算哪些步驟反覆執行或重做，例如逐張調整照片尺寸。記錄他何時嘆氣或切換視窗，這些時刻指出流程繁瑣之處。", "avoid": "避免只看截圖就判斷流程；觀察有人用工具完成真實任務。", "synthetic": true}}, "7a95d14d0aee396b": {"question": "哪個功能顧客一直要求，但競爭對手沒解決？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客一直要求、競爭者卻忽略的功能，可能代表機會，也可能是難以滿足的要求。", "example": "從賣家論壇與訪談蒐集功能要求，例如上傳前依平台規則檢查商品資料。記錄各要求出現頻率、來自哪種賣家，以及是否有既有工具提供。", "avoid": "避免每個被要求的功能都做；先查競爭者為什麼略過，不要直接假設只是沒想到。", "synthetic": true}}, "ed2b1c1bc430cca9": {"question": "我們的競爭對手是誰？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "提案需要清楚呈現競爭者，讓聽眾了解顧客會拿你與誰比較，以及差異在哪。", "example": "在提案中，將競爭者分成直接工具、接案者等外聘協助、自己手動做。每組寫出一項想提供的差異，並標示為待測試的主張。", "avoid": "避免簡報聲稱沒有競爭，也避免只比功能而忽略人工替代方案。", "synthetic": true}}, "6c8718cdf838d14b": {"question": "有多少人面對這個問題？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "面對問題的人數，決定這項創業構想能靠這個問題成長到多大。", "example": "從明確群體估算：假設你計算某個平台上每月新增商品的小型賣家。寫下計數方法與來源，並標明這是仍待修正的估計。", "avoid": "避免直接引用所有網路賣家的巨大總數，卻不解釋如何計算。", "synthetic": true}}, "393b367e23fd10a1": {"question": "為什麼是現在？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "投資人與團隊需要知道最近改變了什麼，讓現在而不是五年前成為合適時機。", "example": "尋找影響示範構想的近期變化：平台加嚴商品頁要求，或工具讓圖片與文字準備更便宜。解釋每項變化如何讓問題更急迫，或解法更可行。", "avoid": "避免只說市場正在成長之類的一般答案；指出具體的近期變化。", "synthetic": true}}, "fe5d25a03724da1d": {"question": "市場規模有多大？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "市場規模幫助你與聽者判斷，這個機會能否支持你想建立的事業。", "example": "由下往上估算：可計數的目標賣家數，乘以準備測試的價格，再乘以實際可能的購買頻率。列出每項輸入，標明哪些是假設。", "avoid": "避免引用巨大的整體產業數字，卻沒有連到你的特定顧客。", "synthetic": true}}, "d6272fa86d4cbd9b": {"question": "這個市場有哪些成長潛力與未來發展機會？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "成長潛力呈現市場是否會擴大，以及服務第一批顧客後，事業還能走向哪裡。", "example": "描述示範構想可能的下一步：從小型服飾賣家拓展到其他商品類別，或從商品頁延伸到其他商店內容。把每項標為未來選項，不是已經在執行的計畫。", "avoid": "避免把未來擴張說成必然；說明哪些初步成果必須先發生。", "synthetic": true}}, "6cc224fa11d82d12": {"question": "假設六個月後，一個資金更多、技術更強的團隊開始做相同產品，我們還剩下什麼優勢？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "資金與工程能力可能被複製；這題迫使你找出更強團隊也難以輕易複製的東西。", "example": "假設較大團隊做出相同上架工具，你仍可能擁有與一群賣家的密切關係，或服務他們時累積的供應商格式知識。寫出你將擁有什麼，以及如何確認。", "avoid": "避免只回答動作更快或更努力；那不是持續的優勢。", "synthetic": true}}, "28d9fefc459f2aad": {"question": "哪些網路效應能讓事業隨著成長而更有價值？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "網路效應讓更多人使用時，產品變得更有價值，長期可能保護事業。", "example": "以示範構想思考：每位新賣家的供應商檔案，能否改善之後的商品頁準備？供應商是否會為了服務許多賣家而加入？把每項標成待確認的可能性，而不是功能。", "avoid": "避免使用者變多只是營收增加，就宣稱有網路效應；要說明每位使用者得到的價值如何成長。", "synthetic": true}}, "69bda11b26d0debc": {"question": "什麼會讓顧客難以轉換到其他方案？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "轉換成本能在競爭者出現時留住顧客，但應來自已交付的價值，而不是綁住顧客的手段。", "example": "假設賣家把商品範本、供應商對應設定與上架紀錄存於服務。久了，換工具就需要重建這些設定。記下賣家會真正捨不得哪些內容。", "avoid": "避免依賴合約或阻擋資料匯出；不是基於價值的轉換成本會讓顧客反感。", "synthetic": true}}, "73d93b2d48af922f": {"question": "我們是否能形成難以被取代的優勢？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "缺少保護能力的事業，一旦顯露潛力就容易被快速複製，限制早期投入能帶來多久回報。", "example": "列出上架服務可能的保護來源，例如累積資料或賣家關係。逐項描述一年後必須出現什麼情況，才能保護你，以及如何確認。", "avoid": "避免沒有具體說明就回答可以；難以被取代的能力需要具體來源。", "synthetic": true}}, "a4b4e7355ab76ecf": {"question": "我們可以透過技術、資料、品牌、通路、法規或供應鏈，建立哪些優勢？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "逐一檢查各種來源，有助於找出實際可建立的優勢，而不是宣稱什麼都有一點優勢。", "example": "逐項檢查示範構想的來源：多種供應商格式資料、小型賣家信任的品牌、平台夥伴提供的通路。標記哪些能在一年內建立，哪些不太可能。", "avoid": "避免一次宣稱六種來源都有；選真正能建立的一至兩項。", "synthetic": true}}, "bae585a71c64afc2": {"question": "這個團隊有哪些能力與優勢，能推動這項創業構想？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在提案中，聽者想知道為什麼特別是這個團隊，有能力執行所描述的計畫。", "example": "為示範構想的創辦團隊列出具體能力：一人管理過小店的商品頁，另一人會開發資料工具。把每項能力連到它能完成的特定計畫部分。", "avoid": "避免列出亮眼職稱或學校，卻沒有連到這個事業需要的工作。", "synthetic": true}}, "6a168fa8943c7d08": {"question": "到目前為止，我們觀察到了什麼？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "觀察是後續每項主張的原料。列出實際看到的事，才能讓早期討論立足於事件，而不是意見。", "example": "只寫團隊有人親眼見過的事：賣家從供應商 PDF 重新輸入商品規格，或因缺照片而暫停上架。記下誰、何時、在哪裡看見。把解讀放另一欄。", "avoid": "避免把預期賣家會經歷的事，寫得像團隊已經親眼看過。", "synthetic": true}}, "a69cf1ed4ecd6452": {"question": "我們有哪些初步證據？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "初步證據不必很強，但必須存在。說出它，才能看出計畫有多少依據來自團隊之外。", "example": "初步證據可能是三份賣家對話筆記、賣家論壇討論缺欄位的截圖，或你替朋友商店準備商品頁的紀錄。每項標上來源與日期，方便判斷分量。", "avoid": "避免把朋友的熱情，或想法看似理所當然，算作初步證據。", "synthetic": true}}, "fd146da1df1a8021": {"question": "哪些部分已經獲得確認？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "把已確認部分與其他部分分開，才能知道哪裡能有些信心地繼續，哪裡仍在猜測。", "example": "逐一查看 canvas；只有具體來源支持時，才標為已確認。例如兩位賣家展示規格欄空白的上架試算表，問題描述對該群體可能已確認；付費意願則可能仍未確定。", "avoid": "避免只因團隊同意，或尚無人質疑，就把某部分標為已確認。", "synthetic": true}}, "ac6dd356b74a242b": {"question": "顧客說了什麼？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客說的話揭露了他的用語、優先順序與挫折。這是有用資訊，但必須與實際行動分開。", "example": "每次對話後，把賣家自己的說法抄進筆記，例如他如何描述商品上架前一晚。依主題分組，標示哪些是在描述過去事件，哪些是對未來的意見。", "avoid": "避免把顧客的話改寫成你的產品詞彙，也避免把禮貌稱讚當成需求訊號。", "synthetic": true}}, "957565ea0ab44281": {"question": "顧客過去實際做了什麼？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "過去行動花費顧客的時間或金錢，因此比口頭偏好或未來行為預測，更可靠地揭露真正優先順序。", "example": "記錄行動，例如賣家上個月聘請自由工作者修商品照片，或自製規格範本。請看實際產物：帳單、試算表、訊息串。記下發生時間與花費的努力。", "avoid": "避免用顧客說將來會做什麼，取代已經做過的事。", "synthetic": true}}, "a9f19a758281c277": {"question": "有哪些證據支持我們的假設？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "每個假設都應指向背後證據。沒有支持的假設，是計畫最容易出問題的地方。", "example": "做兩欄。左邊寫假設，例如「賣家分批上架商品」；右邊列具體支持來源，例如賣家展示的上架行事曆。如果目前沒有支持，右欄就留白。", "avoid": "避免為了讓 canvas 看似完整，就把同一份證據放到每個假設下面。", "synthetic": true}}, "135d08f951fa894d": {"question": "有哪些證據反對我們的假設？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "相反證據可以防止把大量成本花在錯誤問題上。", "example": "訪談可能發現，賣家其實只花幾分鐘做這項任務。如果有觀察到，就把這段敘述與支持證據一起保留。", "avoid": "避免只保留支持自己想法的證據。", "synthetic": true}}, "abb0268362589e16": {"question": "資料來自政府資料、學術研究、產業報告，還是匿名文章？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "不同來源的可靠程度差異很大。知道數字從哪裡來，才知道它在決策中能承擔多少分量。", "example": "假設找到小型網路商店使用多個平台的比例。往回追溯：來自統計機關、同儕審查論文、供應商產業報告，還是匿名部落格？把原始來源記在數字旁。", "avoid": "避免沒找到並註明原始來源，就重複二手文章中的數字。", "synthetic": true}}, "0d74bf7f958f254d": {"question": "資料是否仍符合目前市場狀況？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "市場變化很快。舊資訊描述的平台、工具或賣家習慣，可能已不適用於正在研究的顧客。", "example": "檢查每份來源的發表日期。如果網路賣家工具報告早於平台上架規則重大變動，或 AI 寫作工具普及，就只把它當背景資料，再找較新的賣家對話。", "avoid": "避免只因來源知名就依賴它，卻不查資料何時收集。", "synthetic": true}}, "96f5b09c9ce718ce": {"question": "資料是否與我們實際的目標顧客相關？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "廣泛市場的資料，不一定能描述你準備服務的特定顧客。相關性與可靠性同樣重要。", "example": "關於擁有內部設計團隊的大型網路零售商報告，對靠試算表上架的兩人商店說明有限。使用來源前，確認它是否涵蓋你目標的規模、地區與平台。", "avoid": "避免把大型企業或其他地區的發現，直接套用到沒有專職設計師的小型賣家。", "synthetic": true}}, "9a9f495d2849527d": {"question": "真實顧客訪談能否支持這項主張？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "案頭研究可以指出模式，訪談則顯示模式是否出現在顧客的真實工作中。兩者應指向相同方向。", "example": "如果報告指出小型賣家在商品照片上有困難，就規劃訪談確認。請幾位賣家帶你回顧最近一次上架，看照片問題是否未經提示就出現。記下哪些訪談支持主張，哪些不支持。", "avoid": "避免只因文章提過，就把主張當定論，卻沒聽顧客說過。", "synthetic": true}}, "75402a460af0f714": {"question": "哪些敘述是事實，哪些只是推測？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "事實與推測在投影片上看起來一樣。標示後，團隊才知道決策哪裡依據觀察、哪裡依據猜測。", "example": "逐句閱讀問題敘述並標記。「我們訪談的一位賣家，因供應商規格太晚到而延遲上架」是單一事件的事實；「多數小型賣家每週都遇到」則在蒐集更多案例前仍是推測。", "avoid": "避免刪掉誰在何時說過，就把單一訪談升級成一般事實。", "synthetic": true}}, "d8f7160ba3eb3c00": {"question": "這個分析最可能錯在哪裡？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "（由教材指令轉問句）", "audience": "團隊／個人自問", "help": {"why": "每份分析都有弱點。及早指出最可能出錯處，才能知道投入更多時間或金錢前應先看哪裡。", "example": "回顧分析，問哪個環節支持最少。以上架構想為例，可能問題真實存在，但賣家能靠範本便宜解決。把它寫成最可能的錯誤，並規劃確認。", "avoid": "避免用競爭或資金等一般風險回答，卻不指出最可能錯誤的具體環節。", "synthetic": true}}, "ed7e15be98460a02": {"question": "有哪些證據會推翻這個假設？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "無法推翻的假設，無法引導決策。事先定義相反證據，才能在結果出現時保持誠實。", "example": "對「賣家花大量時間補缺少欄位」這個假設，先決定什麼會算反對證據。僅作示例：如果多數受訪賣家說任務很快，且想不起近期問題，就視為假設被削弱。", "avoid": "避免把推翻條件定得太窄，讓任何實際可能結果都無法反駁假設。", "synthetic": true}}, "03e965ce974d6447": {"question": "不願購買的顧客會如何反駁我們的論點？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "（由教材指令轉問句）", "audience": "團隊／個人自問", "help": {"why": "不會購買的顧客，能揭露團隊常忽略的反對理由。站在他們角度反駁，可以在市場之前先發現弱點。", "example": "扮演一位拒絕的賣家。他可能說平台已有缺欄位提示，或姪子免費幫忙上架。寫下每個反對理由，並確認真實賣家在訪談中是否也提出。", "avoid": "避免編造容易回答的弱反對理由，而不是賣家可能拒絕的最強理由。", "synthetic": true}}, "dd3faa18a5846f2e": {"question": "這個結論還需要哪些真實資料才能成立？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "結論的可靠程度受缺少資料限制。列出仍需要的資料，能把模糊擔心變成具體研究任務。", "example": "如果結論是賣家願意為商品頁準備付費，列出仍缺什麼：多久上架一次、現在花多少、誰批准支出。每個缺項旁寫取得方法，例如請對方展示近期帳單。", "avoid": "避免結論依賴的資料還在待收集清單，就把結論視為已準備好。", "synthetic": true}}, "4b813516f2b929b1": {"question": "團隊是否已經有初步證據？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這是快速確認團隊從觀察還是信念出發，也能調整對後續驗證工作量的期待。", "example": "請每位成員指出一項自己收集的證據，例如賣家對話或協助準備的商品頁。如果沒有人能說出，就誠實記錄，先安排第一個收集證據步驟，再分其他工作。", "avoid": "避免只因成員有個人意見或尚未向賣家查證的產業經驗，就回答有證據。", "synthetic": true}}, "f89dcd86c7db723c": {"question": "哪些部分已經有證據？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "canvas 各處的證據通常不平均。看清哪些部分有支持，才能決定接下來把努力放在哪裡。", "example": "依序查看問題、顧客、市場與解法。以上架構想為例，問題區可能有賣家對話筆記，定價卻沒有資料。標成有證據、部分證據或沒有證據，並為每個標記附來源。", "avoid": "避免把一份強證據延伸到所有區塊，讓整張 canvas 看似都有支持。", "synthetic": true}}, "51fbd5f0ec70d1d5": {"question": "這次訪談支持了哪些假設？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "團隊檢查", "help": {"why": "把每次訪談連到特定假設，才能看出對話實際教會你什麼，而不只剩一般印象。", "example": "訪談後列出觸及的假設。如果賣家展示每週手動貼入供應商規格的試算表，就註記它支持反覆人工工作的假設，並引用支持它的那個時刻。", "avoid": "避免因賣家同意了你替他說出的描述，就把假設標為獲得支持。", "synthetic": true}}, "01be1810fb135761": {"question": "這次訪談推翻了哪些假設？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "團隊檢查", "help": {"why": "反駁假設的訪談往往最有價值。明確記錄，能防止團隊悄悄忽略不方便的結果。", "example": "如果賣家說供應商資料總是完整，真正延誤在攝影，就註記它反駁缺欄位假設。記下原話與描述的事件，與支持假設的訪談放在一起。", "avoid": "避免尚未確認其他人是否也如此，就把相反訪談解釋成不尋常顧客。", "synthetic": true}}, "931f9cc3f2d9dcbf": {"question": "顧客是否已投入人力、軟體、顧問或其他解決方案？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "既有投入表示問題已重要到值得花錢或時間，也顯示顧客會拿什麼與你比較。", "example": "問賣家目前用什麼準備商品頁。一人可能按批付錢請自由工作者，一人用試算表範本，另一人有兼職助理。記下費用或花費時數。", "avoid": "避免認為現在沒有支出就代表市場空白；也可能是問題不夠重要。", "synthetic": true}}, "4ef98f7eefbe2dfd": {"question": "有什麼證據證明問題存在？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "產品策略取決於真實問題。決定範圍前，團隊應能指出證據，而不只是有說服力地描述問題。", "example": "收集具體痕跡：缺欄位被拒的商品頁截圖、賣家向供應商索取規格的訊息，或觀察賣家準備批次的筆記。每項都應呈現問題在某個特定商家、某一天發生。", "avoid": "避免用清楚的問題敘述或巨大市場估計，代替問題實際發生的證據。", "synthetic": true}}, "d857cf05504426a2": {"question": "我們已經和顧客談過了嗎？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在構想階段，與顧客交談是最快確認想像中的問題是否符合真實工作方式的方法。", "example": "計算你真正與小型賣家談過如何準備商品頁的次數。如果曾在市集與店主閒聊並問到流程，也可以算。記下次數與時間，即使答案是零。", "avoid": "避免把推銷想法並詢問意見的對話，算成顧客探索。", "synthetic": true}}, "204259bb3e9fd18a": {"question": "我們訪談過哪些人？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "知道確切訪談了誰，才能看出證據來自目標顧客，還是只是容易接觸的人。", "example": "保留簡單名單：商家類型、規模、平台、對話者與日期。例如在一個平台販售家用品的兩人商店，與店主訪談。檢查名單是否符合已定義的顧客。", "avoid": "避免只概括「幾位賣家」，卻沒記下是誰、是否符合目標顧客。", "synthetic": true}}, "b953397f4ecc9d37": {"question": "我們是否需要再次聯繫他們？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第二次對話可以補資料、確認改變，或推進測試。刻意做決定，能讓關係持續有用，而不是靠偶然。", "example": "檢查每次訪談還有哪些未解問題。如果賣家提到供應商規格表，但你沒看過，就詢問能否跟進查看下一份。如果對方適合計畫中的試行，就記下以便之後聯繫。", "avoid": "避免沒有個別跟進理由，就預設全部再聯繫或全部不聯繫。", "synthetic": true}}, "b4ef6de4242ce05b": {"question": "我們能否快速取得顧客回饋？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "快速回饋讓團隊以天而不是月學習。接觸顧客速度慢，是值得及早知道的限制。", "example": "列出這週可用的管道：自己加入的賣家社群、平常購買的商店，或在網路販售的親戚。估計每個管道可能帶來多少回覆，以及安排對話要多久。", "avoid": "避免只因顧客群很大就假設容易接觸，卻沒有測試真實管道。", "synthetic": true}}, "6efb4a1b85f47b9f": {"question": "團隊是否願意很快接觸顧客？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "如果沒有人願意打電話，依賴訪談的計畫就會失敗。意願是應公開說明的團隊事實。", "example": "問每個人這週是否準備好傳訊息給賣家，以及要聯繫幾位。如果有人不安，第一次通話可以與隊友搭配，或先負責筆記。", "avoid": "避免口頭原則上同意，卻一直等產品或提案更成熟才開始接觸。", "synthetic": true}}, "569b3e4f46cca454": {"question": "我們第一批要訪談的顧客是誰？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第一批訪談會塑造早期結論。刻意選擇對象，才能讓結論關於目標顧客，而不只是關於有回覆的人。", "example": "列出具體人物或商家：認識的小服飾店主、本地平台社群裡兩位賣家、最近推出新商品的商店。預約前逐一核對顧客定義。", "avoid": "避免只因方便就從親友開始，卻不確認他們是否符合目標顧客。", "synthetic": true}}, "26f6a3fbed82c0d0": {"question": "我們第一批要訪談幾位顧客？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "目標人數讓計畫具體，也告訴團隊何時停下回顧，而不是無限訪談。", "example": "僅作示例：事先決定第一次回顧前要訪談多少位合適賣家，以及要跨訪談尋找什麼。選擇團隊能在可用時間完成的人數，之後再重新評估。", "avoid": "避免為了感覺完整而選很大人數，團隊卻無法在下一次決策前實際完成。", "synthetic": true}}, "c1389e5422fff5f7": {"question": "由誰負責聯繫他們？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "沒有負責人的接觸工作通常不會發生。指定一個人，才能把聯繫變成承諾，而不是共同意願。", "example": "把訪談名單中的每個對象，分配給一位隊友，負責第一封訊息、安排通話與之後確認。例如一位創辦人聯繫平台社群，另一位聯繫平常購買的商店。", "avoid": "避免把負責人寫成「團隊」，讓每個人都以為別人會聯繫。", "synthetic": true}}, "cddeaea851820ba4": {"question": "何時完成訪談？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "完成日期把訪談變成排定的步驟，也決定團隊何時開會回顧所學。", "example": "選定第一輪訪談全部完成與回顧會議的日期。假設團隊有兩週，現在就安排回顧，並在中途檢查多少位賣家已確認時間。", "avoid": "避免等訪談夠多才決定日期；這通常讓回顧永遠不發生。", "synthetic": true}}, "0cb5a85af1ed10b8": {"question": "我們要如何整理結果？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "分散在不同人腦中、格式不一的筆記很難比較。先同意結構，才能看見不同訪談間的模式。", "example": "用一張共用表格，每次訪談一列：對象、日期、描述的過去事件、原話、支持或反駁的假設、後續事項。在每次通話後一天內、細節還清楚時填寫。", "avoid": "避免到最後都只靠記憶或零散筆記，讓細節模糊成一般印象。", "synthetic": true}}, "f606ce05f3264361": {"question": "我們的問題是否在詢問過去行為？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "詢問過去行為能帶出實際發生的事；問未來則容易得到猜測與禮貌回答。", "example": "不要問賣家會不會用上架工具，改問：「請說說上次上架一批新商品的過程。你先做了什麼？」留意日期、工具與參與者。", "avoid": "避免用「你會為這個付費嗎？」等假設問題，要求顧客預測自己的行為。", "synthetic": true}}, "1abd735a181eafe7": {"question": "我們是否要求具體例子？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "一般答案會隱藏重要細節。具體例子能以可確認的方式呈現頻率、努力與後果。", "example": "賣家說上架「總是很麻煩」時，追問最近一次：「是哪個商品？缺什麼？怎麼取得資料？」若可以，請他展示試算表或訊息。", "avoid": "避免接受「通常」「一直」等概括，而不問近期一個具體案例。", "synthetic": true}}, "4242c71608d13d53": {"question": "我們是否太早或過度介紹產品？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "太早描述產品，會讓對話轉向對你想法的反應，偏離顧客自己的經歷。", "example": "把對話時間用在賣家今日如何準備商品頁。若要提產品，也只在最後簡短提及。如果發現自己前十分鐘就在解釋功能，就把話題帶回最近一次上架。", "avoid": "避免用展示或提案開場；這會招來禮貌回饋，而不是真實過去工作的描述。", "synthetic": true}}, "38d92b707229443c": {"question": "我們是否問了引導性問題？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "引導性問題暗示你希望聽到的答案。顧客常為禮貌而同意，於是得到的證據只反映你的問法。", "example": "比較「供應商規格缺漏是不是很令人挫折？」與「上次準備商品頁時發生了什麼？」後者讓賣家有空間主動提出問題，或完全不提。", "avoid": "避免問題先說出你預期的問題或情緒，再把顧客同意算成證據。", "synthetic": true}}, "ff223885f5672954": {"question": "我們是否說得太多？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "訪談是為了聽顧客說話。訪談者占了大多數時間，筆記就主要記錄團隊自己的觀點。", "example": "通話後估計誰說得更多，或經同意回顧錄音。僅作示例：決定希望控制的大致發言比例，並記下哪些時刻你是在解釋而不是提問。", "avoid": "避免用解釋填滿沉默；短暫停頓常能讓賣家有時間補充重要內容。", "synthetic": true}}, "d742c86e4f400bd6": {"question": "我們是否針對具體事件追問？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "最有用的細節常在第一個答案之後。追問已提到的事件，能找出原因、成本與替代做法。", "example": "如果賣家提到上個月某商品延遲上架，就問延誤原因、誰處理、花多久，以及銷售計畫受到什麼影響。先停留在同一事件，再繼續下一題。", "avoid": "避免顧客剛提到值得深入的具體事件，就跳到下一個預設問題。", "synthetic": true}}, "c8234fd27a008f78": {"question": "我們是否記錄顧客原話？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "原話能保留顧客意思，也更容易之後比較。改述往往會偏向團隊預期的內容。", "example": "逐字記下說法，例如賣家如何描述追著供應商要尺寸表。在筆記中標成引言。若要錄音，先取得同意，通話中仍記下關鍵句。", "avoid": "避免團隊其他人還沒看過，就把顧客說的話改寫成產品用語。", "synthetic": true}}, "533b66e55536a83e": {"question": "哪一種顧客最願意接受訪談？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "爽快同意交談的顧客，可能最感受到問題。他們的意願本身就是值得記錄的訊號。", "example": "追蹤誰回覆邀約、回覆多快。如果常上新商品的賣家比偶爾販售的人更早回覆，就記下模式。問願意受訪的人，是否認識上架工作量相近的其他人。", "avoid": "避免假設最願意受訪的人能代表所有顧客；他們可能特別投入或好奇。", "synthetic": true}}, "61aa933f232393c0": {"question": "我們最重要的假設是什麼？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "測試瞄準能改變決策的事情時，才有用。", "example": "我們假設賣家會為減少商品頁準備時間付費。下一個測試必須研究付款，而不只是展示版本看起來好不好。", "avoid": "當不確定的是付款假設，避免測試的只是漂亮展示版本。", "synthetic": true}}, "d5d7150a9b560fb7": {"question": "哪些部分仍然只是推測？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "當問題、顧客、市場與解法已有草圖，標出推測，才能看出哪些部分沒有團隊外的資訊依據。", "example": "在各區塊標出純粹靠推理寫成的敘述。以上架構想為例，如果沒有賣家說過或做過任何支持的事，「賣家會放棄目前試算表而轉用」可能仍是推測。", "avoid": "避免把推測當成無害的填充內容；它常位於計畫最依賴的部分。", "synthetic": true}}, "157f42b4345648ef": {"question": "哪些假設應該優先驗證？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "不是每個假設現在都值得測試。排序能把有限時間放在會改變方向的假設上。", "example": "依兩點評估每個假設：計畫依賴它的程度，以及支持證據有多少。以上架構想為例，賣家是否經常遇到缺欄位，可能應先於偏好哪種檔案格式。", "avoid": "避免只因容易快速得到結果，就從最好測試的假設開始。", "synthetic": true}}, "ef06fcf1d83ce7f1": {"question": "哪些部分仍然是假設？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "明確寫出假設才能測試。假設一直隱含時，團隊會爭論結論，而不是底下的想法。", "example": "把每個無支持的想法改成可確認的句子：「賣家至少每月準備一次新商品頁」，或「店主做採購決策」。把它們列成與證據紀錄分開的清單。", "avoid": "避免把假設寫得像「賣家想要效率」那麼模糊，讓任何證據都無法支持或反駁。", "synthetic": true}}, "7ffb839312bc9a7e": {"question": "哪些部分仍然只是想像？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "分工與組隊時，承認哪些部分只存在想像中，有助於把任務放在查證它們。", "example": "找出依賴腦中畫面的部分：賣家開心上傳供應商 PDF，便取得完成的商品頁。問這幅畫面中哪些步驟沒有人在現實見過，並指派一人研究其中一步。", "avoid": "避免依想像的產品流程分工，彷彿顧客已經證明會照著走。", "synthetic": true}}, "8905d452dee23b35": {"question": "哪個假設一旦錯誤，就會讓這項創業構想不成立？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "有些假設承載整個創業構想。找出哪個錯了就會終止構想，才能知道投入更多努力前要先查什麼。", "example": "問：「如果這是錯的，我們會停止嗎？」以上架構想為例，決定性的假設可能是賣家準備商品頁頻繁到需要協助。如果一年只上架兩次，構想可能不成立。", "avoid": "避免把好幾個假設都說成同樣關鍵，讓團隊不必決定先測哪一個。", "synthetic": true}}, "dd31e391e2e1d7b4": {"question": "哪個假設一旦錯誤，就會讓整個商業模式不成立？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "商業模式連結顧客、價值、付款與交付。即使問題真實，一個環節斷掉仍可能讓收入無法運作。", "example": "逐步追蹤模式：賣家有問題、賣家付費、團隊以可持續成本交付。最弱的一環可能是成本：人工準備商品頁的時間，超過價格所能負擔。明確指出那一環。", "avoid": "避免只專注顧客喜不喜歡產品，忽略付款、成本與誰掌握預算。", "synthetic": true}}, "3a31e3afb91ced5b": {"question": "我們的想法背後有哪些隱藏假設？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "（由教材練習轉問句）", "audience": "團隊／個人自問", "help": {"why": "隱藏假設是大家因覺得理所當然而沒寫下的內容。它們可能默默失敗，破壞看起來合理的計畫。", "example": "把想法念出來，每句後問「要讓這成立，哪些事必須為真？」以上架構想為例，隱藏假設可能包括賣家能分享供應商檔案，或各平台上架規則相近。", "avoid": "避免只列出已經討論過的假設；這個練習要找的是被視為理所當然的內容。", "synthetic": true}}, "d6ddf8150808faf7": {"question": "如果這個假設是錯的，這個想法是否仍然成立？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "把假設與相反情況對照，能看出想法有多依賴它，幫助區分關鍵假設與小細節。", "example": "選一個假設，例如「賣家偏好上傳檔案，而不是輸入資料」。想像它是錯的。如果改用引導式表單仍能交付價值，這個假設就不如會使構想終止的假設重要。", "avoid": "避免沒有推演顧客、提供內容或交付方式實際會改變什麼，就直接回答可以。", "synthetic": true}}, "2279afc7ed02a30f": {"question": "哪些假設仍然尚未確認？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由作業指示轉問句）", "audience": "團隊檢查", "help": {"why": "一輪訪談後，有些假設仍未確定。列出它們，才能看出下一輪訪談或測試還要涵蓋什麼。", "example": "把假設清單與訪談筆記比較。例如團隊已聽到足夠多關於賣家如何準備商品頁的描述，卻完全不知道誰批准支出。把該假設標為尚未確認，並規劃相關問題。", "avoid": "避免只因訪談沒有反駁，就標成已確認；缺少反對證據，不等於得到支持。", "synthetic": true}}, "2f44d776aa353ee3": {"question": "我們最危險、最沒被證明的假設是什麼？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在產品策略中，風險最高、證據最少的假設，最容易讓過早投入開發的心力白費。", "example": "一起考量兩件事：假設錯誤會造成多大損失，以及目前的證據有多少。以商品上架服務為例，可能是假設賣家足夠信任自動產生的資料，願意不逐欄檢查就發布。", "avoid": "避免挑選風險雖高、卻已有充分證據的假設，也不要選擇雖不確定、影響卻很小的假設。", "synthetic": true}}, "aaf85984756d2e44": {"question": "這個功能要驗證哪一個商業假設？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "每項功能都應用來取得學習，或交付已經驗證的價值。把功能連到假設，才能讓產品範圍服務於決策。", "example": "在開發缺漏欄位提示功能前，先寫下要測試的假設：「賣家會在發布前補齊被標示的欄位，而不是忽略提示。」再決定哪些使用行為支持或反駁這個假設。", "avoid": "避免只因競爭者有某項功能，或覺得開發起來很有趣就做，卻沒有對應假設。", "synthetic": true}}, "be92af2d265496e2": {"question": "我們接下來準備如何驗證問題？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在構想階段，應先確認真實的人是否有這個問題，再投入時間做解法。", "example": "選一種下週要用的方法，例如請幾位小型賣家帶你回顧最近一次上架過程，或坐在一位賣家旁觀察他準備一批商品。寫下希望觀察到什麼。", "avoid": "在確認目標顧客確實有這個問題之前，避免直接做原型或登陸頁。", "synthetic": true}}, "372afd29520b5c8d": {"question": "我們能否先用人工服務、表單、簡報或簡單原型測試？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "還沒做出軟體，也能用簡單的形式測試價值。在了解有限時，這能降低學習成本並加快速度。", "example": "以商品上架服務為例，團隊可以手動替一位賣家準備商品資料、用簡單表單收取供應商檔案，或以幾張投影片展示預想流程。依照當下要測試的假設選擇形式。", "avoid": "避免認為人工或低擬真測試不專業，就直接投入開發可運作的系統。", "synthetic": true}}, "90ba4784ca7af67f": {"question": "下一步最需要驗證什麼？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第一次填寫 canvas 時，很多事情都還不確定。選出最需要驗證的一項，能避免分散心力。", "example": "檢視問題、顧客、市場與解法，選出計畫最依賴、卻仍不確定的事情。以商品上架服務為例，可能是選定的賣家是否夠常上架新品，因而在意這個問題。", "avoid": "避免把所有事情都列為需要驗證，讓團隊沒有明確的下一步。", "synthetic": true}}, "e8b3ca99993f17a1": {"question": "我們接下來要測試什麼？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "從檢視證據走到決策，必須指定一個具體測試。否則討論證據並不會改變團隊的行動。", "example": "用一句包含方法與對象的話描述測試：「訪談上個月推出新品的賣家，了解他們如何蒐集規格。」註明它要回答證據檢視中哪個尚未解決的問題。", "avoid": "避免只寫「定價」這類主題，卻沒有具體方法、對象與預期觀察。", "synthetic": true}}, "686da165d10ea5b2": {"question": "由誰負責這個測試？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "測試需要一位負責準備、執行與回報的人。明確分工能避免測試卡在不同人之間。", "example": "即使有人協助，也指定一位創辦人負責。例如一人安排賣家訪談並整理結果，另一人參與做筆記。把負責人的名字寫在測試旁。", "avoid": "避免把責任分得太散，以致沒有人覺得自己應負責完成測試並回報結果。", "synthetic": true}}, "caba9abf250b6e77": {"question": "何時完成？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "期限決定何時檢視結果與做下一個決策。沒有期限，測試往往會不斷延長。", "example": "排定測試日期，並緊接著安排檢討。假如要進行一輪賣家訪談，現在就訂好結束日，並約定屆時訪談場次不足要怎麼處理。", "avoid": "避免寫「有空的時候」這種沒有期限的安排，讓測試可以無限延後。", "synthetic": true}}, "17ae31d68e846bed": {"question": "這項工具能幫助我們驗證哪一個假設？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "問卷、訪談與原型各自適合不同假設。先說清楚假設，才能選擇真正能回答它的工具。", "example": "若假設是賣家花很多時間追供應商規格，適合訪談最近一次上架經驗。若要測試付費意願，提出付費試行方案，比滿意度問卷更合適。", "avoid": "避免因為熟悉或方便就先選工具，再回頭找它能測什麼假設。", "synthetic": true}}, "1a60a8bdbbbc02f0": {"question": "下一步行動是什麼？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "（由紀錄欄位轉問句）", "audience": "團隊檢查", "help": {"why": "每份訪談紀錄都應以具體行動收尾，讓學習連到團隊下一步。", "example": "在每份訪談筆記末尾寫一項行動與負責人，例如追問賣家能否提供供應商檔案、在訪綱加入預算問題，或邀請對方參加試行。", "avoid": "避免以「很有趣的對話」這種無法導向具體下一步的評論結束筆記。", "synthetic": true}}, "852b9166b3a8a0b5": {"question": "我們會從這個實驗學到什麼？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "實驗前先說清楚預期學到什麼，結果才有辦法解讀，也能判斷是否值得投入成本。", "example": "實驗前寫下各種結果代表什麼。例如，賣家收到人工整理的上架資料後直接發布、不需修改，表示輸出可能符合需求；若大部分欄位都要重寫，團隊學到的就是另一件事。", "avoid": "避免先做實驗，事後才決定原本想從中學到什麼。", "synthetic": true}}, "5914ef41f87fd7c4": {"question": "我們想用這個最小可行產品驗證什麼？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "最小可行產品（MVP）是學習工具。沒有明確問題，它就只是沒有目的而做出的小型產品。", "example": "寫下 MVP 要回答的問題，例如賣家是否願意提供真實供應商檔案，並發布整理好的商品資料。只保留回答此問題所需的部分，排除無關功能。", "avoid": "避免把 MVP 當成用來驚艷顧客的首版產品，而不是回答一個問題的工具。", "synthetic": true}}, "6c92ac10ceb507d5": {"question": "我們最少可以做什麼來測試它？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "較小的測試更快、更便宜，讓團隊在資源耗盡前，有更多次學習與調整的機會。", "example": "問自己這週不寫程式能做什麼。以商品上架服務為例，可以拿一位賣家的供應商檔案，替他準備一筆商品資料，觀察他是否使用。", "avoid": "避免把仍需開發數週、顧客才能回應的東西稱為小型測試。", "synthetic": true}}, "b9095bf29f8694ca": {"question": "我們能否用 Landing Page 與候補名單測試需求？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "帶有候補名單的登陸頁，可以觀察人們讀完清楚的提案後是否採取小行動，比口頭表示有興趣更有資訊。", "example": "用簡單頁面描述商品上架準備服務，請訪客加入候補名單。記錄有多少符合條件的賣家到訪、多少人登記，並聯絡登記者確認是否符合條件。", "avoid": "避免把登記等同購買意願；加入名單的成本很低，仍要透過後續對話確認興趣。", "synthetic": true}}, "1e08da1daf1ae116": {"question": "我們能否在開發功能前測試使用意願，同時清楚告知功能尚未完成？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "先測試興趣再開發，能避免投入沒人使用的功能。誠實揭露現況，才能在測量真實興趣的同時維持信任。", "example": "在訂購表單加入「產生商品照片」等選項，清楚標示尚未提供。記錄多少賣家勾選，並詢問他們的期待；坦白說明是否會推出，以及何時可能推出。", "avoid": "避免隱瞞功能尚未完成，否則會破壞信任，也讓觀察到的訊號難以解讀。", "synthetic": true}}, "aa9ee1ccb0510988": {"question": "我們能否用概念說明影片，透過預約 Demo 或預購測試興趣？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "短影片能在產品尚未存在時展示使用方式。預約展示或預購，則把被動觀看轉成可測量的行動。", "example": "錄一段短片，展示賣家上傳供應商檔案後取得整理好的上架資料，並清楚說明這只是概念。加上預約展示或可退款預購按鈕，記錄誰採取行動。", "avoid": "避免把觀看數或按讚數當成興趣；預約展示或預購才顯示願意採取行動。", "synthetic": true}}, "2fbd01d1566c0af4": {"question": "我們能否先以人工交付結果，再進行自動化？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "先人工交付，能在投資自動化前了解顧客真正需要的成果，避免自動化做錯環節。", "example": "對前幾位賣家，團隊先根據供應商檔案手動填入商品資料，記錄每個步驟耗時與容易出問題的欄位。只將反覆出現、且賣家明確重視的步驟自動化。", "avoid": "避免因人工工作看似無法擴大規模，就在尚未了解賣家重視哪些成果之前急著自動化。", "synthetic": true}}, "efcc937fe4743457": {"question": "貼身人工服務能否測試顧客是否重視這個結果？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "Concierge（明講是人工服務）（concierge）透過親自、密切地交付成果，確認顧客是否重視成果本身，而不是介面或軟體。", "example": "為一小群賣家提供親自協助的服務：團隊直接與每位賣家合作，準備下一批上架資料，事後再關心使用情況。觀察他們是否要求再次服務，或願意付費。", "avoid": "避免把禮賓式測試當成免費幫忙，卻沒有明確確認賣家是否重視成果的問題。", "synthetic": true}}, "2c9e3fc167b7dbd8": {"question": "顧客目前是否正在尋找解決方式？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客若已主動找人幫忙，代表需求正在發生。若沒有人尋找，你可能得先創造需求才能銷售。", "example": "問賣家上次商品上架準備落後時嘗試過什麼：搜尋範本、聘請接案者，或在賣家論壇發文？記錄每次嘗試及大致時間。", "avoid": "避免把一般抱怨算成主動尋找解法。只抱怨卻從未求助的賣家，提供的訊號較弱。", "synthetic": true}}, "3903fb3ca8abfaed": {"question": "顧客是否願意為這項產品或服務付費？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "人們不願付費解決的問題可能真實存在，但無法支撐一門生意。付款是區分興趣與價值的測試。", "example": "提出小額付費服務：以明確價格替一位賣家準備接下來 20 筆商品資料。記錄誰同意、誰要求折扣、誰拒絕。此為示範；開始提出方案前先訂好價格。", "avoid": "避免只問對方未來是否願意付費。假設性的回答成本很低，要看實際付款或明確預約。", "synthetic": true}}, "c7bf03e35feb0083": {"question": "顧客是否願意採取行動解決問題？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "行動代表這個問題在顧客所有待辦事項中，優先度夠高。沒有行動，即使痛苦的問題也可能一直不被解決。", "example": "請賣家寄給你上週的商品資料試算表，讓你試著準備上架資料。他是否願意花時間找出並寄送檔案，比口頭同意更有意義。", "avoid": "避免把會議中的熱情當成行動；只計入顧客在對話結束後實際完成的步驟。", "synthetic": true}}, "948d5d5ef3ceb9dd": {"question": "顧客是否願意投入時間、金錢或其他資源解決問題？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "金錢只是承諾的一種。時間、資料存取與人力投入，也能顯示顧客願意為解決問題付出多少。", "example": "列出賣家目前的投入：每週補齊缺漏欄位的工時、兼職助理、付費試算表外掛。請他回顧最近一週，記錄實際用掉的資源，而不是估計值。", "avoid": "避免只看現金。每週投入多小時人力的賣家，也在顯示願意付出資源。", "synthetic": true}}, "967beeef1817665a": {"question": "哪一群人已經採取行動？", "sourceSection": "Customer Validation \u0026 Growth：顧客、情境與假設", "sourceRange": "來源：第四至五週第 6、9、11–12、20–22、37–38、43–44、49 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "已針對問題採取行動的族群，最可能成為早期顧客。從他們開始，能更快了解解法是否有幫助。", "example": "比較一年只上架少量商品的賣家，與每月都有新品的賣家。記錄哪一群已採取共用範本或聘人協助等替代做法，那一群更適合作為起點。", "avoid": "避免預設選最大的族群。人數多、卻尚未採取行動的區隔，可能反應最慢。", "synthetic": true}}, "b183c7441248c029": {"question": "顧客願意付出什麼承諾？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "訪談後顧客提出的承諾，最能記錄訊號強度。只有禮貌認同、沒有承諾，評價應較低。", "example": "每次對話後，寫下賣家同意的具體下一步：後續會談日期、分享商品資料樣本，或支付試行訂金。若沒達成任何約定，就如實記錄，不要提升成有興趣。", "avoid": "避免把稱讚列為承諾。「聽起來有用」或「有消息通知我」並沒有讓顧客承擔任何事。", "synthetic": true}}, "97849cabe4bd3a54": {"question": "目標顧客是否主動要求進一步了解？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "顧客不用催促就主動詢問細節，表示好奇來自他們自己。這是問題對他們重要的早期訊號。", "example": "追蹤看過簡短介紹的賣家，是否回覆詢問運作方式、需要哪些檔案或要花多久。記錄每個問題與提問者，而不是只計算瀏覽量。", "avoid": "避免把你主動追蹤的訊息算成顧客的請求；這裡只計入顧客主動提出的問題。", "synthetic": true}}, "016e8ad9c4f6e163": {"question": "顧客是否詢問正式上線時間或價格？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "詢問時間與價格，表示顧客開始想像實際購買，並依你的方案安排事情，而不只是回應構想。", "example": "簡單記錄每次賣家詢問何時開始服務或價格多少，並註明是在你提到定價之前或之後。未經提示而主動提出的問題更有份量。", "avoid": "避免含糊回答「以後再說」。提供具體日期或價格，才能觀察顧客的反應。", "synthetic": true}}, "2151f948ed9f84b2": {"question": "顧客是否願意邀請主管或決策者參與？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "把主管或預算負責人找來，會消耗顧客一部分信譽，表示他認為這個解法值得在內部討論。", "example": "若訪談的店員邀請店主參加下次通話，就記錄下來。註明誰參與、店主問什麼，以及是否約定下一個決策步驟。此為示範；事先決定是否把這種行動視為通過。", "synthetic": true, "avoid": "避免假設你正在談的人有權購買。如果他始終未讓決策者參與，交易可能停滯。"}}, "a203c80a1202eb94": {"question": "顧客是否接受付費試用？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "付費試用要求顧客在完整成果出現前先承擔小風險。願意接受，比答應免費測試顯示更強的信心。", "example": "提出兩週試行方案，以小額費用替賣家準備一個商品類別。記錄向多少符合條件的賣家提出、多少人付款。此為示範；開始前先訂好費用與邀請名單。", "avoid": "避免為了容易招募就預設免費試行。免費試用看不出顧客是否重視成果到願意付費。", "synthetic": true}}, "e7d49f57079095d6": {"question": "使用者是否願意容忍早期產品的不完整？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "問題夠痛時，早期採用者願意接受不完善之處。若使用者完全不能接受未完成版本，需求可能比預期弱。", "example": "先用共用試算表與電子郵件交付上架資料，不做精緻 app。觀察賣家是否在有人工步驟的情況下仍持續使用，並區分哪些缺點只是抱怨、哪些會讓他們完全停用。", "avoid": "避免在測試前就把產品打磨完美；對不完整版本的容忍度，本來就是要學習的事情。", "synthetic": true}}, "da191aaaca326320": {"question": "顧客是否願意簽署合作意向或訂單？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "簽署意向書或訂單，能把口頭興趣轉為書面承諾，比對話中隨口說好更難。", "example": "準備一頁文件，說明試行範圍、開始日期與價格，請表示有興趣的賣家簽署。記錄誰簽了、誰要求修改條款、誰不再回應。", "avoid": "避免把文件當成形式。如果顧客覺得簽署沒有意義，這個訊號也沒有意義。", "synthetic": true}}, "e1d872801b308649": {"question": "我們希望顧客做出什麼行動？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "具體行動比禮貌稱讚更有力。", "example": "請符合條件的賣家安排試行，或介紹能核准付款的人。記錄他們實際做了什麼。", "avoid": "避免把稱讚當成承諾。", "synthetic": true}}, "ca0cd943146853e8": {"question": "你願不願意為解決這件事情付錢？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "直接詢問，能了解顧客如何看待付款。他的回答與猶豫方式，可透露是否有預算處理這個問題。", "example": "賣家描述最近一次上架延誤後，先問以前花過多少錢處理類似工作，再問下個月是否願意付費避免重演。留意過往支出的描述，不要只聽快速答應。", "avoid": "避免把一句爽快的「願意」當成證據；追問過去付過多少，以及誰核准支出。", "synthetic": true}}, "bd8f0722c2fa170f": {"question": "我們要如何判斷結果？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在看到結果前決定判讀方式，能避免團隊把任何結果都當成好消息，讓證據確實連到決策。", "example": "開始訪談前，寫下哪些回答算是商品上架準備痛點的強證據、弱證據或反證。先與團隊共用，事後再逐次訪談依此評估。", "avoid": "避免根據測試後的心情判斷結果；先約定衡量依據。", "synthetic": true}}, "fb1f03629aa72bd8": {"question": "成功長什麼樣子？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "對成功有共同想像，才能替每個測試與功能設定目標；否則團隊可能只追求活動量，而非成果。", "example": "用顧客的角度描述成功：賣家不必手動補齊缺漏欄位，就能發布一批新品。再決定如何觀察，例如一起檢視已發布的商品頁。", "avoid": "避免把推出功能或開會定義為成功；那些是投入，不是顧客得到的成果。", "synthetic": true}}, "5b742930361023e2": {"question": "什麼數字出現時，我們會繼續？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "看到結果之前，先決定如何解讀。", "example": "此為示範：測試前先決定，需要多少符合條件的賣家在何日前預約付費試行。依你的生意訂定合適門檻。", "avoid": "避免看到結果後才決定成功門檻。", "synthetic": true}}, "d8ac28b0359f716b": {"question": "什麼數字出現時，我們會調整方向？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "先設定轉向門檻，能在證據薄弱時更容易改變方向；否則團隊往往只是出於慣性持續。", "example": "此為示範：提出付費試行前，先決定在一定期間內至少要有多少符合條件的賣家付款。寫明若低於門檻，就重新檢視顧客族群或問題，而不只是加倍努力。", "avoid": "避免看到結果後才移動門檻；事後修改的數字已無法引導決策。", "synthetic": true}}, "93af7c379b7b412a": {"question": "我們提出的方案是否具有價值？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "解法必須比顧客目前的替代做法更好才有意義。這一題在投入更多之前，確認是否真的有改善。", "example": "替賣家準備一批商品資料，並與原本流程比較。記錄他還需修改多少，以及下次是否願意再次選用你的成果。", "avoid": "避免用解法看起來多厲害衡量價值；價值在於它為顧客工作帶來什麼差異。", "synthetic": true}}, "9194e42d4b4a1a11": {"question": "顧客為什麼需要這項產品？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "了解顧客為什麼需要產品，能讓團隊持續對準真實情境，避免功能偏離原本的問題。", "example": "把需求連到具體時刻：賣家的新一批供應商貨物即將到貨，必須趕在季節促銷前上架。請賣家描述最近一次發生的情形，以及困難在哪。", "avoid": "避免用產品功能回答這題；需求來自顧客情境，不是功能清單。", "synthetic": true}}, "77566383c5ca9916": {"question": "我們提供什麼價值？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "你提供的價值，就是顧客願意付錢交換的東西。說清楚它，才能決定定價、訊息與優先開發項目。", "example": "用賣家認得的成果描述，例如貨到當天就有完整、可發布的商品資料。向賣家說明後，確認他們是否用類似的話描述好處。", "avoid": "避免把技術或功能列成價值；顧客付錢是為了在自己的生意中看得到的成果。", "synthetic": true}}, "0acea3cbed515fa1": {"question": "我們可以測試的最小解決方案是什麼？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "小而完整的成果，可能比許多尚未完成的功能帶來更多學習。", "example": "開發自動化系統前，先人工準備一位賣家的下一批商品資料，清楚說明試行包含哪些內容。", "avoid": "避免在測試成果之前就投入自動化。", "synthetic": true}}, "dfde358b0bec117d": {"question": "我們是否一定需要完整產品才能測試？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "許多假設在完整產品出現前就能測試。先把所有東西做完，會延後學習並提高犯錯成本。", "example": "先別開發上傳工具，請賣家用電子郵件寄商品照片與試算表。人工準備上架資料再回傳，在自動化之前確認他是否想要這個成果。", "avoid": "避免假設顧客只會對完成的產品有反應；早期使用者往往在意成果，而非介面。", "synthetic": true}}, "5cde4a97e57e03ba": {"question": "哪一項功能最能證明顧客是否需要這個解決方案？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "選對一項功能，比廣泛開發更能快速測試核心需求。選擇的過程也逼團隊說清楚最需要學到什麼。", "example": "比較候選功能：自動補齊缺少的規格、調整照片尺寸、撰寫標題。問自己，賣家反覆使用哪一項，最能證明他需要商品資料方面的協助。先只做那一項。", "avoid": "避免選最好做或最有趣的功能；選能回答風險最高問題的那項。", "synthetic": true}}, "3484291a2eef9be2": {"question": "這個功能在解決哪一個已被證實的問題？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "每項功能都應追溯到顧客在訪談中確認的問題。沒有這個連結的功能，往往乏人使用。", "example": "加入照片去背前，先查訪談筆記：是多位賣家都說修圖反覆造成延誤，還是只有一人順口提到？記錄哪些筆記支持這項功能。", "avoid": "避免只用單一軼事或團隊偏好合理化功能，應連到重複出現的顧客證據。", "synthetic": true}}, "352b88f2094daba1": {"question": "他們到底想完成什麼事情？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "了解顧客必須完成的任務，能讓產品對準他的工作，而不是團隊想像的畫面或功能。", "example": "逐步列出賣家的工作：蒐集供應商資料、撰寫標題、檢查必填欄位、上傳照片、發布。觀察一位賣家做一次，記錄哪些步驟最花時間或導致重做。", "avoid": "避免只描述使用者在你產品內的操作；先從無論用什麼工具都必須完成的工作開始。", "synthetic": true}}, "d3e198b82d5812db": {"question": "我們這次到底要解決哪一小段問題？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "選擇問題的一小部分，能讓下一個測試做得到、結果也能解讀。一次想解決所有問題，會模糊學到的事。", "example": "從所有上架問題中選一項，例如根據供應商表格補齊商品規格。照片與標題之後再處理，並向試行賣家清楚說明這輪包含與不包含什麼。", "avoid": "避免選擇範圍太廣的一部分，以致失敗時無法追溯到單一原因。", "synthetic": true}}, "008e10f76f3ac88a": {"question": "最少做到什麼程度，就有顧客願意付第一筆錢？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第一次付款，代表有人認為你的方案值得付錢。找出最小交付範圍，能維持小規模並加快學習。", "example": "問賣家需要收到什麼才願意為一批資料付款：可能是在約定日期前，拿到 30 筆符合商店格式的完整商品資料。人工交付，再觀察他是否付款。", "avoid": "避免在任何人付款前就加入儀表板、帳號或系統整合；這些很少決定第一次購買。", "synthetic": true}}, "806cf1c5ff1400d5": {"question": "如果這件事情明天被解決，會產生什麼具體影響？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "直接問顧客", "help": {"why": "聽顧客描述具體差異，能看出解決問題是否對日常工作有影響。模糊回答可能代表問題不嚴重。", "example": "請賣家想像貨到時上架資料就準備好了。留意具體改變：趕上週末促銷、讓助理有時間做客服。問最近哪一週會因此不同。", "avoid": "避免接受「會比較方便」等籠統回答；追問會改變哪項工作、哪一天或哪個成果。", "synthetic": true}}, "bbefb90e6c686c57": {"question": "我們的解決方案如何處理這個問題？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "投資人與顧客需要看清楚問題與解法之間的連結。兩者對不上，會削弱整份提案。", "example": "把各環節連起來：賣家因商品欄位缺漏而錯過發布時機，所以服務蒐集供應商資料，回傳完整、可上傳的商品資料。確認連結中的每項主張都有訪談證據支持。", "avoid": "避免只描述解法，卻沒有說明它排除了問題的哪一部分；連結必須明確。", "synthetic": true}}, "cf4f653cfdf4ccce": {"question": "我們提供什麼產品？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "直白說明產品，別人才知道會買到或使用什麼。描述模糊，會讓回饋與決策更困難。", "example": "寫一句賣家能複述的話：在兩天內，把供應商試算表與照片轉成可在商店發布的商品資料的服務。請賣家用自己的話重述，測試是否理解。", "avoid": "避免把產品描述成平台或生態系；說清楚顧客收到什麼、以什麼形式收到。", "synthetic": true}}, "46af06a775a529df": {"question": "我們的價值主張與現有解決方案有什麼差異？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客會拿你與目前的做法比較，包括試算表與接案者。差異必須對他有意義，而非只是聽起來新。", "example": "列出既有選擇：內部處理、聘請接案者、通用範本。問賣家各自有哪些困擾。穩定產出符合商店格式的資料可能是差異，但要向他們確認。", "avoid": "避免聲稱沒有競爭；不處理與人工工作，都是顧客已經接受的替代選項。", "synthetic": true}}, "4ff6844ca0f2db22": {"question": "能讓我們測試假設的最簡單技術是什麼？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "技術選擇應服務測試，而非反過來。最簡單的做法能更快取得答案，即使放棄成本也較低。", "example": "若要測試賣家是否想要完整上架資料，先用共用試算表、收照片的表單與人工審查。等賣家持續透過這套流程送來商品，再考慮客製軟體。", "avoid": "避免因為團隊想學某技術就選它；選最快能回答假設的做法。", "synthetic": true}}, "81c0addf8c25b513": {"question": "我們能否先用規則式系統測試需求，再投入 AI？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "簡單規則通常就能看出顧客是否想要成果。若不想要，投入 AI 只是讓沒人要的產品變得更貴。", "example": "寫固定規則，標示賣家試算表中缺漏的尺寸、材質、重量等欄位。若賣家覺得提示有用並持續回來，再評估 AI 是否能改善成果。", "avoid": "避免因 AI 聽起來厲害就從它開始；先以簡單邏輯確認背後需求存在。", "synthetic": true}}, "59ef788d3d0b7595": {"question": "我們能否先用寫死的工作流程測試需求，再建完整基礎設施？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "寫死流程能快速為少數顧客交付成果，在花數週建置可能不需要的系統前先測試需求。", "example": "寫一支程式，把某位賣家的供應商表格轉成商店匯入格式，將他的分類直接寫在程式裡。若有數位賣家持續使用，再做通用化。", "avoid": "避免在需求出現前就建置多租戶帳號、權限與擴充規模的能力。", "synthetic": true}}, "368c8f4ef43eeccc": {"question": "產品中哪些基本設計選擇必須保持一致？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "即使早期產品，也需要少數一致的基本規則，才不會讓使用者困惑。提早約定可減少產品成長時的重做。", "example": "約定幾項規則：各處使用相同欄位名稱、統一日期格式、缺漏資訊用相同措辭。寫成簡短共用筆記，每個新畫面或檔案都依此檢查。", "avoid": "避免花數週做完整設計系統；先固定那些一旦不一致就會讓使用者困惑的選擇。", "synthetic": true}}, "6c876f959825be3e": {"question": "我們是否一直延後測試、文件或量測？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "早期速度很重要，但什麼都延後會留下隱性負擔。沒有基本追蹤，就無法知道顧客是否使用你做的東西。", "example": "列出團隊暫時省略的項目：自動化測試、環境設定筆記、使用追蹤。決定哪些現在保留最小做法，例如記錄賣家提交的每批商品，以及何時重新處理其餘項目。", "avoid": "避免把使用追蹤完全延後，否則之後無法回答使用情況與留存問題。", "synthetic": true}}, "a8afdf0ac12c9b4f": {"question": "我今天可以到哪裡找到這些顧客？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "知道顧客原本聚集在哪裡，才能判斷是否接觸得到人。找不到對象，再好的構想也難以測試。", "example": "列出具體場所：社群平台的賣家群組、電商平台論壇、在地商家聚會、服務小店的供應商。本週實際接觸其中兩處，記錄能聯絡到多少符合條件的賣家。", "avoid": "避免只回答「網路上」或「社群媒體」；指出具體可接觸的社群、活動或人。", "synthetic": true}}, "7ea4e064b15a2a56": {"question": "哪一群顧客最容易接觸？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "早期學習仰賴快速與顧客對話。最容易接觸的族群，能讓你在較短時間內進行更多對話與測試。", "example": "比較不同區隔：團隊成員已加入論壇中的賣家、透過供應商人脈認識的賣家、陌生開發找到的賣家。記錄一週內各管道帶來多少對話。", "avoid": "避免只因容易接觸就選擇沒有該問題的族群；對方符合顧客輪廓時，可接觸性才有用。", "synthetic": true}}, "cbb9ff30e57367e4": {"question": "我們能否在短時間內找到他們？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "時間會影響推進速度。若接觸顧客要花數月，團隊可能還沒學到東西就耗掉時間與精力。", "example": "設定短期間，例如接下來十天，規劃這段時間能聯絡誰。此為示範：先決定想約到多少場賣家對話，再比較計畫與實際結果。", "avoid": "避免把接觸顧客留到以後；能否近期接觸到人，本身就是計畫是否實際的一部分。", "synthetic": true}}, "aa037480add09669": {"question": "哪一類顧客的回覆率最高？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "回覆率顯示哪個族群覺得問題與自己相關到值得回應，能幫助決定有限時間該放哪裡。", "example": "向兩群賣家傳送相同的簡短訊息，例如服飾賣家與居家用品賣家。記錄各群聯絡多少人、多少人回覆，再比較。", "avoid": "避免比較收到不同訊息的族群；一次只改一項，才能看出什麼促成回覆。", "synthetic": true}}, "c3682203cbc51b08": {"question": "哪一個顧客取得管道成本最低？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "獲客成本決定成長能否負擔自身成本。提早了解，能避免放大每增加一位顧客就虧錢的管道。", "example": "追蹤各管道投入的時間與金錢：論壇發文、供應商轉介、小額廣告。記錄各管道帶來多少符合條件的賣家，用成本除以人數來比較。", "avoid": "避免只計金錢；創辦人在管道投入的工時也是成本。", "synthetic": true}}, "85ddfe10e09164cc": {"question": "哪一種邀請訊息的回覆率最高？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "邀請訊息往往是顧客第一次接觸你。小幅用字差異就可能改變誰會回覆，進而影響後續學到的一切。", "example": "寫兩版：一版直接指出問題，例如發布前補齊商品資料；另一版邀請對方聊聊上架工作。分別寄給條件類似的賣家，記錄各版回覆情況。", "avoid": "避免用太少訊息判斷措辭好壞；等每版都接觸足夠人數再比較。", "synthetic": true}}, "ee914defe2121043": {"question": "訪談對象是否願意介紹其他潛在顧客？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "受訪者介紹同行，表示他願意為問題的相關性背書。轉介也能讓招募更快、更省成本。", "example": "每次訪談結束，問對方是否認識也為上架準備所困的賣家。記錄多少人提供名字，以及多少次介紹真的成為對話。", "avoid": "避免把「可以跟某人提一下」等模糊提議算進去；只計入實際促成聯絡的介紹。", "synthetic": true}}, "41c5e60512f9bba1": {"question": "我們的訪談邀請回覆率與完成率是多少？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "回覆率與完成率能顯示招募在哪一步出問題。回覆多但完成少，與很少人回覆，需要不同調整。", "example": "每週追蹤三個數字：發出多少賣家邀請、收到多少回覆、完成多少訪談。若回覆多卻很少出席，可縮短請求內容或提供更彈性的時段，讓忙碌賣家容易參與。", "avoid": "避免只追蹤完成的訪談；沒有前面各步的人數，就無法判斷哪一步需要改善。", "synthetic": true}}, "8ffeafb5f13c5b7a": {"question": "我們的顧客介紹率是多少？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "轉介率顯示顧客是否重視產品到願意推薦，也可能成為低成本獲客管道。", "example": "記錄每位經既有試行賣家推薦而來的新賣家，以此人數除以同期間的活躍試行賣家人數，並記下每次轉介日期。", "avoid": "避免只依賴顧客說有多喜歡產品；衡量實際發生的轉介。", "synthetic": true}}, "ab5db194c4df06ea": {"question": "有多少比例的使用者完成核心任務並再次使用？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "完成一次核心任務並再次回來，表示初次體驗交付了足夠價值。只有註冊無法顯示這點。", "example": "定義核心任務，例如賣家上傳供應商表格並發布回傳的上架資料。記錄多少新賣家完成，以及多少人在指定期間內帶另一批商品回來。", "avoid": "避免用登入或建立帳號衡量啟用；這些都發生在顧客取得價值之前。", "synthetic": true}}, "ab04d74c83667b21": {"question": "最重要的一至兩條使用者旅程是什麼？", "sourceSection": "Product Strategy：Problem、結果、驗證與產品範圍", "sourceRange": "來源：第七週第 8、11–16、19–20、26、28、31、46、52–53 頁。\n\n\n直接問顧客（第 31 頁）：\n\n\n最後一題在教材中明確安排於理解問題之後；不把口頭願付費等同實際付款。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "專注一到兩條使用旅程，能避免小團隊分散心力。產品必須在這些路徑運作良好。", "example": "選出最重要的旅程：賣家寄出供應商資料，再收到完整上架資料。第二條可能是修正回傳資料。將各旅程寫成步驟，從頭到尾測試。", "avoid": "避免把每項功能都列為旅程；若什麼都重要，就沒有一項得到足夠關注。", "synthetic": true}}, "c91c992c4c2bc4fc": {"question": "使用者什麼時候第一次真正感受到產品價值？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "註冊不等於取得價值。", "example": "賣家不需修正缺漏資訊，就發布整理好的商品資料。確認這是否是對他有意義的時刻。", "avoid": "避免把建立帳號當成顧客取得價值的證據。", "synthetic": true}}, "ae0d82b1ca4d8a64": {"question": "從註冊到第一次感受到價值之間，我們可以縮短哪些步驟？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "取得價值之前的每個步驟，都是使用者可能放棄的地方。移除不必要步驟，能讓更多人抵達重要時刻。", "example": "寫出從註冊到第一筆商品資料準備好的所有步驟：建立帳號、連接商店、上傳檔案、選擇範本。問哪些能略過或稍後再做，例如第一批完成後才連接商店。", "avoid": "避免只是增加新手導覽畫面來解釋冗長流程；能縮短流程本身就縮短。", "synthetic": true}}, "fdbca3373e454a91": {"question": "使用者是否在沒有提醒的情況下再次使用？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "主動回來可能顯示持續出現的價值。", "example": "觀察賣家是否在沒有追蹤訊息的情況下送來第二批商品。記錄實際事件，不要只由滿意度推論。", "avoid": "避免把提醒後回來，算成未經提醒而主動回來。", "synthetic": true}}, "0dbd6d3dc2437f11": {"question": "使用者第一次試用後是否有回來？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "第一次試用後再回來，表示價值可能足夠真實、值得重複使用。只用一次可能只是好奇，而非需求。", "example": "每位賣家完成第一批試行後，記錄他是否未經提醒就提交下一批。對每位試行賣家記下第二批日期，或如實記錄沒有收到。", "avoid": "避免把你提醒後的回訪算進來；那顯示你的追蹤努力，而非顧客需求。", "synthetic": true}}, "326bd370e163acd0": {"question": "我們的使用模式顯示了什麼？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "使用模式顯示顧客如何把產品放進工作中。時間與頻率可以確認或挑戰你對問題的假設。", "example": "檢視賣家何時提交商品批次：只在季節促銷前，還是每週穩定提交？畫出每位賣家的提交日期。季節性模式可能改變服務定價與支援人力安排。", "avoid": "避免只看總量；平均值可能掩蓋大部分活動都由少數重度使用者貢獻的情況。", "synthetic": true}}, "dc7574ea38b33f7b": {"question": "如果使用者正在離開，我們應該重新檢查問題、需求或價值主張的哪些部分？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "使用者離開時，原因可能在更上游的問題本身，而不是缺少功能。回頭檢視能避免修錯地方。", "example": "若賣家用完一批就停止，問發生什麼變化。也許他很少上架，或缺漏資料來自你無法接觸的供應商。回查訪談筆記，決定重新測試哪個假設。", "avoid": "避免看到流失就立刻加功能；先確認原本的問題是否夠頻繁、夠痛。", "synthetic": true}}, "51a68ddfbb7d30d9": {"question": "我們的留存率是多少？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "留存率整理出顧客是否隨時間持續取得價值，是產品解決反覆出現問題的明確訊號之一。", "example": "依開始使用的月份將賣家分組，記錄各組在之後每個月至少提交一批商品的比例。此為示範：事先決定採用哪段期間作為留存觀察窗口。", "avoid": "避免沒有固定時間窗口就計算留存率；否則不同群體無法比較。", "synthetic": true}}, "a675c3d0a3b643e0": {"question": "我們的試用轉換率與付費轉換率是多少？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "試用與付費轉換顯示興趣在哪裡變成承諾，幫助判斷該改善方案還是試用體驗。", "example": "記錄多少賣家開始試用、多少完成、多少之後付費處理一批商品。分開追蹤這些人數，才能看出哪一步流失最多。", "avoid": "避免把試用與付費轉換合成一個數字；兩者指向不同的待解問題。", "synthetic": true}}, "e8a48bec8f9e840d": {"question": "使用者點了哪裡？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "點擊資料顯示使用者注意哪裡、在哪裡困惑，可能揭露訪談中從未提及的問題。", "example": "記錄上架工具主要畫面上的點擊，例如上傳、預覽、編輯欄位。檢查賣家是否反覆點擊不能互動的地方，或完全略過預覽。", "avoid": "避免沒有問題就追蹤所有點擊；加入追蹤前先決定要學到什麼。", "synthetic": true}}, "e2c1bc7c8c4c3224": {"question": "他們使用了哪些功能？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "知道哪些功能被使用，能看出顧客在哪裡找到價值，幫助決定改善什麼、停止維護什麼。", "example": "記錄賣家每次使用功能的情形：批次上傳、缺漏欄位提示、標題建議。數週後列出每位賣家至少用過一次的功能，以及只在展示時出現的功能。", "avoid": "避免只依賴使用者說自己用了什麼；實際使用往往與描述不同。", "synthetic": true}}, "d87da2c7c56d7763": {"question": "他們在哪一步離開？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "使用者退出的步驟，顯示流程在哪裡沒幫上忙，也告訴你修正流程時先查哪裡。", "example": "記錄主要旅程各步：開始上傳、檔案接受、預覽資料、匯出資料。計算到達各步的賣家人數，找出相鄰步驟中最大跌幅。", "avoid": "避免只根據抱怨猜退出點；測量每一步，讓資料指出真正的落差。", "synthetic": true}}, "be3dfed046130fa0": {"question": "哪些功能被大量採用？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "廣泛被採用的功能通常指向核心價值，顯示產品變動時應保護與強化什麼。", "example": "依每週使用各功能的活躍賣家人數排序。若多數使用缺漏欄位提示，卻很少使用標題建議，可考慮以欄位提示為產品核心。", "avoid": "避免把單一重度使用者當成廣泛採用；確認有多少不同顧客使用該功能。", "synthetic": true}}, "f4338f46ae7d3102": {"question": "哪些功能沒有人使用？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "沒人用的功能會增加維護成本，也讓產品雜亂。找出它們，有助移除干擾並檢討背後假設。", "example": "經過指定期間後，列出沒有任何活躍賣家使用的功能，例如沒人開啟的範本庫。決定移除前，先問幾位賣家是否知道它存在。", "avoid": "避免因為曾投入開發心力，就保留沒人用的功能；過去投入不是保留理由。", "synthetic": true}}, "b04051277b59b241": {"question": "我們的轉換率是多少？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "轉換率顯示每個階段是否有效引導人們取得價值或付款，讓漏斗可以測量，而非只靠個別故事。", "example": "先定義階段，例如到訪頁面、索取樣本、收到上架資料、付款。針對同一群賣家、同一期間，記錄各階段人數。", "avoid": "避免引用轉換率卻不說明連接哪兩個階段；沒有定義，數字就沒有意義。", "synthetic": true}}, "5875a39fd8e4aee5": {"question": "我們的錯誤率是多少？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "錯誤很快會破壞信任，對要發布到營運中商店的賣家尤其如此。追蹤錯誤能看出品質問題是否正在趕走使用者。", "example": "記錄每次上傳失敗、匯出被拒，以及賣家必須手動修正的商品資料。計算每批錯誤數，每週檢視最常見原因。", "avoid": "避免只計系統崩潰；從賣家角度看，錯誤或不完整的商品資料也是錯誤。", "synthetic": true}}, "122e852db49700ab": {"question": "我們要如何創造營收並成長？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "營收與成長相連。若賺錢方式無法隨顧客增加而擴大，就會限制事業能走多遠。", "example": "假設賣家按整理好的商品筆數付款，寫下營收如何增加：同一賣家更多商品、更多賣家，或兩者兼有。再註明目前實際看過賣家走哪條路。", "avoid": "避免只回答營收目標，卻沒有說明會產生營收的顧客行為。", "synthetic": true}}, "28b59453ed4b3f79": {"question": "我們的收入是否可重複？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "一次性付款會迫使你每月尋找新買家。可重複營收則顯示顧客是否會為相同價值再次付款。", "example": "記錄多少試行賣家不需催促就為第二批商品付款。此為示範：先決定兩個月內多少次回購，才算對你而言可重複的模式。", "avoid": "在第二次付款發生前，避免把賣家承諾持續使用算成重複營收。", "synthetic": true}}, "61a4d50ec12c5df4": {"question": "我們要如何把價值轉成收入？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "替顧客創造價值，不保證你能取得其中一部分。能否取得價值，取決於誰付款、何時付款、為何種成果付款。", "example": "賣家每次推出商品都省下準備時間。決定要在交付資料時收費、按月收取使用費，或依發布商品筆數收費。問試行賣家，哪個時點付款最合理。", "avoid": "避免認為產品節省心力，顧客就自然會付款；確認付款適合放在哪個環節。", "synthetic": true}}, "0227c91eea69ebe8": {"question": "我們的免費版本本身是否提供價值？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "免費方案必須真的解決事情，才能吸引並留住使用者。沒有實質內容的免費版，既學不到東西，也帶不來轉換。", "example": "想像一個免費檢查工具，標示賣家商品試算表中缺漏的欄位。觀察他是否為真實上架工作使用並修正那些欄位，即使他從未升級。", "avoid": "避免提供只有鎖住功能的展示版，卻沒有賣家可用的成果。", "synthetic": true}}, "072f808d128e2d8b": {"question": "什麼能讓免費使用者有明確的升級理由？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "除非付費版解決免費版尚未處理的問題，否則免費使用者會繼續免費用。升級的觸發點必須具體。", "example": "免費檢查工具找出缺漏欄位，付費方案則補齊內容並整理標題格式。記錄賣家何時開始要求修正，而不只是提醒；這可能是升級時點。", "avoid": "若免費使用者從未達到用量上限，或不覺得受限，就不要只依賴用量限制促成升級。", "synthetic": true}}, "db194ed5c25b5a39": {"question": "我們是否有足夠流量支撐廣告模式？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "廣告需要龐大受眾規模才能帶來收入。小而專注的工具，可能始終達不到用廣告支付成本所需的流量。", "example": "估計上架工具目前每月有多少賣家造訪，與廣告主需要的規模比較。若差距很大，考慮直接向賣家收費。", "avoid": "避免只因向使用者收費讓你不自在，就預設選廣告模式。", "synthetic": true}}, "5917f029dc565fe9": {"question": "產品是否持續提供足以支持訂閱的價值？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "訂閱要求顧客每月付款，只有每月都取得價值，而非只取得一次，才會讓人覺得合理。", "example": "確認賣家推出新品的頻率是否高到每月都需要協助。請一位賣家展示過去幾個月的發布日期，看需求是否規律重複。", "avoid": "避免只因經常性營收很吸引人就採訂閱，而顧客需求其實只是偶爾出現。", "synthetic": true}}, "bba70bf3e15fda21": {"question": "價值是否只發生一次？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "若顧客只需要一次，訂閱會很快流失，單次或按專案計價可能更適合。", "example": "賣家可能只需一次完整商品目錄整理，之後僅有少量更新。追蹤試行賣家首次整理後是否回來，必要時將首次工作與後續工作分開定價。", "avoid": "避免把大型首次專案當成同一賣家有持續需求的證據。", "synthetic": true}}, "7df6b058ce456c5e": {"question": "什麼定價單位符合顧客的業務？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "定價若對應顧客認得的工作，就更容易理解。", "example": "比較按商品筆數付款，與按模型 token 用量付款。測試賣家能將哪個單位連到有用的成果。", "avoid": "避免用顧客無法連到價值的技術單位收費。", "synthetic": true}}, "c1148c680f66f444": {"question": "我們的商業模式是什麼？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "投資人與團隊成員需要簡短說明：誰付款、付費取得什麼、錢如何進來。否則計畫容易偏移。", "example": "一種說法是：小型賣家按批次付款，取得每次新品推出前整理好的商品資料。用一句話寫下你的版本，再標示哪些已測試、哪些仍是假設。", "avoid": "避免同時列出多種可能模式，卻沒選出現在正在測試哪一種。", "synthetic": true}}, "8e7fdb7d5e438783": {"question": "我們有哪些收入來源與收費方式？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "列出每種收入來源及收費方式，能看出定價是否對應顧客工作，以及現金如何實際進來。", "example": "分別列出收入來源，例如按筆收費、首次商品目錄整理費、月費方案。逐項註明誰付款、計價單位，以及是否已有賣家如此付款。", "avoid": "避免把規劃中的收入來源與顧客實際付款過的來源混在同一份清單中。", "synthetic": true}}, "d19766be37a192e7": {"question": "我們的毛利率是否夠高？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "毛利顯示扣除服務每位顧客的直接成本後，還剩多少。毛利太薄，成長空間就小。", "example": "針對一批商品資料，記錄人工修正工時，加上工具或模型費用。將總成本與收費比較，看還剩多少可供事業使用。", "avoid": "計算每批交付成本時，避免忽略藏在產品背後的人工工作。", "synthetic": true}}, "ac72aaaef685e68a": {"question": "我們的單位經濟是否成立？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "單位經濟檢查單一顧客是否能獲利。若一位都不成立，增加顧客只會放大損失。", "example": "選一位試行賣家，加總找到他的成本、處理他商品資料的成本，以及他支付的金額。此為示範：擴大接觸前，先決定每位賣家需達多少獲利。", "avoid": "避免只期待規模能解決負的單位經濟，卻不知道哪項成本真的會下降。", "synthetic": true}}, "4880f53aa4747347": {"question": "取得一位顧客的成本是多少？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "了解獲客成本，才能知道每位新顧客開始造成虧損之前，你能花多少錢找到他。", "example": "追蹤接觸賣家的工時與金錢，例如訊息、社群發文與通話，再除以成為付費顧客的人數。記錄每位顧客來自哪個管道。", "avoid": "避免因為沒有直接花錢，就不把創辦人的時間算進獲客成本。", "synthetic": true}}, "bc0cd6242bc68eff": {"question": "一位顧客的終身價值是多少？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "顧客終身價值估計顧客離開前能帶來多少收入，據此判斷獲客成本合理的上限。", "example": "早期賣家尚無法觀察完整使用期間，先記錄每人買過幾批、留了多久，再把任何終身價值估計明確標成之後要重看的一項假設。", "avoid": "避免用幾個月資料推估多年顧客生命週期，卻當成已知事實呈現。", "synthetic": true}}, "669e0e59441e21a9": {"question": "回收顧客取得成本需要多久？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "回收期顯示資金會在每位新顧客身上占用多久。回收太慢，會壓縮小團隊的資金可支撐時間。", "example": "假設找到一位賣家花了一定的開發工時與金錢，記錄需要幾個月的付款才能覆蓋成本，再與現金可支撐多久比較。", "avoid": "避免用營收而非毛利計算回收期，這會讓回收看起來比實際更快。", "synthetic": true}}, "413baf3ecebd56da": {"question": "我們的毛利率與顧客留存率是多少？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "毛利與留存一起看，才能知道每位顧客是否賺錢，以及是否留得夠久，讓獲利累積。", "example": "對每位試行賣家，記錄每批毛利與下個月是否回來。把兩者並列；高毛利但很快離開，與穩定回訪，代表不同情況。", "avoid": "避免其中一項很弱時，只報另一個數字。", "synthetic": true}}, "7812f3281d483297": {"question": "取得一位使用者要花多少錢？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在產品策略中，取得一位使用者的成本，可顯示哪些獲客管道值得加碼、哪些應停止。", "example": "比較接觸賣家的管道，例如賣家論壇、電商社群、既有試行者轉介。逐一記錄時間、金錢，以及多少賣家註冊並完成第一次上架。", "avoid": "避免把所有管道平均成一個數字，掩蓋真正有效的管道。", "synthetic": true}}, "780d1d9793deca51": {"question": "顧客取得成本是否低於顧客價值？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "若獲得一位顧客的成本高於他帶來的價值，每個新註冊都會讓事業更弱。", "example": "把試行賣家的兩個數字並列：引進他的成本，以及至今產生的毛利。標示哪些人已覆蓋自己的獲客成本。", "avoid": "避免用樂觀的未來價值與獲客成本比較，應看顧客已實際產生的價值。", "synthetic": true}}, "f142e7b12a64c8a6": {"question": "我們的營收、成本與單位經濟是多少？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "將營收、成本與每位顧客的經濟情況放在同一頁，能看出目前活動是否足以支撐團隊。", "example": "做一張簡單月表：商品批次營收、直接交付成本、接觸顧客成本、工具等固定成本。加一列每位賣家的獲利，將經測試取得的數字與假設放在不同欄。", "avoid": "避免展示精美試算表，卻讓人分不出假設與實際記錄數字。", "synthetic": true}}, "6e3dd5b451718ded": {"question": "我們的每位使用者平均收入與每月經常性收入成長是多少？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "每位使用者平均營收與經常性營收成長，顯示賣家是否隨時間增加支出，以及顧客基礎是否持續擴大。", "example": "每月記錄賣家帶來的經常性總營收，再除以活躍賣家人數。註明成長來自新賣家加入，還是既有賣家提交更大批商品，因為兩者指向不同下一步。", "avoid": "避免把一次性整理費算成每月經常性營收，造成成長被高估。", "synthetic": true}}, "6158fab3be1b22c1": {"question": "我們的財務預測是什麼？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "預測顯示你認為事業會如何成長，以及哪些前提必須成立。最重要的是背後假設。", "example": "預測未來一年的賣家數、每批價格、每月批次數與成本。此為示範：選擇保守與樂觀情境，在每一列旁寫出假設及測試方式。", "avoid": "避免只畫一條陡升曲線，卻不說明每個數字背後的假設。", "synthetic": true}}, "95aa48534b4b2163": {"question": "成長是否依賴增加人力？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "若每增加一位顧客就需要更多人力，成本會隨營收增加，事業就難以超過團隊產能擴大。", "example": "目前團隊人工修正商品資料，記錄一位賣家的一批資料需要幾小時。若賣家倍增就大致需要雙倍工時，成長仍依賴人力，下一個問題就是自動化。", "avoid": "避免沒有測量現在有多少人工工作，就假設未來軟體會消除它。", "synthetic": true}}, "372672bde8aca578": {"question": "成長靠產品複製、網路效應，還是靠增加人與庫存？", "sourceSection": "從 Problem 到 Team：商業模式", "sourceRange": "來源：第三週第 3、9、13–14 頁。標有「轉問句」者從原欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "成長來源決定成本。複製軟體便宜，網路效應會累積，但增加人力與庫存也會提高成本。", "example": "以商品上架服務為例，標出哪些部分幾乎可零成本複製，例如欄位檢查；哪些仍需人力，例如改寫標題。註明賣家互相介紹，是否可能產生任何網路效應。", "avoid": "若顧客並未因彼此參與而實際受益，就避免聲稱有網路效應。", "synthetic": true}}, "859a8ea0916752bf": {"question": "這件事是否讓我們更接近顧客、驗證、使用或收入？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "小團隊很容易用忙碌填滿數週。這項檢查讓心力持續連到顧客、證據、使用或營收。", "example": "重新設計儀表板之前，先問會推進這四項中的哪一項。多約三場賣家通話能讓你更接近顧客；打磨沒人看的頁面未必能。把答案寫在每項預定工作旁。", "avoid": "避免把工具設定或品牌設計等感覺有生產力的工作，未經連結就當成進展。", "synthetic": true}}, "2b4ea3108c5c89ac": {"question": "我們是否更接近一個可以持續運作的商業模式？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "若每個月仍依賴無法持續的投入，成長意義有限。這題檢查的是方向，不只是活動量。", "example": "比較試行賣家本月與上月：是否更多人付款、每批交付工時是否下降、離開的人是否減少？逐項記錄變化，不要只靠整體感覺。", "avoid": "付款與交付成本沒變時，避免只用註冊數或關注度判斷進展。", "synthetic": true}}, "f5a5f6a9a30678b6": {"question": "我們能否重複這套取得與服務顧客的方法？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "成長需要能再次奏效的流程，而非幸運成交一次。可重複性顯示能否在第一批顧客之後繼續取得更多。", "example": "寫下每位試行賣家如何被找到、開始使用、接受服務。若接下來三位能以相近投入走完相同步驟，流程可能可重複；也記下每位有哪些差異。", "avoid": "避免假設靠私人關係拿到的交易，也能在陌生人身上重複。", "synthetic": true}}, "d2cc68f71976d798": {"question": "哪些有效做法可以讓整個團隊共同使用？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "一位成員找到有效做法後，若其他人能照著做而非重新摸索，團隊就能成長更快。", "example": "某位創辦人可能有一段能讓賣家預約通話的訊息。寫下步驟與完整原文，讓另一位成員使用一週，記錄是否也帶來預約。", "avoid": "避免讓有效做法只留在一個人的腦中，其他人既無法使用也無法檢查。", "synthetic": true}}, "a0ca75f0dba03362": {"question": "我們應該把有限的時間、人才與注意力投入在哪裡？", "sourceSection": "Customer Validation \u0026 Growth：Growth", "sourceRange": "來源：第四至五週第 14–18、30、32–33 頁。除原有問句外標示轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "小團隊無法同時追所有管道與功能。決定心力放哪裡，往往是最重要的成長決策。", "example": "列出目前工作，例如接觸賣家、開發自動標題改寫、經營社群貼文。逐項記錄上週耗時與成果，保留結果較明確的一到兩項，暫停其餘。", "avoid": "避免為了不必承受停止某項工作的不適，就把心力平均分配到所有事情。", "synthetic": true}}, "60c92f964306af40": {"question": "我對這個問題有真實興趣嗎？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "早期研究問題往往緩慢又令人失望。真正的興趣，才能讓你在尚未奏效時仍持續閱讀、提問與回到問題。", "example": "假設商品資料團隊的一位創辦人發現，自己休息時也會看賣家論壇討論雜亂試算表。寫下過去一個月中，兩次沒人要求卻主動花時間處理這個問題的時刻。", "avoid": "避免根據市場聽起來多令人興奮作答；興趣會反映在已經做的事情，不只是打算做的事。", "synthetic": true}}, "ce2caae988aa6594": {"question": "我願意花一年研究這個領域嗎？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "熟悉一個領域到能看出真實機會，需要時間。願意研究一年，是測試你是否會留得夠久、真正了解它。", "example": "以商品資料事業為例，一年可能要學習電商平台上架規則、供應商資料格式、小型賣家如何規劃新品。列出會研究的主題，誠實估計每週願意投入幾小時。", "avoid": "避免還沒想像閱讀平台政策、比較試算表範本等枯燥部分，就直接答應。", "synthetic": true}}, "9985b86116f69cdc": {"question": "我願意為了驗證這個問題去接觸陌生人嗎？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "對問題的大部分學習，來自你還不認識的人。若覺得與陌生人交談做不到，就無法檢查問題。", "example": "一位創辦人可以試著傳簡訊給五位從未見過的小型賣家，詢問最近一次推出商品的經驗。留意發送時的感受，以及下週是否願意再做。", "avoid": "避免只打算依賴朋友與前同事，他們往往重禮貌勝過準確回應。", "synthetic": true}}, "1d254a13db1bd36a": {"question": "即使解決方案改變，我是否仍然在乎這個問題？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "第一個解法很可能會改變。在意問題本身，而非最喜歡的功能，才能在第一個構想失敗後繼續前進。", "example": "想像團隊發現賣家不想要自動上架工具，卻願意接受檢查清單服務。問自己，即使如此，是否仍想協助他們解決商品欄位缺漏。", "avoid": "避免把對特定 app、設計或技術的執著，當成對問題的在意。", "synthetic": true}}, "bc63c1c1ed444992": {"question": "我擅長什麼？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "你的強項影響你能深入研究哪些問題，以及能獨力承擔哪些工作。提早了解，有助選擇合適角色。", "example": "在商品資料團隊中，有人擅長整理試算表，有人擅長寫清楚的商品文案，也有人擅長安撫壓力大的顧客。問兩位曾合作的人，他們會優先把什麼工作交給你。", "avoid": "避免只列職稱或工具；描述實際做好過、也能再做一次的事。", "synthetic": true}}, "434e023caa94b179": {"question": "我關心哪些問題領域？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "從原本就在意的領域出發，能先有較廣的選擇，而不是過早鎖定單一構想。", "example": "創辦人可能列出持續注意的小型網路零售、供應商溝通、商品攝影。寫三到五個領域，再為每個領域補上一個近期看見有人遇到困難的情境。", "avoid": "若沒有個人興趣牽引，避免只列聽起來熱門或容易募資的領域。", "synthetic": true}}, "6d427eb63c6c4cbf": {"question": "我現在感興趣的是真實痛點，還是只是有趣的想法？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "有趣的構想可能令人興奮，卻沒有解決任何人的迫切需求。區分兩者，能避免做出只有自己覺得聰明的東西。", "example": "會寫詩意商品標題的 AI 工具可能是有趣構想；賣家因供應商規格缺漏而延後上架，則是痛點。註明哪一個能用真實過往事件描述。", "avoid": "避免用自己多享受解釋構想來判斷；喜歡概念，不等於有痛點證據。", "synthetic": true}}, "363153a61f4296a3": {"question": "我現在最害怕的是什麼？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "恐懼會默默影響決策，例如逃避訪談或延後測試。說出恐懼，團隊才能安排如何面對，而非被它牽著走。", "example": "商品資料團隊的一位創辦人可能承認，怕被賣家拒絕、失去積蓄，或在前同事面前顯得可笑。寫下恐懼，再寫一個本週能讓自己較容易面對的小步驟。", "avoid": "避免回答什麼都不怕；這通常表示還沒仔細看自己的恐懼。", "synthetic": true}}, "92f7452014ce9592": {"question": "我能否把失敗視為資訊，而不是個人挫敗？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "許多早期測試不會如願。把失敗視為資訊，才能持續學習，而非隱藏結果或太早放棄。", "example": "假設十位賣家都拒絕試行。把這當成資訊的創辦人會詢問他們說了什麼、整理原因，再調整下一個測試。回想最近一次挫折，記下從中學到什麼。", "avoid": "避免未檢視過去面對真實挫折的反應，就承諾自己能冷靜面對失敗。", "synthetic": true}}, "0439513ba4f2d75a": {"question": "我在哪些領域比一般人更容易理解問題、找到顧客或取得資料？", "sourceSection": "從 Problem 到 Team：Problem、Customer、Market、Solution", "sourceRange": "來源：第三週第 17、21、23、25–26、32–34 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在了解領域、接觸顧客或取得資料上已有他人沒有的起步優勢，能讓早期學習比外行人更快、更便宜。", "example": "曾經營小型網店的創辦人，可能熟悉賣家社群、了解平台上傳規則，也仍保有舊商品試算表。列出你能在一週內聯絡十位相關人士的領域。", "avoid": "避免把尚未實際使用的人脈當成優勢；先測試他們是否真的回覆。", "synthetic": true}}, "8433e62be1f0c31d": {"question": "我真的在乎這個問題嗎？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "組隊時，每個人對問題的在乎程度，會決定他願意投入多少心力。這個檢查要先由個人完成，再成為共同的討論。", "example": "在答應加入商品上架資料團隊之前，每位創辦人可以用一句話寫下：賣家的商品上架問題，為什麼對自己有意義？接著把句子唸出來，留意誰的回答具體、誰的回答模糊。", "avoid": "不要因為其他創辦人很熱情就回答願意。他們的在乎不等於你的在乎。", "synthetic": true}}, "d5cb586e94adc523": {"question": "我願意花時間了解這群顧客嗎？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊只能服務自己了解的顧客。願意了解這群特定顧客，比對創業普遍有興趣更重要。", "example": "對小型電商賣家而言，了解顧客可能包括觀察某人準備一批上架商品、加入賣家社群，以及閱讀他們對平台的抱怨。每個人可以說明，未來兩週願意花多少小時做這些事。", "avoid": "不要把了解顧客當成某一位隊友的工作，其他人只負責開發或規劃。", "synthetic": true}}, "9d06bff33197fe4e": {"question": "我願意訪談陌生人嗎？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "訪談是團隊共同的工作，不是最外向那個人的任務。每位成員都要決定自己是否願意參與。", "example": "在商品上架資料團隊裡，每位創辦人可以承諾至少進行兩場賣家訪談，再彼此比對紀錄。不自在的人可以先在別人的訪談中做筆記，再自己主持訪談。", "avoid": "不要讓某位隊友包辦所有訪談，其他人只聽賣家說了什麼的摘要。", "synthetic": true}}, "27245f55339cd106": {"question": "即使原始方案被否定，我還願意留下來嗎？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊經常因為某個解法而組成。如果那個解法被否定，只為了它而加入的成員可能離開，讓工作停滯。", "example": "假設賣家否定了原先規劃的商品上架編輯器，卻說出另一個供應商資料的問題。每位創辦人可以寫下：自己是否願意留下來處理那個問題，以及什麼情況會讓自己離開。", "avoid": "不要替整個團隊回答。每個人都說出自己的答案，必要時先私下寫下來。", "synthetic": true}}, "6f6176b896e86f1d": {"question": "我相信這個問題值得研究嗎？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "研究一個問題要花上數週心力。相信這個問題值得投入，才會讓每位成員願意做那些不光鮮的研究工作。", "example": "一位創辦人可以向隊友說明，為什麼小型賣家缺少商品資料的問題，值得花三週研究，以及什麼發現會讓她停止。彼此比對每個人的理由是否站得住腳。", "avoid": "不要把相信問題值得研究，混同於相信問題已被解決或已獲確認。", "synthetic": true}}, "4613b38c402b5d51": {"question": "為什麼這位創辦人或這個團隊適合處理這個問題？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（由 Founder fit 欄位轉問句）", "audience": "團隊／個人自問", "help": {"why": "投資人、合作夥伴與早期顧客想知道：為什麼是這個團隊，而不是另一個團隊，能夠了解並妥善解決這個問題？", "example": "對商品上架資料的創業案而言，團隊適合的理由可以結合：某位創辦人多年經營小店的經驗、一位曾做過試算表匯入工具的工程師，以及能接觸賣家社群的管道。每項主張都附上證據，例如過去的作品或聯繫對象。", "avoid": "不要只列熱情或努力這類任何團隊都能在沒有證據時宣稱的特質。", "synthetic": true}}, "f5aaa8c729a363bf": {"question": "我能夠提供什麼貢獻？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊適合度也包含某個人願意且有能力負責的具體工作。", "example": "我可以招募五位合適的賣家，並整理訪談紀錄。這是一項提出的承諾，不是已完成的工作。", "avoid": "不要只說出一項技能，卻不負責一項具體任務。", "synthetic": true}}, "0f29829a4f215f93": {"question": "團隊還缺少什麼角色？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "團隊缺少的能力會變成工作上的缺口。提早看見，才能在它阻礙進度前，透過招募、學習或規劃來處理。", "example": "商品上架資料團隊可能有產品與工程能力，卻沒有人擅長向店主銷售。寫下未來三週需要的角色，標出每個角色由誰負責，並圈出還沒有人負責的部分。", "avoid": "不要假設之後自然會有人補上缺少的角色，卻不說明是誰、何時補上。", "synthetic": true}}, "d374d58f4c0d52fa": {"question": "我可以負責什麼角色？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "承擔責任表示對成果負責，不只是幫忙。清楚知道自己能負責什麼，團隊才知道可以在哪些事上依靠你。", "example": "某位創辦人可能說，她能負責未來三週的賣家招募，包括邀約訊息與時間安排。寫下你要負責的角色，以及這個角色做到什麼才算完成。", "avoid": "不要提議什麼都幫一點忙。每項任務都由大家共同負責，通常等於沒有人真正負責。", "synthetic": true}}, "ce59dc7f84d85d41": {"question": "我最適合扮演什麼角色？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "你接下的角色，與最適合你的角色可能不同。適合程度會影響工作品質，以及你能持續做多久。", "example": "在商品上架資料團隊裡，一位創辦人也許會寫程式，但她最擅長的工作是整理訪談證據。比較哪些任務讓你忙了一整天之後仍有精神，哪些讓你耗盡心力，再據此選擇。", "avoid": "不要挑頭銜最亮眼的角色，而應選擇符合自己真正優勢的角色。", "synthetic": true}}, "315dade60eb1f6b0": {"question": "我希望找到什麼樣的隊友？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "知道自己需要什麼樣的隊友，才能有目的地招募；也能看出某個人雖然相處愉快，卻沒有補上真正缺少的能力。", "example": "商品上架資料創業案的創辦人，可能需要一位能與店主談預算、每週有十小時可投入的人。依序寫下你需要的技能、可投入時間與態度。", "avoid": "不要只找想法與工作方式都和你一模一樣的人，否則同樣的缺口會繼續存在。", "synthetic": true}}, "761da01d5eeab5f8": {"question": "我們是否具備不同但互補的能力？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "成員彼此相似的團隊，會重複相同的盲點。互補的技能讓團隊能兼顧研究、開發與銷售，而不把負擔全壓在一個人身上。", "example": "把每位創辦人最擅長的兩項技能寫在看板上。在商品上架資料團隊裡，如果每個人都寫程式開發，就表示團隊缺少訪談賣家及進行銷售對談的人。", "avoid": "不要把不同本身當成互補。不同的技能只有在工作確實需要時，才有幫助。", "synthetic": true}}, "0c0826825dae8428": {"question": "我們要如何分配工作？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "沒有共同同意的分工，有些工作會做兩次，有些則完全沒做。清楚分工能讓進度看得見，也更公平。", "example": "以三週的 sprint 為例，商品上架資料團隊可以分成賣家訪談、市場筆記與人工試行三項工作。每項指定一位負責人與確認進度的日期，並寫在所有人都看得到的地方。", "avoid": "不要只依照會議中誰先自願就分派工作，而沒有確認技能與可投入時間。", "synthetic": true}}, "49d6699783cb27af": {"question": "誰負責研究問題與訪談顧客？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "問題研究與訪談，會產生後續每項決策所依賴的證據。沒有指定負責人，訪談就容易延後，或沒有留下紀錄。", "example": "在商品上架資料團隊裡，某位創辦人可以負責尋找賣家、安排通話與維護共享訪談紀錄。其他人參與部分通話，但由她確保每場訪談都有進行並留下紀錄。", "avoid": "不要把整個團隊列為負責人。即使有多人協助，也要選定一個負責的人。", "synthetic": true}}, "05bce37146f14dfa": {"question": "誰負責分析市場？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "市場分析讓你知道，可能有多少顧客遇到這個問題，以及還有誰在服務他們。需要有人負責，分析才會持續有依據。", "example": "對商品上架資料創業案而言，市場負責人可以列出小型賣家聚集的地方、他們已經使用的工具，以及符合目標描述的賣家數量。每個數字都註明是待查核的來源數據，還是估計值。", "avoid": "不要把市場分析交給寫 pitch 的人就算了，這經常讓分析變成沒有來源、只求亮眼的數字。", "synthetic": true}}, "0262a0c37050f11f": {"question": "誰負責設計與開發產品？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "設計與開發把學到的事，轉成顧客可以試用的東西。清楚的負責人能避免團隊在了解問題之前就開始開發。", "example": "在商品上架資料團隊裡，工程師可以先負責一個小型人工試行，例如用共享試算表補齊缺漏欄位，再開始寫任何軟體。由她決定要做什麼，以及什麼時候做。", "avoid": "不要讓開發者在訪談尚未顯示賣家實際需要什麼之前，就開始完整開發。", "synthetic": true}}, "e1cd1d87be16f6ab": {"question": "誰負責視覺設計與行銷傳播？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "團隊如何介紹自己，會影響賣家是否回應。視覺設計與訊息需要負責人，才能讓邀約與 pitch 素材保持一致。", "example": "對商品上架資料創業案而言，某位創辦人可以負責邀約訊息、一頁簡單的試行說明，以及上架內容修改前後的範例。追蹤哪種用語能讓更多賣家回覆。", "avoid": "不要把視覺與訊息留到 pitch 前一晚才處理，此時沒有人有時間拿去向顧客測試。", "synthetic": true}}, "6f3749fb87b2ccf2": {"question": "誰負責銷售與商務開發？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "必須有人請顧客做出承諾，無論是參與試行、付款，還是介紹他人。沒有銷售負責人，興趣很少會變成行動。", "example": "在商品上架資料團隊裡，銷售負責人可以追蹤已訪談的賣家、提出付費試行，並了解誰能核准支出。她記下每位賣家的回應，也包括拒絕。", "avoid": "不要假設好產品會自己賣出去，也不要認為一定要等產品完成才能開始銷售。", "synthetic": true}}, "fcc580180d3d7a37": {"question": "誰負責專案管理與提案溝通？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "專案管理者讓截止日期、紀錄與決策集中在同一處；也需要有人向導師、評審或合作夥伴清楚說明提案。", "example": "對商品上架資料團隊而言，某位創辦人可以主持每週進度確認、維護任務看板，並準備最終提案。她向其他人收集證據，而不是自己寫完每一節。", "avoid": "不要只因為某個人其他工作最少，就把這個角色交給他，而沒有確認他能否清楚溝通。", "synthetic": true}}, "266573447281464d": {"question": "角色與負責人是否清楚？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "模糊的角色會讓任務遺漏，也讓不滿默默累積。每個角色都有清楚的負責人，大家才容易知道該問誰，以及由誰負責。", "example": "為商品上架資料團隊做一張簡單表格，列出各角色、負責人與本週預期產出。請每位創辦人複述內容，並確認不需要修改。", "avoid": "不要停在會議中的口頭共識。沒有寫下來，每個人記住的內容就會不同。", "synthetic": true}}, "eda328c92eb45b4e": {"question": "每位成員是否都有具體任務？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "沒有具體任務的成員，會逐漸疏離或等待指示。具體任務讓每個人都能參與，也讓進度可以量測。", "example": "在商品上架資料團隊裡，具體任務可以是週五前訪談三位賣家，或週三前寫好試行方案。確認每位成員的任務都有交付物與日期。", "avoid": "不要使用「協助研究」或「支援行銷」這類在週末無法檢查是否完成的任務描述。", "synthetic": true}}, "1892e108c2e3a84f": {"question": "誰負責邀約顧客、進行訪談與整理證據？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "訪談包含幾個步驟：找到對象、和他們交談，以及把紀錄整理成可使用的證據。任何一步沒有人負責，都可能被跳過。", "example": "對商品上架資料團隊而言，一位創辦人可以寄出邀請，第二位主持通話，第三位依問題與賣家類型標註紀錄。每一輪結束後，確認三個步驟都已完成。", "avoid": "不要進行訪談卻沒有人負責紀錄，讓證據散落在個人對話與記憶裡。", "synthetic": true}}, "7b43af1e16477fb4": {"question": "誰負責更新顧客輪廓與問題定義？", "sourceSection": "Customer Validation \u0026 Growth：訪談與訪談後的檢查", "sourceRange": "來源：第四至五週第 25–26、30、39–40、45、47–49 頁。\n\n直接問顧客：\n\n\n團隊檢查：", "editorialNote": "", "audience": "團隊檢查", "help": {"why": "訪談只有在改變團隊共同理解時才有意義。當證據有變化，需要有人更新顧客輪廓與問題定義。", "example": "完成一週賣家訪談後，某位創辦人可以修正目標描述，例如限縮為依賴供應商試算表的賣家，並註明是哪些訪談促成這項改變。", "avoid": "不要因為更新顧客輪廓感覺像在承認錯誤，就一直保留原來的版本。", "synthetic": true}}, "e9472c50960bf7bd": {"question": "團隊有哪些成員？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "讀提案的人想知道，實際做事的是誰。清楚的名單也能讓團隊知道，誰已經投入，誰只是有興趣。", "example": "對商品上架資料創業案而言，列出每位創辦人，並用一句話介紹背景，例如曾經營小店、工程師，以及零售行銷人員。只列目前實際參與工作的人。", "avoid": "不要把只給過一次建議的顧問或朋友列成團隊成員。", "synthetic": true}}, "1cef232fe71f0857": {"question": "每位成員帶來哪些專長，負責哪些工作？", "sourceSection": "Pitch 所需欄位轉問句", "sourceRange": "來源：第二週第 5 頁、第七週第 1 頁。這裡保留商業提問，刪除繳交及評分要求；這些題目由欄位轉寫，不是逐字問句。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "讀 pitch 的人會判斷團隊是否能交付成果。把每個人的專長連到一項責任，才能顯示團隊有組織，而不只是有才華。", "example": "在商品上架資料團隊裡，一位創辦人有經營小店的經驗，負責賣家訪談；另一位做過匯入工具，負責試行。把每項專長與這個人目前正在做的工作配對。", "avoid": "不要列出亮眼的過去經歷，卻和目前責任毫無關係。", "synthetic": true}}, "629eccb2e32cbdfb": {"question": "每個人每天願意投入多少時間？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "每天可投入的時間，決定團隊能多快學習。知道每個人實際可投入的每日時數，能避免計畫默默依賴某一個人撐住。", "example": "在商品上架資料團隊裡，一位創辦人也許平日晚上能投入兩小時，另一位只有三十分鐘。把數字寫下來，安排任務時配合最小且實際可行的每日時段。", "avoid": "不要以狀況最好的一天來回答。應以普通忙碌日也能持續做到的時間為準。", "synthetic": true}}, "0b89111698d07105": {"question": "我們是否願意在晚上或週末繼續工作？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "許多早期團隊要配合工作或課業安排。事先約定是否包含晚上與週末，可以避免之後感到意外或不滿。", "example": "商品上架資料團隊可以約定，平日晚上做非同步工作，週六上午一起檢視訪談。每個人都說明哪些晚上或週末無法投入。", "avoid": "不要因為某個人週末有空，就假設所有人都有空。直接問每位成員。", "synthetic": true}}, "a38ba35bce2b888e": {"question": "團隊如何做決策？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "決策往往在大家還沒準備好時就會出現。提早選定決策方式，能避免意見不同演變成拖延或傷害感情。", "example": "對商品上架資料團隊而言，可以約定各領域的負責人在自己的範圍內決策；至於要鎖定哪一群顧客，則需要三位創辦人明確同意。", "avoid": "不要在團隊沒有做出這種選擇的情況下，默認由聲音最大或資歷最深的人決定。", "synthetic": true}}, "b3d4c9b42df58fb4": {"question": "我們要如何處理意見不同的情況？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "意見不同時，清楚的處理方式能幫助團隊繼續前進。", "example": "約定由誰負責決策、要考慮哪些證據，以及何時重新檢視。不要把沉默當成同意。", "avoid": "不要把沉默當成同意。", "synthetic": true}}, "29a57578640b62fc": {"question": "我們是否對成功有共同定義？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "某個人認為成功是學習，另一個人認為是上線，還有人認為是募資。不同定義會導致不同的優先順序與挫折。", "example": "商品上架資料創業案的每位創辦人，先私下寫下課程結束時成功會是什麼樣子，例如有人付費參與試行，或做出明確的停止決定。再把答案並排比較。", "avoid": "不要使用「把它做成」這類大家都同意、卻各自定義不同的寬泛說法。", "synthetic": true}}, "33c5870b981144be": {"question": "接下來三週，我可以投入多少時間？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "三週的範圍夠短，可以精確規劃。你個人可投入的時數，決定這段期間哪些訪談、測試與草稿實際做得到。", "example": "商品上架資料團隊的一位創辦人可能查看行事曆，發現三週合計只有十二小時空檔，其中一週大多被工作占滿。請逐週寫下可投入的時數，而不只列出總時數。", "avoid": "估算可用時間時，避免忽略行事曆上已有的考試、旅行或工作期限。", "synthetic": true}}, "39b62fd12357d8d8": {"question": "我們是否在乎同一個問題？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "成員若在意不同的問題，就會把團隊帶往不同方向。共同認同的問題，能讓研究與決策保持聚焦。", "example": "在商品上架資料團隊中，一位創辦人可能在意賣家損失的時間，另一位卻在意商品照片能否更好。每個人各用一句話寫出問題，再由團隊檢查大家描述的是否是同一件事。", "avoid": "避免因為大家都喜歡同一個產品構想，就以為已經達成共識。同一個構想背後可能藏著不同的問題。", "synthetic": true}}, "592c56cb8c02b1ad": {"question": "我們是否願意面對問題可能不成立的結果？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "研究可能發現問題很小，或早已被解決。無法接受這種結果的團隊，容易忽略證據，仍然繼續開發。", "example": "商品上架資料團隊可以事先約定：如果多數受訪賣家準備商品上架只需幾分鐘，就暫停並重新思考。請在第一次訪談開始前，把這個條件寫下來。", "avoid": "避免把每一次不明確的訪談都解讀為支持。還沒看到結果前，就先決定什麼樣的結果算是否定。", "synthetic": true}}, "a8488581a90582cf": {"question": "我們對投入程度與成果標準是否一致？", "sourceSection": "從 Problem 到 Team：合作", "sourceRange": "來源：第三週第 44–48 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "投入程度與成果標準，決定大家付出多少努力，以及怎樣才算完成。這兩者不一致，是團隊衝突的常見原因。", "example": "商品上架資料團隊可以約定，例如在一天內回覆訊息，並在訪談後二十四小時內完成紀錄。以下僅為示範：決定每人每週應完成多少次訪談。", "avoid": "避免不把標準說出來，之後卻用隊友從未同意過的期待來評斷他們。", "synthetic": true}}, "0dd807049fabd788": {"question": "每個人每週可以投入多少時間？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "每週可投入的時數，能把良好意願轉成做得到的計畫。分工時，這些時數能顯示每個人實際可以完成哪些任務。", "example": "在商品上架資料團隊中，每位創辦人在自己的負責角色旁寫下每週可投入時數。如果銷售負責人每週只有三小時，團隊可能需要把後續追蹤交給其他人。", "avoid": "避免還不知道可投入時數就先分配角色，結果把最大的任務交給時間最少的人。", "synthetic": true}}, "609b07e6e9c5c333": {"question": "每個人對成果的期待是什麼？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "每個人加入的理由可能不同，例如學習、作品集，或真的成立公司。若不說出期待，成果出來時就容易失望。", "example": "商品上架資料專案的每位創辦人都可以說明自己希望獲得什麼，也許是訪談能力、能運作的原型，或課程結束後繼續做下去的機會。請記下彼此期待不同之處。", "avoid": "避免因為團隊正在做創業構想，就假設每個人都想成立一家完整的公司。", "synthetic": true}}, "763226add17f4bb9": {"question": "我們如何做決策？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "組成團隊並分配角色時，決策方式能讓每位負責人知道哪些事可以自己決定，哪些時候需要詢問其他人。", "example": "商品上架資料團隊可以寫下：任務負責人在自己的任務範圍內做決定；意見不同時，依證據進行簡短討論；若仍無法解決，由專案管理者在約定日期前決定。", "avoid": "避免每個小決定都要求所有人同意，這會拖慢團隊，也讓每個人疲憊。", "synthetic": true}}, "23c07dd5fa7c7bb8": {"question": "我們要如何處理意見不同的情況？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "清楚的處理方式，能讓團隊在意見不同時繼續前進。", "example": "約定由誰負責決策、要考慮哪些證據，以及何時重新檢視。不要把沉默當成同意。", "avoid": "避免把沉默當成同意。", "synthetic": true}}, "2f1bcc9108539a75": {"question": "我們要如何面對沒有完成任務的成員？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "任務未完成的情況總會發生。事先約定如何回應，能把它當成實際待解決的問題，而不是個人衝突。", "example": "在商品上架資料團隊中，一次未完成的訪談，可以先用簡短溝通了解原因、訂出新期限；如果再次未完成，就重新分派任務。請在第一個期限到來前，約定這些步驟。", "avoid": "避免保持沉默，然後默默自己把工作做完。這會累積不滿，也會隱藏真正的工作量。", "synthetic": true}}, "d8cfe12743f86c0b": {"question": "我們的溝通頻率與方式是什麼？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "清楚的溝通頻率與管道，能避免訊息遺失及決策散落各處，尤其當成員在不同時段工作時。", "example": "商品上架資料團隊可以用一個群組聊天處理簡短問題、用共用文件保存訪談紀錄，並在每週一通話三十分鐘。請寫明決策記錄在哪裡，讓大家不必翻找舊對話。", "avoid": "避免把決策分散在許多 App，卻沒有約定一個可以查到決定的地方。", "synthetic": true}}, "a6c88620ffdde5e9": {"question": "提案者是否願意接受不同意見？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "提出構想的人，通常也最依戀這個構想。如果他抗拒其他觀點，團隊就會停止提出有用的質疑。", "example": "在商品上架資料團隊中，提出構想的創辦人可以邀請每位隊友說出一項自己懷疑的假設，並以規劃如何查證來回應，而不是替假設辯護。", "avoid": "避免把提案者的構想視為不能改變，其他人只能協助執行。", "synthetic": true}}, "24a46f651ac93736": {"question": "成員的投入程度是否一致？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "投入程度不一致時，最投入的人會承擔大部分工作，其他人則感到壓力。檢查一致性，能及早讓這個問題浮現。", "example": "比較商品上架資料團隊各位創辦人事先承諾的每週時數，以及第一週實際投入的時數。如果一個人投入八小時，另一個人只投入一小時，就公開討論並調整角色。", "avoid": "避免期待每個人的時數完全相同。一致性指的是誠實且經過共同同意的投入程度，不是相同的數字。", "synthetic": true}}, "ac637909817b3876": {"question": "我們是否已確認投入程度與決策方式？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "這是團隊成立後的最後一次檢查，確認真正開始工作前，投入程度與決策規則已經寫下來。", "example": "第一次 sprint 開始前，商品上架資料團隊一起檢視一頁文件，列出每個人的時數、預期成果及決策方式。每位創辦人以文字確認，團隊再約定重新檢視的日期。", "avoid": "避免因為這個主題曾討論過一次，就勾選完成。達成共識，代表有一份所有人都確認過的文字紀錄。", "synthetic": true}}, "6c6567eb10870f51": {"question": "我們的團隊是否能快速行動、學習與修正？", "sourceSection": "從 Idea 到 Problem：問題與需求", "sourceRange": "來源：第二週第 9、15、17、19–20、25、27、29 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "早期創業要在時間與金錢耗盡前，靠更快的學習取得進展。循環太慢，就會減少修正方向的機會。", "example": "量測團隊從新構想到賣家測試，再到做出決定，需要多久。如果測試新的商品上架格式需要一個月，就找一個更小的測試，看能否在一週內回答同一個問題。", "avoid": "避免把開發速度和學習速度混為一談；快速交付卻不檢視結果，學到的東西很少。", "synthetic": true}}, "7fe58e2639b9e5bd": {"question": "如果想法被否定，我們是否願意調整方向？", "sourceSection": "從 Idea 到 Problem：優勢、團隊與個人", "sourceRange": "來源：第二週第 31、35、37、43–45 頁。\n\n\n三週是教材原本的反思期間；保留來源，不預設為未來網站的固定期限。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "顧客否定構想後，創辦人往往仍會替它辯護。事先同意願意改變，才能讓證據比對構想的依戀更有分量。", "example": "下一輪賣家訪談前，每位創辦人寫下：如果賣家說準備商品上架不是問題，自己會怎麼做。訪談後重新閱讀這些紀錄，再與團隊實際做出的決定比較。", "avoid": "避免把否定解釋成顧客只是還不理解這個構想。", "synthetic": true}}, "83d7791fefe7632d": {"question": "我們為什麼選擇這個方向？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "記錄選擇某個方向的理由，能讓團隊在新證據出現時，檢查這些理由是否仍成立。", "example": "寫一則簡短紀錄：我們聚焦在沒有設計師的小型賣家，因為有幾位描述自己每次新品上市前，都要反覆修正上架內容。附上訪談紀錄連結。新訪談出現時，檢查是否支持這個理由。", "avoid": "避免只記錄決定，卻沒有留下導致這個決定的證據或假設。", "synthetic": true}}, "c43a0d6e99f2b2b3": {"question": "我們為什麼放棄另一個方向？", "sourceSection": "從 Problem 到 Team：證據與決策", "sourceRange": "來源：第三週第 37、39、41–42 頁。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "被放棄的方向也包含學習。如果沒有寫下原因，團隊可能又回到同一條路，或因錯誤的理由而排除它。", "example": "假設團隊放棄商品照片編輯。記錄原因：也許賣家已經有照片工具，或交付成本太高。再記下什麼新證據，會讓這個方向值得重新考慮。", "avoid": "避免只寫「沒有用」，卻不說測試了什麼、觀察到了什麼。", "synthetic": true}}, "64ff041dd3cc79e5": {"question": "什麼情況下，我們需要修改方向？", "sourceSection": "從 Problem 到 Team：分工、組隊驗證與第一次檢查", "sourceRange": "來源：第三週第 47–60 頁；標記轉問句的題目由職責或 Canvas 欄位展開。", "editorialNote": "", "audience": "團隊／個人自問", "help": {"why": "在結果出現前先設定改變方向的條件，能避免團隊事後替不理想的結果找理由。", "example": "以下僅為示範：試行前先約定，若在指定日期前，同意付費的合適賣家人數低於你們訂定的數量，就測試不同的顧客族群。請寫下來並註明日期。", "avoid": "避免把改變方向的條件寫得模糊，例如「如果進展不順利」，這樣沒有人能檢查是否符合。", "synthetic": true}}, "6537a3b675533f75": {"question": "我們學到的東西會如何改變下一個決定？", "sourceSection": "Product Strategy：取得、啟用、留存與量測", "sourceRange": "來源：第七週第 21–24、40–41 頁。以下除取得成本與首次價值原有提問外，為敘述轉問句。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "研究應該改變你接下來的行動。", "example": "如果主要延誤來自供應商資訊不完整，就先測試這個問題，再投入圖片生成。", "avoid": "避免證據已指向其他方向，卻仍重複原先的計畫。", "synthetic": true}}, "11f748ccce111483": {"question": "不論誰的職位最高，資料說了什麼？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "小團隊中，最資深或最有自信的聲音，可能壓過證據。先看資料，能讓決策保持誠實。", "example": "決策會議前，把賣家實際做過的事，例如預約、付款、再次提交商品批次，整理在同一頁共用文件。每個人在發表意見前先讀完，決策紀錄也引用這一頁。", "avoid": "避免讓意見最強烈的創辦人在看到結果後，才決定哪些資料算數。", "synthetic": true}}, "0f289a72c7f84e61": {"question": "我們是根據未來價值，還是過去成本做決定？", "sourceSection": "Product Strategy：競爭、定價與建置", "sourceRange": "來源：第七週第 34–36、39、43、45、48–49、51 頁。明示轉問句，不把工具或技術選項當所有創業者的必答題。", "editorialNote": "（轉問句）", "audience": "團隊／個人自問", "help": {"why": "已經投入的時間與金錢無法收回。決策應取決於每個選項從現在起能帶來什麼。", "example": "團隊花了好幾週製作自動照片編輯器，但賣家很少使用。請從今天開始比較選項：接下來各要花多少成本，又能帶來什麼。不要把過去那幾週的投入放進這次比較。", "avoid": "避免主要因為已投入很多，就繼續一個專案。", "synthetic": true}}, "f1dc316b6f3da70f": {"question": "你喜歡我們的想法嗎？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "", "audience": "反例／延後", "help": {"why": "人們談到構想時通常會客氣。喜歡一個構想不需付出代價，也很難看出他們是否真的有這個問題，或是否願意行動。", "example": "請一位賣家帶你回顧最近一次新品上市：準備了什麼、缺少哪些欄位，以及修正花了多久。他們過去的行動，比對你的構想有什麼看法，更能提供資訊。", "avoid": "避免把對構想的讚美當成需求證據。", "synthetic": true}}, "3a190bc64bfa1b05": {"question": "你會不會使用？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "", "audience": "反例／延後", "help": {"why": "對未來行為的預測並不可靠。多數人為了友善而說會使用，之後卻從未使用產品。", "example": "改問賣家目前如何準備商品上架，以及曾試過什麼方法讓工作更輕鬆。之後，針對他們下一批商品提出試行，記錄他們是否真的傳送檔案。", "avoid": "避免把假設性的「會使用」計算為未來使用者，或視為需求訊號。", "synthetic": true}}, "6c4e4e9e6fa2f1ad": {"question": "你願意付多少錢？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（尚未理解價值就問）", "audience": "反例／延後", "help": {"why": "顧客還沒理解價值前就問價格，得到的會是猜測。答案反映的是問法，不是真實的付費意願。", "example": "先了解商品上架問題讓賣家付出什麼代價，例如工時或延後上市。等他們看過準備好的一批商品後，再提出具體的付費試行，記錄他們接受、議價或拒絕。", "avoid": "避免把早期談話中的假設價格，引用為顧客的付費意願。", "synthetic": true}}, "3e07881fefa4cddc": {"question": "還可以增加什麼功能？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "", "audience": "反例／延後", "help": {"why": "腦力激盪功能，會把焦點從顧客的問題移到你的解法，往往在核心價值確認前，就擴大了範圍。", "example": "詢問賣家目前商品上架工作中，哪個部分造成最多延誤，並請他實際展示。等試行顯示賣家為了哪個成果持續回來後，再討論功能構想。", "avoid": "避免向還沒使用過核心服務的顧客，蒐集功能願望清單。", "synthetic": true}}, "500a5fd4e61578e1": {"question": "你是不是覺得這個流程很麻煩？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（誘導問題）", "audience": "反例／延後", "help": {"why": "這是引導式問題。它暗示了你希望得到的答案，所以對方同意，也無法讓你了解賣家的真實經驗。", "example": "以中立方式詢問：「請帶我回顧你上一次上架新商品的過程。」留意對方描述為緩慢或重複的步驟。如果他完全沒有提到挫折，也把這點記錄為證據。", "avoid": "避免把問題寫成顧客只需要附和你的形式。", "synthetic": true}}, "dae99895abe6f43e": {"question": "App 要有哪些功能？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（不宜先於問題驗證）", "audience": "反例／延後", "help": {"why": "問題尚未確認前就決定 App 功能，等於依猜測來開發。功能應該跟著問題的證據走。", "example": "列功能前，先確認賣家是否反覆遇到欄位或標題缺漏。先手動完成一批商品，記下你實際做過哪些步驟；這些步驟能指出最初值得開發的功能。", "avoid": "避免還沒親眼看到問題發生，就先排功能 roadmap。", "synthetic": true}}, "c0ef952d29cab6c5": {"question": "網站要長什麼樣子？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（不宜先於問題驗證）", "audience": "反例／延後", "help": {"why": "還不知道顧客是誰，以及什麼能說服他們之前，很難把網站設計對。", "example": "一個簡單頁面或一則直接訊息，可能就足以向賣家提出試行。等訪談顯示賣家使用哪些問題描述與用詞後，再依這些語言設計網站。", "avoid": "避免還沒有任何一位賣家同意試用服務，就花數週做視覺設計。", "synthetic": true}}, "c745b021d7a3ae1a": {"question": "要使用哪一種 AI 模型？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（不宜先於問題驗證）", "audience": "反例／延後", "help": {"why": "模型選擇是實作細節。必須先知道顧客需要完成哪項任務，以及哪些品質重要，才能判斷。", "example": "先手動準備一位賣家的上架內容，記錄哪些步驟最耗時，例如撰寫標題或填寫規格。之後再使用賣家的真實商品資料，針對這些具體步驟測試模型。", "avoid": "避免還不知道要完成哪項顧客任務，就開始比較 AI 模型。", "synthetic": true}}, "520ecbdea25882b9": {"question": "品牌名稱應該是什麼？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（不宜先於問題驗證）", "audience": "反例／延後", "help": {"why": "取名字會讓人感覺有進展，但很少影響早期學習。顧客還不清楚時取的名字，之後可能需要改。", "example": "和賣家測試期間，先使用一個簡單的暫用名稱。等知道服務哪個顧客族群，以及他們如何描述商品上架問題後，再重新檢視品牌。", "avoid": "避免長時間爭論名稱，拖延了與那些你需要向其學習的賣家對話。", "synthetic": true}}, "2531c7cb1255a920": {"question": "Logo 要使用什麼顏色？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（不宜先於問題驗證）", "audience": "反例／延後", "help": {"why": "Logo 顏色幾乎不影響問題是否真實存在，卻占用了早期更需要投入顧客工作的時間。", "example": "暫時先不做 Logo，把時間用來聯絡經常上架商品的賣家。等有幾位賣家開始付費，而且你正準備擴大上市時，再回頭處理視覺識別。", "avoid": "避免在探索問題的階段，把 Logo 或顏色決定當成里程碑。", "synthetic": true}}, "a3bfc377f53d9bca": {"question": "最少可以做幾個功能，就算是一個產品？", "sourceSection": "教材提醒避免或延後的問題", "sourceRange": "這些不是推薦填答問題，保留是為了後續提供反例。來源：第三週第 18 頁、第四至五週第 9、27 頁、第七週第 28、30 頁。", "editorialNote": "（教材建議改問首次付費所需價值）", "audience": "反例／延後", "help": {"why": "功能數量不能定義產品。課程建議改問：顧客第一次付費前，需要先獲得什麼價值。", "example": "改問：「賣家必須收到什麼，才願意為第一批商品付費？」也許是無需修正、可直接發布的上架內容。只開發或交付能產生這個成果的部分，即使用手動方式也可以。", "avoid": "避免把功能檢查清單當成上市標準，而不是付費顧客得到的成果。", "synthetic": true}}}, "provenance": {"translationPolicy": "依 Cami 原教材的中文概念與用詞翻譯。question 是既有英文題目的繁體中文對照；help 是既有衍生示例的忠實翻譯，不宣稱為 Cami 原文。", "sourceFiles": [{"file": "Week2-9_16-從 Idea 到 Problem.md", "sha256": "fc00e81a7289f0c5c170395f41a153cc2539a91979b8b7e6df348687e425bbe8"}, {"file": "Week3-0923-Problem-to-Team.md", "sha256": "c1a5bbd60fcabcbef74ed500ea492c289fe548d6328774d26eaf878db5cdf95c"}, {"file": "Week4-5-Customer-Validation-Growth-revised.md", "sha256": "dc1a8fe4d7f8c3bd5092a13a724a813c3cebd1de53cf140a374ee3b5770cb1d6"}, {"file": "week7-10_21- Product Strategy.md", "sha256": "5ee9acf7c844239794998713d5162b2ed023ac2d9a19cf8c8df85584f2ccc3fe"}], "questionCount": 362, "derivedExamplePolicy": "Existing synthetic examples are translated, not replaced, and are not attributed as original Cami slide examples."}}};
